insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-cap-cuu-104',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-104","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nôn ra máu tươi, đi ngoài phân đen và choáng váng","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":58,"sex":"nam","patient_label":"Ông P. V. D."},"presentation":{"intro":"Phòng cấp cứu, 6 giờ sáng. Nam 58 tuổi nôn máu tươi một lượng nhiều, đi ngoài phân đen, choáng váng. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":122,"sbp":84,"dbp":50,"rr":26,"temperature_c":36.7,"spo2":95},"history":[{"question":"Nôn máu và đi ngoài phân đen từ bao giờ, lượng bao nhiêu?","response":"Nôn ra máu đỏ tươi lẫn cục khoảng hai bát trong một giờ; phân đen lỏng, dính, ba lần từ đêm qua."},{"question":"Có đau thượng vị trước đó không?","response":"Đau âm ỉ thượng vị nhiều tuần, đau khi đói, đỡ khi ăn."},{"question":"Có dùng thuốc giảm đau chống viêm, aspirin hoặc thuốc chống đông không?","response":"Uống diclofenac nhiều tuần vì đau lưng; không dùng thuốc chống đông."},{"question":"Có uống rượu nhiều hoặc có bệnh gan không?","response":"Uống rượu thỉnh thoảng; chưa từng bị bệnh gan."},{"question":"Có choáng váng, ngất, đau ngực không?","response":"Chóng mặt, hoa mắt, suýt ngất khi đứng dậy; không đau ngực."},{"question":"Có bệnh tim, bệnh thận, tiểu đường không?","response":"Tăng huyết áp, đang dùng thuốc nhưng đã ngưng vài ngày."},{"question":"Có dị ứng thuốc không?","response":"Không."},{"question":"Có tiền sử loét hoặc chảy máu tiêu hóa?","response":"Chưa từng."}],"examination":[{"group":"K","item":"Tưới máu và tri giác","finding":"Tỉnh nhưng vật vã, da niêm mạc nhợt, chi lạnh, làm đầy mao mạch 4 giây."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, ấn đau thượng vị nhẹ, không phản ứng thành bụng, không gan lách to, không tuần hoàn bàng hệ."},{"group":"K","item":"Thăm trực tràng","finding":"Phân đen, nhão, có mùi hôi đặc trưng."},{"group":"K","item":"Dấu hiệu bệnh gan mạn","finding":"Không sao mạch, không vàng da, không cổ trướng."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh đều, phổi trong."},{"group":"K","item":"Tư thế","finding":"Hạ huyết áp tư thế rõ, không ngồi dậy được."}],"investigations":[{"name":"Công thức máu, nhóm máu, thử chéo, đông máu","duration_minutes":10,"result":"Hb 6,8 g/dL (trước đó 14), tiểu cầu 210 G/L, INR 1,1; nhóm máu O dương, đã chéo 4 đơn vị."},{"name":"Ure, creatinin, điện giải, lactate","duration_minutes":10,"result":"Ure 14 mmol/L, creatinin 105 µmol/L, lactate 3,5 mmol/L, K 3,6."},{"name":"Điện tim và troponin","duration_minutes":10,"result":"Nhịp nhanh xoang; troponin bình thường."},{"name":"Nội soi dạ dày tá tràng cấp cứu trong 24 giờ sau hồi sức","duration_minutes":20,"result":"Loét hành tá tràng thành sau 15 mm, đáy có mạch máu lộ đang rỉ máu (Forrest Ib hoặc IIa)."},{"name":"Xét nghiệm tìm H. pylori khi nội soi (urease nhanh hoặc mô bệnh học)","duration_minutes":20,"result":"Dương tính."},{"name":"Chụp CT bụng có cản quang trước nội soi","duration_minutes":40,"result":"Không cần để tìm nguồn chảy máu tiêu hóa trên ổn định và không làm chậm nội soi."},{"name":"Chụp X quang dạ dày có uống thuốc cản quang","duration_minutes":10,"result":"Không phù hợp trong xuất huyết đang hoạt động."}],"choices":{"diagnosis":{"ydx":["Hội chứng Mallory-Weiss","Ung thư dạ dày chảy máu","Xuất huyết tiêu hóa trên do loét hành tá tràng (Forrest cao), sốc mất máu","Vỡ giãn tĩnh mạch thực quản do xơ gan"]},"actions":["Hội chẩn tiêu hóa nội soi cầm máu trong 24 giờ sau hồi sức","Truyền dịch tinh thể ồ ạt và truyền máu đến Hb trên 10 g/dL","Hội chẩn ngoại khoa, chuẩn bị can thiệp mạch hoặc mổ khi nội soi thất bại","Đặt sonde dạ dày rửa nước đá để cầm máu","Hoãn nội soi đến 72 giờ vì chờ ổn định hoàn toàn","Dùng ức chế bơm proton liều cao đường tĩnh mạch ngay","Truyền dịch tinh thể thận trọng và truyền hồng cầu lắng khi Hb dưới 7 g/dL (dưới 8 g/dL nếu có bệnh tim mạch), tránh dịch quá nhiều","Nhịn ăn uống, theo dõi nước tiểu và sinh hiệu liên tục","Thở oxy, hai đường truyền lớn, monitor, lấy máu và gọi máu cùng nhóm","Cân nhắc đặt nội khí quản bảo vệ đường thở trước nội soi nếu nôn máu tiếp diễn hoặc rối loạn tri giác","Cho thuốc giảm đau chống viêm để giảm đau thượng vị","Ngưng NSAID và thuốc tăng huyết áp tạm thời; xét nghiệm H. pylori"]}}'::jsonb,
  '590712df130c96fd2b87d0dfdf5bd6da403ce834758ecba68f8ea1a363c13da5'
)
on conflict (case_id) do update set
