values (
  'ngoai-cap-cuu-104',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-104","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-104-1","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị xuất huyết tiêu hóa trên không do tăng áp lực tĩnh mạch cửa của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","title":"Hướng dẫn chẩn đoán và điều trị xuất huyết tiêu hóa trên không do tăng áp lực tĩnh mạch cửa của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị xuất huyết tiêu hóa trên không do tăng áp lực tĩnh mạch cửa của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ugib-acg-2021-18648f1657f7","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/33929377/","title":"ACG Clinical Guideline: Upper Gastrointestinal and Ulcer Bleeding, Am J Gastroenterol 2021. DOI: 10.14309/ajg.0000000000001245.","organization":null,"year_version":null,"citation":"ACG Clinical Guideline: Upper Gastrointestinal and Ulcer Bleeding, Am J Gastroenterol 2021. DOI: 10.14309/ajg.0000000000001245.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ugib-ican-2019","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/31634917/","title":"International Consensus Group recommendations on nonvariceal upper gastrointestinal bleeding, Ann Intern Med 2019. DOI: 10.7326/M18-1795.","organization":null,"year_version":null,"citation":"International Consensus Group recommendations on nonvariceal upper gastrointestinal bleeding, Ann Intern Med 2019. DOI: 10.7326/M18-1795.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Vỡ giãn tĩnh mạch thực quản do xơ gan","credit":"none"},{"text":"Hội chứng Mallory-Weiss","credit":"none"},{"text":"Xuất huyết tiêu hóa trên do loét hành tá tràng (Forrest cao), sốc mất máu","credit":"full"},{"text":"Ung thư dạ dày chảy máu","credit":"none"}]},"action_options":[{"text":"Thở oxy, hai đường truyền lớn, monitor, lấy máu và gọi máu cùng nhóm","time_minutes":5,"grade":"critical","rationale":"Sốc mất máu do xuất huyết tiêu hóa trên cần hồi sức ABC ngay."},{"text":"Truyền dịch tinh thể thận trọng và truyền hồng cầu lắng khi Hb dưới 7 g/dL (dưới 8 g/dL nếu có bệnh tim mạch), tránh dịch quá nhiều","time_minutes":10,"grade":"critical","rationale":"Mục tiêu truyền máu hạn chế; bù thể tích theo huyết động."},{"text":"Dùng ức chế bơm proton liều cao đường tĩnh mạch ngay","time_minutes":5,"grade":"critical","rationale":"Giảm tái chảy máu và nhu cầu can thiệp, trước và sau nội soi."},{"text":"Hội chẩn tiêu hóa nội soi cầm máu trong 24 giờ sau hồi sức","time_minutes":10,"grade":"critical","rationale":"Nội soi sớm là điều trị quyết định."},{"text":"Nhịn ăn uống, theo dõi nước tiểu và sinh hiệu liên tục","time_minutes":5,"grade":"critical","rationale":"Chuẩn bị nội soi và đánh giá hồi sức."},{"text":"Ngưng NSAID và thuốc tăng huyết áp tạm thời; xét nghiệm H. pylori","time_minutes":5,"grade":"recommended","rationale":"Loại bỏ yếu tố gây loét, điều trị tiệt trừ sau đó."},{"text":"Cân nhắc đặt nội khí quản bảo vệ đường thở trước nội soi nếu nôn máu tiếp diễn hoặc rối loạn tri giác","time_minutes":10,"grade":"recommended","rationale":"Phòng sặc máu."},{"text":"Hội chẩn ngoại khoa, chuẩn bị can thiệp mạch hoặc mổ khi nội soi thất bại","time_minutes":10,"grade":"recommended","rationale":"Chảy máu tái phát lớn sau cầm máu cần can thiệp mạch hoặc phẫu thuật."},{"text":"Truyền dịch tinh thể ồ ạt và truyền máu đến Hb trên 10 g/dL","time_minutes":20,"grade":"harmful","rationale":"Truyền máu quá nhiều làm tăng tái chảy máu và biến chứng."},{"text":"Hoãn nội soi đến 72 giờ vì chờ ổn định hoàn toàn","time_minutes":120,"grade":"harmful","rationale":"Làm tăng nguy cơ tái chảy máu và tử vong."},{"text":"Cho thuốc giảm đau chống viêm để giảm đau thượng vị","time_minutes":5,"grade":"harmful","rationale":"NSAID làm nặng thêm loét chảy máu."},{"text":"Đặt sonde dạ dày rửa nước đá để cầm máu","time_minutes":15,"grade":"harmful","rationale":"Không có hiệu quả cầm máu, có thể gây hạ thân nhiệt."}],"teaching_explanation":"Nôn máu, phân đen và sốc cần hồi sức trước, nội soi cầm máu trong 24 giờ, kèm PPI liều cao. Ngưỡng truyền máu hạn chế (Hb dưới 7 g/dL) giảm tái chảy máu. Ngưng NSAID và tiệt trừ H. pylori để phòng tái phát."}'::jsonb,
  '01f8dcc5faff5e7d2c54bd2054e653d9a3f81cbef7432fc3ca957d73e64a1c6c'
)
