insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-cap-cuu-105',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-105","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Ngã từ thang, đau đầu, nôn và đồng tử giãn một bên","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":34,"sex":"nam","patient_label":"Anh V. M. T."},"presentation":{"intro":"Phòng cấp cứu, 14 giờ. Nam 34 tuổi ngã từ độ cao 4 mét, đập đầu xuống nền xi măng, mê rồi tỉnh, nay lơ mơ dần. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":54,"sbp":182,"dbp":100,"rr":10,"temperature_c":36.9,"spo2":93},"history":[{"question":"Chấn thương xảy ra thế nào, cách đây bao lâu?","response":"Người đi cùng kể: ngã từ thang cao khoảng 4 mét, đầu đập xuống nền, cách đây 2 giờ."},{"question":"Có mất ý thức không, sau đó có tỉnh táo không?","response":"Mê khoảng vài phút rồi tỉnh, nói chuyện được, sau đó đau đầu tăng, nôn nhiều và lơ mơ dần."},{"question":"Có nôn, co giật, chảy máu hay dịch từ tai mũi không?","response":"Nôn vọt ba lần; không co giật; chảy ít máu từ vết rách da đầu vùng thái dương trái."},{"question":"Có dùng thuốc chống đông, thuốc kháng tiểu cầu không?","response":"Không dùng."},{"question":"Có uống rượu trước đó không?","response":"Không uống rượu."},{"question":"Tiền sử bệnh, dị ứng thuốc?","response":"Khỏe mạnh, không dị ứng thuốc."},{"question":"Có đau cổ, đau chỗ khác không?","response":"Không nói được rõ do lơ mơ; người đi cùng thấy không kêu đau chỗ khác."},{"question":"Lần ăn cuối?","response":"Ăn trưa cách đây 3 giờ."}],"examination":[{"group":"K","item":"Đường thở, hô hấp","finding":"Thở chậm, không đều, thỉnh thoảng ngưng thở ngắn; có dịch nôn trong miệng."},{"group":"K","item":"Glasgow","finding":"Mắt đáp ứng đau (2), vận động co cứng bất thường (3), lời nói âm vô nghĩa (2); GCS 7."},{"group":"K","item":"Đồng tử","finding":"Đồng tử trái 6 mm không phản xạ ánh sáng, đồng tử phải 3 mm phản xạ chậm."},{"group":"K","item":"Đầu, mặt","finding":"Vết rách da đầu thái dương trái, sưng nề dưới da, không dấu hiệu nền sọ (không bầm quanh mắt, sau tai)."},{"group":"K","item":"Cột sống cổ","finding":"Chưa loại trừ gãy cột sống cổ, cần nẹp cổ."},{"group":"K","item":"Bụng, ngực, chi","finding":"Không thấy tổn thương kèm theo."}],"investigations":[{"name":"CT sọ não không cản quang ngay khi đủ điều kiện ổn định đường thở","duration_minutes":40,"result":"Khối máu tụ ngoài màng cứng thái dương trái dày 25 mm, đẩy lệch đường giữa 10 mm, xóa các bể quanh thân não, gãy xương thái dương trái."},{"name":"Đường huyết mao mạch","duration_minutes":10,"result":"6,2 mmol/L."},{"name":"Công thức máu, nhóm máu, đông máu","duration_minutes":10,"result":"Hb 14,5 g/dL, tiểu cầu 250 G/L, INR 1,0."},{"name":"Khí máu động mạch","duration_minutes":10,"result":"pH 7,31; PaCO2 52 mmHg; PaO2 68 mmHg."},{"name":"Điện giải đồ, natri máu","duration_minutes":10,"result":"Na 138 mmol/L."},{"name":"CT cột sống cổ","duration_minutes":40,"result":"Không thấy gãy."},{"name":"Chọc dò dịch não tủy","duration_minutes":10,"result":"Chống chỉ định khi tăng áp lực nội sọ và khối choán chỗ."},{"name":"Chụp mạch máu não ngay trước mổ","duration_minutes":10,"result":"Không cần, làm chậm giải ép."}],"choices":{"diagnosis":{"ydx":["Chấn thương sọ não nặng, máu tụ ngoài màng cứng thái dương trái, tăng áp lực nội sọ dọa thoát vị hồi hải mã","Tổn thương sợi trục lan tỏa đơn thuần","Máu tụ dưới màng cứng mạn tính","Chấn thương sọ não nhẹ, quan sát tại nhà"]},"actions":["Chọc dò thắt lưng để đo áp lực và giảm áp","Cho thở oxy qua mặt nạ và theo dõi vì GCS 7 còn tự thở","Kiểm soát đường thở: đặt nội khí quản có cố định cổ, thở máy, tránh thiếu oxy (SpO2 trên 94%)","An thần giảm đau, khâu cầm máu vết rách da đầu, kháng sinh, phòng uốn ván","Giữ huyết áp tâm thu từ 110 mmHg trở lên, đặt đường truyền, không hạ huyết áp","Dùng dung dịch ưu trương (manitol 0,25 đến 1 g/kg hoặc natri clorid 3%) khi có dấu thoát vị","Làm CT sọ ngay sau khi ổn định đường thở, không để chờ lâu","Truyền dịch nhược trương (glucose 5%) để bù dịch","Hội chẩn ngoại thần kinh và đưa đi mổ lấy máu tụ ngoài màng cứng khẩn cấp","Tăng thông khí ngắn (PaCO2 30 đến 35) chỉ khi có dấu thoát vị tiến triển","Nằm đầu cao 30 độ, giữ cổ trung tính, cố định cột sống cổ","Tăng thông khí liên tục để PaCO2 dưới 25 mmHg"]}}'::jsonb,
  '31e07c7e354d4a4ddade8a566643ee7fb90eaeddf67f7548839b154457b0077f'
)
