values (
  'ngoai-cap-cuu-105',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-105","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-tbi-btf-2017-021e7a89b068","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/27654000/","title":"Brain Trauma Foundation: Guidelines for the Management of Severe Traumatic Brain Injury, 4th Edition, Neurosurgery 2017. DOI: 10.1227/NEU.0000000000001432.","organization":null,"year_version":null,"citation":"Brain Trauma Foundation: Guidelines for the Management of Severe Traumatic Brain Injury, 4th Edition, Neurosurgery 2017. DOI: 10.1227/NEU.0000000000001432.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-105-2","resource_type":"other","source":"ATLS 10th Edition (American College of Surgeons), Chapter 6: Head Trauma, 2018.","title":"ATLS 10th Edition (American College of Surgeons), Chapter 6: Head Trauma, 2018.","organization":null,"year_version":null,"citation":"ATLS 10th Edition (American College of Surgeons), Chapter 6: Head Trauma, 2018.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-105-3","resource_type":"other","source":"Hướng dẫn quy trình xử trí chấn thương sọ não của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","title":"Hướng dẫn quy trình xử trí chấn thương sọ não của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","organization":null,"year_version":null,"citation":"Hướng dẫn quy trình xử trí chấn thương sọ não của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"neutral"},{"index":6,"role":"waste"},{"index":7,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Chấn thương sọ não nhẹ, quan sát tại nhà","credit":"none"},{"text":"Máu tụ dưới màng cứng mạn tính","credit":"none"},{"text":"Chấn thương sọ não nặng, máu tụ ngoài màng cứng thái dương trái, tăng áp lực nội sọ dọa thoát vị hồi hải mã","credit":"full"},{"text":"Tổn thương sợi trục lan tỏa đơn thuần","credit":"none"}]},"action_options":[{"text":"Kiểm soát đường thở: đặt nội khí quản có cố định cổ, thở máy, tránh thiếu oxy (SpO2 trên 94%)","time_minutes":5,"grade":"critical","rationale":"GCS dưới 9, thở chậm không đều; thiếu oxy làm tổn thương não thứ phát."},{"text":"Giữ huyết áp tâm thu từ 110 mmHg trở lên, đặt đường truyền, không hạ huyết áp","time_minutes":5,"grade":"critical","rationale":"Phản xạ Cushing (huyết áp cao, mạch chậm) là cố gắng duy trì tưới máu não, không hạ huyết áp."},{"text":"Hội chẩn ngoại thần kinh và đưa đi mổ lấy máu tụ ngoài màng cứng khẩn cấp","time_minutes":15,"grade":"critical","rationale":"Máu tụ có hiệu ứng khối với dấu thoát vị cần giải ép phẫu thuật."},{"text":"Nằm đầu cao 30 độ, giữ cổ trung tính, cố định cột sống cổ","time_minutes":3,"grade":"critical","rationale":"Giảm áp lực nội sọ, bảo vệ cột sống cổ."},{"text":"Dùng dung dịch ưu trương (manitol 0,25 đến 1 g/kg hoặc natri clorid 3%) khi có dấu thoát vị","time_minutes":10,"grade":"critical","rationale":"Giảm áp lực nội sọ tạm thời để cầu nối phẫu thuật."},{"text":"Tăng thông khí ngắn (PaCO2 30 đến 35) chỉ khi có dấu thoát vị tiến triển","time_minutes":5,"grade":"recommended","rationale":"Tăng thông khí kéo dài làm giảm tưới máu não."},{"text":"An thần giảm đau, khâu cầm máu vết rách da đầu, kháng sinh, phòng uốn ván","time_minutes":10,"grade":"recommended","rationale":"Điều trị hỗ trợ cho bệnh nhân thở máy."},{"text":"Làm CT sọ ngay sau khi ổn định đường thở, không để chờ lâu","time_minutes":20,"grade":"recommended","rationale":"Xác định tổn thương phẫu thuật."},{"text":"Chọc dò thắt lưng để đo áp lực và giảm áp","time_minutes":30,"grade":"harmful","rationale":"Có thể gây tụt kẹt hạch hạnh nhân và tử vong."},{"text":"Cho thở oxy qua mặt nạ và theo dõi vì GCS 7 còn tự thở","time_minutes":10,"grade":"harmful","rationale":"GCS dưới 9 cần bảo vệ đường thở; thiếu oxy làm tổn thương não nặng thêm."},{"text":"Tăng thông khí liên tục để PaCO2 dưới 25 mmHg","time_minutes":30,"grade":"harmful","rationale":"Co mạch não, giảm tưới máu, thiếu máu não thứ phát."},{"text":"Truyền dịch nhược trương (glucose 5%) để bù dịch","time_minutes":10,"grade":"harmful","rationale":"Làm phù não và tăng áp lực nội sọ."}],"teaching_explanation":"GCS dưới 9 cần bảo vệ đường thở. Tam chứng Cushing và đồng tử giãn một bên gợi thoát vị; cần giữ huyết áp, tránh thiếu oxy và hạ huyết áp, đầu cao 30 độ, dung dịch ưu trương cầu nối, và mổ giải ép khẩn. Không chọc dò thắt lưng khi có tăng áp lực nội sọ."}'::jsonb,
  '3a5a36a7c5e494af5491c863262aee8e6291801b93e92882432e38d9afbb5629'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-cap-cuu-106',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-106","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Tai nạn giao thông, yếu liệt hai tay và hai chân","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":30,"sex":"nam","patient_label":"Anh Đ. H. K."},"presentation":{"intro":"Phòng cấp cứu, 18 giờ. Nam 30 tuổi bị xe máy tông, ngã đập đầu và cổ, nay không cử động được hai chân, yếu hai tay. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":52,"sbp":84,"dbp":50,"rr":22,"temperature_c":35.6,"spo2":92},"history":[{"question":"Chấn thương xảy ra thế nào, có mất ý thức không?","response":"Bị xe máy tông từ phía sau, ngã bật ra đập đầu và cổ, mê ngắn vài giây rồi tỉnh."},{"question":"Đau cổ, tê yếu tay chân từ lúc nào?","response":"Đau cổ nhiều, hai chân không cử động được, hai tay yếu và tê như kiến bò từ ngay sau tai nạn."},{"question":"Có khó thở, đau ngực không?","response":"Cảm giác thở yếu, thở nông, không đau ngực nhiều."},{"question":"Có đại tiểu tiện không tự chủ không?","response":"Đã tiểu ra quần lúc nằm."},{"question":"Có đau bụng, đau ở nơi khác không?","response":"Không đau bụng; đau cổ là chính."},{"question":"Có uống rượu, dùng thuốc không?","response":"Không uống rượu."},{"question":"Tiền sử bệnh, dị ứng thuốc?","response":"Khỏe mạnh, không dị ứng thuốc."},{"question":"Lần ăn cuối?","response":"Ăn trưa cách đây 6 giờ."}],"examination":[{"group":"K","item":"Đường thở, hô hấp","finding":"Thở bụng, ít dùng cơ liên sườn, thở nông; nói được câu ngắn."},{"group":"K","item":"Cột sống cổ","finding":"Đau chói vùng cổ giữa, đã được nẹp cổ và nằm ván cứng."},{"group":"K","item":"Vận động tay chân","finding":"Hai chân liệt hoàn toàn (0/5); hai tay yếu: gấp khuỷu 3/5, duỗi khuỷu 1/5, bàn tay 0/5."},{"group":"K","item":"Cảm giác","finding":"Mất cảm giác từ ngang núm vú trở xuống, vùng vai và mặt ngoài cánh tay còn."},{"group":"K","item":"Tuần hoàn và nhiệt","finding":"Da ấm hồng, mạch chậm 52, huyết áp thấp, thân nhiệt giảm nhẹ."},{"group":"K","item":"Bụng, chậu","finding":"Bụng mềm, cầu bàng quang căng, trương lực cơ thắt hậu môn mất."}],"investigations":[{"name":"CT cột sống cổ không cản quang","duration_minutes":40,"result":"Gãy trật C5 trên C6, mảnh xương đẩy vào ống sống, hẹp ống sống nặng."},{"name":"MRI cột sống cổ khi tình trạng cho phép","duration_minutes":10,"result":"Tổn thương tủy cổ C5 đến C6 phù và có ổ xuất huyết, chèn ép tủy."},{"name":"Khí máu động mạch","duration_minutes":10,"result":"pH 7,33; PaCO2 48; PaO2 70 (thở oxy)."},{"name":"Công thức máu, nhóm máu, đông máu","duration_minutes":10,"result":"Hb 13,8 g/dL, tiểu cầu 220 G/L, INR 1,0."},{"name":"eFAST tại giường","duration_minutes":10,"result":"Không dịch tự do trong ổ bụng, màng phổi, màng tim."},{"name":"X quang ngực và khung chậu","duration_minutes":10,"result":"Không gãy xương sườn, không tràn khí, khung chậu bình thường."},{"name":"Xoay trở và cởi nẹp cổ để khám toàn diện cho dễ","duration_minutes":10,"result":"Nguy hiểm, có thể làm tổn thương tủy nặng thêm."},{"name":"Chụp CT toàn thân ngay lập tức khi huyết áp thấp vì nghi chảy máu","duration_minutes":40,"result":"Huyết áp thấp ở đây có nhiều khả năng do sốc thần kinh; eFAST đã âm tính."}],"choices":{"diagnosis":{"ydx":["Chấn thương tủy cổ C5 do gãy trật C5-C6, tổn thương tủy hoàn toàn, kèm sốc thần kinh","Hội chứng tủy trung tâm đơn thuần","Sốc giảm thể tích do chảy máu trong bụng","Gãy cột sống cổ không tổn thương tủy"]},"actions":["Truyền dịch tinh thể ồ ạt để điều trị tụt huyết áp","Dùng atropine khi mạch dưới 50 gây triệu chứng, theo dõi nhịp tim","Đặt đường truyền lớn, bù dịch hợp lý và dùng noradrenaline để giữ MAP 85 đến 90 mmHg","Hội chẩn ngoại thần kinh hoặc chấn thương chỉnh hình cột sống, xét mổ giải ép sớm và cố định","Đặt nội khí quản bằng cách ngửa cổ tối đa","Thở oxy, theo dõi hô hấp, chuẩn bị hỗ trợ thông khí hoặc đặt nội khí quản (giữ trục cổ) nếu mệt hô hấp hoặc PaCO2 tăng","Làm CT cột sống cổ, tiếp theo MRI khi ổn định","Dùng methylprednisolone liều cao thường quy cho mọi chấn thương tủy","Cởi nẹp cổ và xoay trở bệnh nhân để khám","Bất động cột sống cổ, giữ nẹp cổ và xoay trục cả khối khi vận chuyển","Sử dụng thuốc phòng huyết khối tĩnh mạch sâu và dự phòng loét dạ dày sớm","Đặt sonde tiểu, giữ ấm, phòng loét tì đè, theo dõi tụt thân nhiệt"]}}'::jsonb,
  '8ce08719d7bf76376ab3651fd1f5e3f9d6b37bcf9adc40e5d9a912e6428f75f7'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

