values (
  'ngoai-cap-cuu-106',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-106","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-106-1","resource_type":"other","source":"ATLS 10th Edition (American College of Surgeons), Chapter 7: Spine and Spinal Cord Trauma, 2018.","title":"ATLS 10th Edition (American College of Surgeons), Chapter 7: Spine and Spinal Cord Trauma, 2018.","organization":null,"year_version":null,"citation":"ATLS 10th Edition (American College of Surgeons), Chapter 7: Spine and Spinal Cord Trauma, 2018.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-106-2","resource_type":"other","source":"Guidelines for the management of acute cervical spine and spinal cord injuries: 2013 update, Neurosurgery 2013; và Congress of Neurological Surgeons 2013 guidelines. DOI: 10.1227/NEU.0b013e3182a7d4ba.","title":"Guidelines for the management of acute cervical spine and spinal cord injuries: 2013 update, Neurosurgery 2013; và Congress of Neurological Surgeons 2013 guidelines. DOI: 10.1227/NEU.0b013e3182a7d4ba.","organization":null,"year_version":null,"citation":"Guidelines for the management of acute cervical spine and spinal cord injuries: 2013 update, Neurosurgery 2013; và Congress of Neurological Surgeons 2013 guidelines. DOI: 10.1227/NEU.0b013e3182a7d4ba.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-106-3","resource_type":"other","source":"Hướng dẫn quy trình xử trí chấn thương cột sống và tủy sống của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","title":"Hướng dẫn quy trình xử trí chấn thương cột sống và tủy sống của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","organization":null,"year_version":null,"citation":"Hướng dẫn quy trình xử trí chấn thương cột sống và tủy sống của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,2,3,4],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"essential"},{"index":5,"role":"neutral"},{"index":6,"role":"waste"},{"index":7,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Gãy cột sống cổ không tổn thương tủy","credit":"none"},{"text":"Sốc giảm thể tích do chảy máu trong bụng","credit":"none"},{"text":"Chấn thương tủy cổ C5 do gãy trật C5-C6, tổn thương tủy hoàn toàn, kèm sốc thần kinh","credit":"full"},{"text":"Hội chứng tủy trung tâm đơn thuần","credit":"none"}]},"action_options":[{"text":"Bất động cột sống cổ, giữ nẹp cổ và xoay trục cả khối khi vận chuyển","time_minutes":2,"grade":"critical","rationale":"Phòng tổn thương tủy nặng thêm."},{"text":"Thở oxy, theo dõi hô hấp, chuẩn bị hỗ trợ thông khí hoặc đặt nội khí quản (giữ trục cổ) nếu mệt hô hấp hoặc PaCO2 tăng","time_minutes":5,"grade":"critical","rationale":"Liệt cơ hô hấp, thở bụng và PaCO2 tăng, nguy cơ suy hô hấp."},{"text":"Đặt đường truyền lớn, bù dịch hợp lý và dùng noradrenaline để giữ MAP 85 đến 90 mmHg","time_minutes":10,"grade":"critical","rationale":"Sốc thần kinh cần vận mạch, giảm thể tích khác cần truyền dịch; tưới máu tủy phụ thuộc huyết áp."},{"text":"Dùng atropine khi mạch dưới 50 gây triệu chứng, theo dõi nhịp tim","time_minutes":5,"grade":"critical","rationale":"Nhịp chậm do mất giao cảm."},{"text":"Đặt sonde tiểu, giữ ấm, phòng loét tì đè, theo dõi tụt thân nhiệt","time_minutes":10,"grade":"critical","rationale":"Liệt tự chủ, mất điều hòa nhiệt và bàng quang."},{"text":"Hội chẩn ngoại thần kinh hoặc chấn thương chỉnh hình cột sống, xét mổ giải ép sớm và cố định","time_minutes":15,"grade":"recommended","rationale":"Gãy trật có chèn ép tủy cần giải ép, nắn chỉnh."},{"text":"Làm CT cột sống cổ, tiếp theo MRI khi ổn định","time_minutes":20,"grade":"recommended","rationale":"Xác định mức tổn thương và chèn ép."},{"text":"Sử dụng thuốc phòng huyết khối tĩnh mạch sâu và dự phòng loét dạ dày sớm","time_minutes":10,"grade":"recommended","rationale":"Nguy cơ cao ở bệnh nhân liệt."},{"text":"Cởi nẹp cổ và xoay trở bệnh nhân để khám","time_minutes":5,"grade":"harmful","rationale":"Gây tổn thương tủy nặng thêm."},{"text":"Truyền dịch tinh thể ồ ạt để điều trị tụt huyết áp","time_minutes":20,"grade":"harmful","rationale":"Sốc thần kinh không do mất thể tích, dễ gây phù phổi."},{"text":"Dùng methylprednisolone liều cao thường quy cho mọi chấn thương tủy","time_minutes":15,"grade":"harmful","rationale":"Khuyến cáo hiện hành không khuyến khích dùng thường quy vì hại nhiều hơn lợi."},{"text":"Đặt nội khí quản bằng cách ngửa cổ tối đa","time_minutes":5,"grade":"harmful","rationale":"Làm tổn thương tủy cổ nặng thêm."}],"teaching_explanation":"Chấn thương tủy cổ có sốc thần kinh (huyết áp thấp, mạch chậm, da ấm) cần bất động, bảo vệ hô hấp và giữ MAP 85 đến 90 mmHg bằng vận mạch sau bù dịch hợp lý. Không dùng steroid liều cao thường quy; luôn loại trừ chảy máu kèm theo bằng eFAST."}'::jsonb,
  'b0d2bb6933ec8cb168efd68de9b5250057dbb1d7f37d2be52231348f4f02c58f'
)
