insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-cap-cuu-107',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-107","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Chảy máu miệng sau cắt amidan, mạch nhanh và da lạnh","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":9,"sex":"nữ","patient_label":"Cháu B. T. H."},"presentation":{"intro":"Phòng cấp cứu, 22 giờ. Bé gái 9 tuổi cắt amidan 5 ngày trước, nay nôn ra máu và chảy máu miệng từ chiều, li bì. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":150,"sbp":70,"dbp":40,"rr":32,"temperature_c":37.2,"spo2":94},"history":[{"question":"Cắt amidan lúc nào, tại đâu, có chảy máu sau mổ không?","response":"Cắt amidan cách 5 ngày, đã xuất viện ngày thứ hai; trước đó không chảy máu."},{"question":"Chảy máu bắt đầu thế nào, lượng bao nhiêu?","response":"Chiều nay thấy chảy máu đỏ tươi trong miệng, nôn ra khoảng một chén máu và cục, bé nuốt máu."},{"question":"Có nôn ra máu bao nhiêu lần, có nuốt máu không?","response":"Nôn hai lần, ra máu tươi và cục máu."},{"question":"Bé có bệnh máu khó đông hoặc chảy máu bất thường trước đây không?","response":"Không rõ, trong nhà không ai bị bệnh chảy máu; trước mổ đã làm xét nghiệm đông máu bình thường."},{"question":"Bé có dùng aspirin hoặc thuốc giảm đau chống viêm sau mổ không?","response":"Mẹ cho uống ibuprofen khi đau họng."},{"question":"Bé có sốt, đau họng nhiều không?","response":"Đau họng, hơi sốt, ăn uống ít."},{"question":"Bé có dị ứng thuốc không?","response":"Không."},{"question":"Lần ăn uống cuối?","response":"Chiều nay uống ít sữa, sau đó nôn."}],"examination":[{"group":"K","item":"Tri giác và tưới máu","finding":"Li bì, da nhợt lạnh, môi tái, thời gian làm đầy mao mạch 4 giây."},{"group":"K","item":"Đường thở","finding":"Thở nhanh, có máu và cục máu trong miệng, nuốt liên tục; chưa có tiếng rít."},{"group":"K","item":"Họng","finding":"Hố amidan phải có cục máu đông phủ giả mạc, có máu rỉ tươi; hố trái khô."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh, mạch nhẹ; phổi trong."},{"group":"K","item":"Bụng","finding":"Mềm, không chướng."},{"group":"K","item":"Dấu hiệu xuất huyết ở nơi khác","finding":"Không có bầm máu, chấm xuất huyết."}],"investigations":[{"name":"Công thức máu, nhóm máu, thử chéo máu, đông máu toàn bộ","duration_minutes":10,"result":"Hb 7,2 g/dL (trước mổ 12), tiểu cầu 280 G/L, PT, aPTT bình thường."},{"name":"Khí máu, lactate","duration_minutes":10,"result":"pH 7,30; BE -7; lactate 3,8 mmol/L."},{"name":"Đường huyết mao mạch","duration_minutes":10,"result":"5,0 mmol/L."},{"name":"Điện giải đồ","duration_minutes":10,"result":"Na 136, K 4,0 mmol/L."},{"name":"Định lượng yếu tố von Willebrand và yếu tố đông máu khi đã ổn định","duration_minutes":10,"result":"Gửi mẫu, kết quả sau."},{"name":"CT cổ có cản quang để tìm vị trí chảy máu","duration_minutes":40,"result":"Không cần, làm chậm cầm máu và có thể làm xấu thêm tình trạng."},{"name":"Cho uống barium để xem họng","duration_minutes":10,"result":"Không có chỉ định, nguy cơ sặc."}],"choices":{"diagnosis":{"ydx":["Viêm họng cấp có chảy máu cam nuốt máu","Chảy máu thứ phát sau cắt amidan (ngày thứ 5), mất máu cấp, sốc giảm thể tích độ III đến IV","Rối loạn đông máu bẩm sinh đơn thuần không do mổ","Chảy máu sau mổ nguyên phát (dưới 24 giờ)"]},"actions":["Chờ nhóm máu và chéo máu xong mới bù dịch","Chuẩn bị gây mê khởi mê nhanh với dạ dày đầy (đã nuốt máu), hút lớn, thiết bị đường thở khó","Nhét gạc mù vào họng bé li bì","Cho vitamin K, kiểm tra yếu tố đông máu khi ổn định","Cho acid tranexamic tĩnh mạch theo cân nặng","Cho thêm ibuprofen giảm đau họng","Hút miệng họng, nằm nghiêng hoặc đầu thấp, oxy lưu lượng cao, giữ đường thở","Hội chẩn tai mũi họng và gây mê hồi sức, chuẩn bị vào phòng mổ cầm máu khẩn","Theo dõi sinh hiệu, lactate, đường huyết, nước tiểu liên tục","Cho trẻ ăn uống sữa và nước đá để cầm máu","Đặt hai đường truyền (nếu khó thì đường xương), bù dịch tinh thể 10 đến 20 mL/kg và gọi máu, truyền hồng cầu lắng sớm","Giải thích tình trạng cho cha mẹ, xin đồng ý mổ và truyền máu"]}}'::jsonb,
  'abaf66679ca42b8bbc051e08aa6459ac1ba255c945fcb469672bd06eea1ff04b'
)
