values (
  'ngoai-cap-cuu-107',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-107","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-tonsillectomy-aaohns-2019","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/30798778/","title":"Clinical practice guideline: Tonsillectomy in children (update), Otolaryngology-Head and Neck Surgery 2019. DOI: 10.1177/0194599818801757.","organization":null,"year_version":null,"citation":"Clinical practice guideline: Tonsillectomy in children (update), Otolaryngology-Head and Neck Surgery 2019. DOI: 10.1177/0194599818801757.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-107-2","resource_type":"other","source":"Pediatric Advanced Life Support (PALS) guideline: sốc giảm thể tích ở trẻ em, American Heart Association 2020.","title":"Pediatric Advanced Life Support (PALS) guideline: sốc giảm thể tích ở trẻ em, American Heart Association 2020.","organization":null,"year_version":null,"citation":"Pediatric Advanced Life Support (PALS) guideline: sốc giảm thể tích ở trẻ em, American Heart Association 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-107-3","resource_type":"other","source":"Hướng dẫn xử trí sốc ở trẻ em của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","title":"Hướng dẫn xử trí sốc ở trẻ em của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","organization":null,"year_version":null,"citation":"Hướng dẫn xử trí sốc ở trẻ em của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Chảy máu sau mổ nguyên phát (dưới 24 giờ)","credit":"none"},{"text":"Rối loạn đông máu bẩm sinh đơn thuần không do mổ","credit":"none"},{"text":"Chảy máu thứ phát sau cắt amidan (ngày thứ 5), mất máu cấp, sốc giảm thể tích độ III đến IV","credit":"full"},{"text":"Viêm họng cấp có chảy máu cam nuốt máu","credit":"none"}]},"action_options":[{"text":"Hút miệng họng, nằm nghiêng hoặc đầu thấp, oxy lưu lượng cao, giữ đường thở","time_minutes":3,"grade":"critical","rationale":"Chảy máu miệng họng có nguy cơ sặc máu và tắc đường thở."},{"text":"Đặt hai đường truyền (nếu khó thì đường xương), bù dịch tinh thể 10 đến 20 mL/kg và gọi máu, truyền hồng cầu lắng sớm","time_minutes":5,"grade":"critical","rationale":"Sốc giảm thể tích ở trẻ cần máu sớm, mạch 150 và huyết áp 70 là sốc mất bù."},{"text":"Hội chẩn tai mũi họng và gây mê hồi sức, chuẩn bị vào phòng mổ cầm máu khẩn","time_minutes":10,"grade":"critical","rationale":"Chảy máu hố amidan cần kiểm soát bằng phẫu thuật; không thể chờ."},{"text":"Cho acid tranexamic tĩnh mạch theo cân nặng","time_minutes":5,"grade":"critical","rationale":"Hỗ trợ cầm máu, không thay thế phẫu thuật."},{"text":"Theo dõi sinh hiệu, lactate, đường huyết, nước tiểu liên tục","time_minutes":10,"grade":"critical","rationale":"Đánh giá đáp ứng hồi sức."},{"text":"Chuẩn bị gây mê khởi mê nhanh với dạ dày đầy (đã nuốt máu), hút lớn, thiết bị đường thở khó","time_minutes":10,"grade":"recommended","rationale":"Nuốt nhiều máu, nguy cơ trào ngược khi khởi mê."},{"text":"Cho vitamin K, kiểm tra yếu tố đông máu khi ổn định","time_minutes":10,"grade":"recommended","rationale":"Loại trừ rối loạn đông máu tiềm ẩn."},{"text":"Giải thích tình trạng cho cha mẹ, xin đồng ý mổ và truyền máu","time_minutes":10,"grade":"recommended","rationale":"Quyền được thông tin."},{"text":"Cho trẻ ăn uống sữa và nước đá để cầm máu","time_minutes":5,"grade":"harmful","rationale":"Dạ dày đầy làm tăng nguy cơ trào ngược khi gây mê."},{"text":"Nhét gạc mù vào họng bé li bì","time_minutes":5,"grade":"harmful","rationale":"Nguy cơ tắc đường thở và cầm máu không hiệu quả."},{"text":"Chờ nhóm máu và chéo máu xong mới bù dịch","time_minutes":30,"grade":"harmful","rationale":"Sốc cần hồi sức ngay song song với chuẩn bị máu."},{"text":"Cho thêm ibuprofen giảm đau họng","time_minutes":5,"grade":"harmful","rationale":"NSAID làm tăng chảy máu."}],"teaching_explanation":"Chảy máu sau cắt amidan là cấp cứu đường thở và tuần hoàn ở trẻ. Mạch rất nhanh, da lạnh, li bì là sốc mất bù; hồi sức dịch, máu sớm, đảm bảo đường thở và phẫu thuật cầm máu. Tránh NSAID sau mổ và luôn nhớ dạ dày đầy máu khi gây mê."}'::jsonb,
  '471944578138c26abb851eda2c593d1768ecccbb8d8265fc3c02bd527ddd7c8d'
)
