insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-cap-cuu-108',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-108","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau bụng dữ dội nhưng bụng mềm, rung nhĩ và nôn","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":72,"sex":"nữ","patient_label":"Bà H. T. N."},"presentation":{"intro":"Phòng cấp cứu, 23 giờ. Nữ 72 tuổi đau bụng đột ngột dữ dội quanh rốn 5 giờ, nôn, đi ngoài phân lỏng, bụng khám còn mềm. Ca mô phỏng, mọi thông tin là giả định.","place":null,"clock":null,"night":false},"vitals":{"hr":128,"sbp":100,"dbp":62,"rr":26,"temperature_c":37.6,"spo2":95},"history":[{"question":"Đau bụng bắt đầu thế nào?","response":"Đột ngột, đau quặn dữ dội quanh rốn cách đây 5 giờ, không thuốc nào làm đỡ."},{"question":"Có nôn, tiêu chảy hoặc ra máu trong phân không?","response":"Nôn hai lần, đi ngoài phân lỏng hai lần, lần sau có lẫn máu đỏ sẫm."},{"question":"Có bệnh tim, rối loạn nhịp hoặc dùng thuốc chống đông không?","response":"Có rung nhĩ vài năm, trước đây uống thuốc chống đông nhưng tự ngưng vài tháng."},{"question":"Có đau bụng sau ăn, sợ ăn, sụt cân trước đó không?","response":"Vài tháng nay đau bụng sau khi ăn, sợ ăn, sụt khoảng 5 kg."},{"question":"Có đau ngực, khó thở hoặc tê yếu chân tay không?","response":"Không đau ngực; hơi khó thở."},{"question":"Có hút thuốc, tăng huyết áp, tiểu đường không?","response":"Tăng huyết áp, hút thuốc lá nhiều năm."},{"question":"Có dị ứng thuốc cản quang không?","response":"Không."},{"question":"Tiền sử phẫu thuật bụng?","response":"Chưa từng."}],"examination":[{"group":"K","item":"Toàn trạng","finding":"Tỉnh, vật vã, kêu đau, da lạnh, làm đầy mao mạch 3 giây."},{"group":"K","item":"Khám bụng","finding":"Bụng chướng nhẹ, mềm, ấn ít đau, không phản ứng thành bụng; đau không tương xứng với khám."},{"group":"K","item":"Tim mạch","finding":"Tim loạn nhịp hoàn toàn, nhanh; mạch bẹn hai bên bắt được."},{"group":"K","item":"Thăm trực tràng","finding":"Có máu đỏ sẫm trên găng."},{"group":"K","item":"Chi dưới","finding":"Chi ấm, mạch ngoại biên bắt được."},{"group":"K","item":"Phổi","finding":"Rì rào phế nang giảm hai đáy, không ran."}],"investigations":[{"name":"CT mạch máu bụng (CT angiography) ngay","duration_minutes":40,"result":"Huyết khối lấp tắc động mạch mạc treo tràng trên cách gốc khoảng 3 cm; thành ruột non giảm ngấm thuốc, dịch tự do ít, khí trong tĩnh mạch cửa không có."},{"name":"Công thức máu, CRP, lactate, điện giải, creatinin, D-dimer","duration_minutes":10,"result":"Bạch cầu 18 G/L; lactate 4,5 mmol/L; D-dimer rất cao; creatinin 128 µmol/L."},{"name":"Khí máu động mạch","duration_minutes":10,"result":"pH 7,28; BE -9."},{"name":"Điện tim","duration_minutes":10,"result":"Rung nhĩ đáp ứng thất nhanh 128 lần/phút."},{"name":"Troponin","duration_minutes":10,"result":"Bình thường."},{"name":"X quang bụng đứng không chuẩn bị","duration_minutes":10,"result":"Quai ruột hơi giãn, không có liềm hơi."},{"name":"Nội soi đại tràng khi nghi thiếu máu để chẩn đoán","duration_minutes":20,"result":"Không nên làm lúc cấp cứu, nguy cơ thủng, làm chậm điều trị."},{"name":"Chờ siêu âm Doppler động mạch mạc treo thay cho CT","duration_minutes":40,"result":"Kết quả phụ thuộc người làm, làm chậm chẩn đoán trong khi CT mạch cho kết quả nhanh."}],"choices":{"diagnosis":{"ydx":["Viêm dạ dày ruột cấp","Thiếu máu mạc treo cấp do tắc động mạch mạc treo tràng trên (huyết khối lấp từ rung nhĩ), nguy cơ hoại tử ruột","Viêm ruột thiếu máu không tắc mạch đơn thuần","Viêm tụy cấp"]},"actions":["Chờ đến khi bụng cứng, phản ứng dội mới chụp CT","Cho thuốc co mạch liều cao để nâng huyết áp","Hội chẩn khẩn phẫu thuật mạch máu và phẫu thuật tiêu hóa, chuẩn bị tái thông mạch và đánh giá ruột","Làm nội soi đại tràng khẩn để chẩn đoán","Thở oxy, đặt hai đường truyền lớn, bù dịch tinh thể thận trọng, theo dõi monitor, lactate và nước tiểu","Dùng kháng sinh phổ rộng tĩnh mạch","Làm ngay CT mạch máu bụng khi nghi thiếu máu mạc treo (đau không tương xứng với khám, rung nhĩ)","Giải thích tiên lượng nặng, khả năng cắt ruột và mổ lần hai, ký cam kết","Giảm đau tĩnh mạch hợp lý","Điều trị nội khoa kéo dài với nuôi ăn tĩnh mạch rồi theo dõi","Dùng heparin không phân đoạn tĩnh mạch ngay khi có chẩn đoán, không chờ mổ","Nhịn ăn, đặt sonde dạ dày, sonde tiểu, kiểm soát nhịp tim (kiểm soát tần số rung nhĩ thận trọng)"]}}'::jsonb,
  'c196d52d06201c42d0645ad93d7e18d326ba9939ca48fdf71a710e3c3c1c9d64'
)
