  'ngoai-cap-cuu-108',
  '{"schema_version":"1.0.0","case_id":"ngoai-cap-cuu-108","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ami-wses-2022","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/36261857/","title":"World Society of Emergency Surgery (WSES) guidelines on acute mesenteric ischemia: 2022 update, World J Emerg Surg 2022. DOI: 10.1186/s13017-022-00443-x.","organization":null,"year_version":null,"citation":"World Society of Emergency Surgery (WSES) guidelines on acute mesenteric ischemia: 2022 update, World J Emerg Surg 2022. DOI: 10.1186/s13017-022-00443-x.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-108-2","resource_type":"other","source":"ESVS Clinical Practice Guidelines on the Management of Diseases of the Mesenteric and Renal Arteries and Veins, Eur J Vasc Endovasc Surg 2017. DOI: 10.1016/j.ejvs.2017.06.017.","title":"ESVS Clinical Practice Guidelines on the Management of Diseases of the Mesenteric and Renal Arteries and Veins, Eur J Vasc Endovasc Surg 2017. DOI: 10.1016/j.ejvs.2017.06.017.","organization":null,"year_version":null,"citation":"ESVS Clinical Practice Guidelines on the Management of Diseases of the Mesenteric and Renal Arteries and Veins, Eur J Vasc Endovasc Surg 2017. DOI: 10.1016/j.ejvs.2017.06.017.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-cap-cuu-108-3","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị rung nhĩ và bệnh động mạch của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","title":"Hướng dẫn chẩn đoán và điều trị rung nhĩ và bệnh động mạch của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị rung nhĩ và bệnh động mạch của Bộ Y tế Việt Nam (số quyết định xem can_doi_chieu).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"neutral"},{"index":6,"role":"waste"},{"index":7,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm tụy cấp","credit":"none"},{"text":"Viêm ruột thiếu máu không tắc mạch đơn thuần","credit":"none"},{"text":"Thiếu máu mạc treo cấp do tắc động mạch mạc treo tràng trên (huyết khối lấp từ rung nhĩ), nguy cơ hoại tử ruột","credit":"full"},{"text":"Viêm dạ dày ruột cấp","credit":"none"}]},"action_options":[{"text":"Thở oxy, đặt hai đường truyền lớn, bù dịch tinh thể thận trọng, theo dõi monitor, lactate và nước tiểu","time_minutes":5,"grade":"critical","rationale":"Có dấu giảm tưới máu; cần hồi sức nhưng tránh quá tải dịch."},{"text":"Làm ngay CT mạch máu bụng khi nghi thiếu máu mạc treo (đau không tương xứng với khám, rung nhĩ)","time_minutes":30,"grade":"critical","rationale":"Chẩn đoán sớm quyết định sống còn; không chờ có dấu viêm phúc mạc."},{"text":"Dùng heparin không phân đoạn tĩnh mạch ngay khi có chẩn đoán, không chờ mổ","time_minutes":5,"grade":"critical","rationale":"Ngăn lan rộng huyết khối, chống chỉ định tương đối nếu có chảy máu lớn."},{"text":"Hội chẩn khẩn phẫu thuật mạch máu và phẫu thuật tiêu hóa, chuẩn bị tái thông mạch và đánh giá ruột","time_minutes":15,"grade":"critical","rationale":"Tái thông trước khi cắt ruột là nguyên tắc."},{"text":"Dùng kháng sinh phổ rộng tĩnh mạch","time_minutes":10,"grade":"critical","rationale":"Nguy cơ chuyển vị vi khuẩn khi thiếu máu ruột."},{"text":"Nhịn ăn, đặt sonde dạ dày, sonde tiểu, kiểm soát nhịp tim (kiểm soát tần số rung nhĩ thận trọng)","time_minutes":10,"grade":"recommended","rationale":"Chuẩn bị mổ, tránh thuốc gây tụt huyết áp."},{"text":"Giảm đau tĩnh mạch hợp lý","time_minutes":5,"grade":"recommended","rationale":"Giảm đau nhưng không làm chậm chẩn đoán."},{"text":"Giải thích tiên lượng nặng, khả năng cắt ruột và mổ lần hai, ký cam kết","time_minutes":10,"grade":"recommended","rationale":"Tôn trọng quyền được thông tin."},{"text":"Chờ đến khi bụng cứng, phản ứng dội mới chụp CT","time_minutes":60,"grade":"harmful","rationale":"Khi có viêm phúc mạc ruột đã hoại tử, tử vong rất cao."},{"text":"Cho thuốc co mạch liều cao để nâng huyết áp","time_minutes":10,"grade":"harmful","rationale":"Co mạch mạc treo làm thiếu máu ruột nặng thêm."},{"text":"Điều trị nội khoa kéo dài với nuôi ăn tĩnh mạch rồi theo dõi","time_minutes":120,"grade":"harmful","rationale":"Chậm tái thông, tăng hoại tử ruột và tử vong."},{"text":"Làm nội soi đại tràng khẩn để chẩn đoán","time_minutes":60,"grade":"harmful","rationale":"Nguy cơ thủng ruột thiếu máu, không thay thế CT mạch."}],"teaching_explanation":"Đau bụng dữ dội nhưng khám bụng mềm ở người rung nhĩ hoặc xơ vữa là thiếu máu mạc treo cấp cho đến khi loại trừ. CT mạch máu bụng sớm, heparin ngay, hồi sức, rồi tái thông mạch trước khi cắt ruột. Chờ viêm phúc mạc là quá muộn."}'::jsonb,
  '564d64a15445c1b762a726887f9e4201ef4bf0e34a3aca6bd5e16c2ced17b818'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'yhct-kham-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nữ 48 tuổi đau sưng nóng các khớp nhỏ bàn tay, cứng khớp buổi sáng","setting":"phongkham","level":"Khó","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":48,"sex":"nữ","patient_label":"Người bệnh mô phỏng Hà T. L."},"presentation":{"intro":"Phòng khám Cơ xương khớp YHCT. Bà là giáo viên, đến khám vì đau sưng nhiều khớp nhỏ ở hai bàn tay khoảng 4 tháng, buổi sáng cứng khớp kéo dài, chưa điều trị đặc hiệu.","place":"Phòng khám Cơ xương khớp YHCT","clock":"08:40","night":false},"vitals":{"hr":84,"sbp":126,"dbp":78,"rr":18,"temperature_c":37.4,"spo2":98},"history":[{"question":"Đau sưng khớp nào, đối xứng hai bên không, kéo dài bao lâu?","response":"Khớp bàn ngón và khớp ngón gần hai tay, đối xứng, sưng đau nóng khoảng 4 tháng."},{"question":"Cứng khớp buổi sáng kéo dài bao lâu?","response":"Cứng khoảng 90 phút mới cử động được bình thường."},{"question":"Có sốt nhẹ, mệt mỏi, sụt cân, khô mắt khô miệng không?","response":"Hơi mệt, sốt nhẹ về chiều, không sụt cân, mắt hơi khô."},{"question":"Có sưng đau khớp ngón chân cái đột ngột, tăng acid uric, hay dùng rượu không?","response":"Không có cơn đau ngón chân cái, chưa từng xét nghiệm acid uric cao, không uống rượu."},{"question":"Có tự dùng thuốc giảm đau, corticoid hoặc thuốc nam không rõ nguồn?","response":"Tự mua thuốc giảm đau chống viêm uống khi đau, chưa dùng corticoid."},{"question":"Có tiền sử loét dạ dày, bệnh gan thận, thai nghén hay viêm gan B?","response":"Không loét dạ dày, chưa biết tình trạng viêm gan B, hết kinh nguyệt chưa tới 1 năm."},{"question":"Khớp có nóng đỏ, khát, tiểu vàng, đại tiện thế nào?","response":"Khớp nóng, khát, thích uống nước mát, tiểu vàng, đại tiện táo."}],"examination":[{"group":"V","item":"Thần sắc, khớp tay","finding":"Sưng nóng hơi đỏ các khớp bàn ngón 2, 3 và ngón gần hai tay, không biến dạng cố định."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi đỏ, rêu vàng nhờn."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Giọng rõ, không khó thở, hơi thở không hôi."},{"group":"T","item":"Mạch","finding":"Mạch hoạt sác."},{"group":"K","item":"Ấn khớp, nắm tay","finding":"Ấn đau 10 khớp nhỏ, nắm tay yếu, nhiệt độ da vùng khớp tăng."},{"group":"K","item":"Khám tim, phổi, da, hạt dưới da","finding":"Tim phổi bình thường, không hạt dưới da, không ban da."}],"investigations":[{"name":"Yếu tố dạng thấp (RF) và anti-CCP","duration_minutes":10,"result":"RF 96 IU/mL, anti-CCP 210 U/mL, đều dương tính cao."},{"name":"Tốc độ máu lắng và CRP","duration_minutes":10,"result":"Máu lắng 52 mm/giờ, CRP 24 mg/L."},{"name":"Công thức máu, men gan, creatinin, HBsAg, anti-HCV","duration_minutes":10,"result":"Hb 11,2 g/dL, bạch cầu bình thường, men gan và creatinin bình thường, HBsAg âm tính."},{"name":"X-quang hai bàn tay","duration_minutes":10,"result":"Mất chất khoáng đầu xương, hẹp khe khớp nhẹ, chưa thấy bào mòn."},{"name":"Chọc hút dịch khớp làm xét nghiệm tinh thể urat để chẩn đoán","duration_minutes":10,"result":"Không có chỉ định ở ca viêm nhiều khớp nhỏ đối xứng điển hình."}],"choices":{"diagnosis":{"ydx":["Viêm khớp dạng thấp giai đoạn sớm, đang hoạt động","Lupus ban đỏ hệ thống","Viêm khớp vảy nến","Bệnh gút mạn","Thoái hóa khớp bàn tay"],"bd":["Đầu thống","Yêu thống","Tý chứng (Lịch tiết phong)","Nuy chứng","Thống phong"],"bc":["Lý – Hư – Hàn","Biểu – Thực – Nhiệt","Biểu – Thực – Hàn","Lý – Thực – Hàn","Lý – Hư – Nhiệt"],"the":["Khí huyết lưỡng hư","Đàm ứ tý trở","Phong thấp nhiệt tý","Can thận hư tổn","Phong hàn thấp tý"],"phap":["Thanh nhiệt, trừ phong thấp, thông kinh lạc","Bổ can thận, cường cân cốt","Tán hàn trừ thấp, thông lạc","Hóa đàm hoạt huyết, thông lạc","Ích khí dưỡng huyết"],"phuong":["Bạch hổ quế chi thang gia giảm","Độc hoạt tang ký sinh thang","Lục vị địa hoàng hoàn","Tuyên tý thang","Quyên tý thang"],"huyet":["Mệnh môn","Thiên khu","Thận du","Hợp cốc","Dương trì","Ngoại quan","Khúc trì","Liệt khuyết"]},"actions":["Sàng lọc viêm gan B, C, lao tiềm ẩn và kiểm tra chức năng gan thận trước khi dùng DMARD","Châm Hợp cốc, Khúc trì, Dương trì, Ngoại quan, có thể phối hợp huyệt tại chỗ","Tự ý dùng corticoid kéo dài hoặc thuốc nam trộn corticoid không rõ nguồn gốc","Chuyển hoặc hội chẩn bác sĩ cơ xương khớp để khởi trị thuốc DMARD (thường methotrexate) sớm, kèm acid folic, theo dõi men gan, huyết học","Dùng thuốc YHCT Bạch hổ quế chi thang gia giảm theo thể Phong thấp nhiệt, theo dõi tiêu hóa","Dùng NSAID ngắn ngày, liều thấp nhất có hiệu quả, che chắn dạ dày nếu cần","Hướng dẫn giữ ấm vừa phải, tập vận động khớp nhẹ, khám theo dõi định kỳ","Dùng Mã tiền, Phụ tử liều cao tự ý khi chưa có thầy thuốc theo dõi","Chọc hút dịch khớp tìm tinh thể urat"]}}'::jsonb,
  'be50865b8089f3ed85e81b099fde6ba0572b58c7b6a47468fed079c464e887f5'
)
