  '{"schema_version":"1.0.0","case_id":"yhct-kham-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-001-1","resource_type":"other","source":"Aletaha D, et al. 2010 Rheumatoid Arthritis Classification Criteria, ACR/EULAR Collaborative Initiative. Arthritis Rheum 2010.","title":"Aletaha D, et al. 2010 Rheumatoid Arthritis Classification Criteria, ACR/EULAR Collaborative Initiative. Arthritis Rheum 2010.","organization":null,"year_version":null,"citation":"Aletaha D, et al. 2010 Rheumatoid Arthritis Classification Criteria, ACR/EULAR Collaborative Initiative. Arthritis Rheum 2010.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-001-2","resource_type":"other","source":"Smolen JS, et al. EULAR recommendations for the management of rheumatoid arthritis, update.","title":"Smolen JS, et al. EULAR recommendations for the management of rheumatoid arthritis, update.","organization":null,"year_version":null,"citation":"Smolen JS, et al. EULAR recommendations for the management of rheumatoid arthritis, update.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,4,5],"examination_essential_indices":[0,1,3,4],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm khớp dạng thấp giai đoạn sớm, đang hoạt động","credit":"full"},{"text":"Thoái hóa khớp bàn tay","credit":"none"},{"text":"Bệnh gút mạn","credit":"none"},{"text":"Viêm khớp vảy nến","credit":"none"},{"text":"Lupus ban đỏ hệ thống","credit":"none"}],"bd":[{"text":"Tý chứng (Lịch tiết phong)","credit":"full"},{"text":"Thống phong","credit":"none"},{"text":"Nuy chứng","credit":"none"},{"text":"Yêu thống","credit":"none"},{"text":"Đầu thống","credit":"none"}],"bc":[{"text":"Biểu – Thực – Nhiệt","credit":"full"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"},{"text":"Lý – Thực – Hàn","credit":"none"}],"the":[{"text":"Phong thấp nhiệt tý","credit":"full"},{"text":"Phong hàn thấp tý","credit":"none"},{"text":"Can thận hư tổn","credit":"none"},{"text":"Đàm ứ tý trở","credit":"none"},{"text":"Khí huyết lưỡng hư","credit":"none"}],"phap":[{"text":"Thanh nhiệt, trừ phong thấp, thông kinh lạc","credit":"full"},{"text":"Tán hàn trừ thấp, thông lạc","credit":"none"},{"text":"Bổ can thận, cường cân cốt","credit":"none"},{"text":"Hóa đàm hoạt huyết, thông lạc","credit":"none"},{"text":"Ích khí dưỡng huyết","credit":"none"}],"phuong":[{"text":"Bạch hổ quế chi thang gia giảm","credit":"full"},{"text":"Tuyên tý thang","credit":"partial"},{"text":"Quyên tý thang","credit":"none"},{"text":"Độc hoạt tang ký sinh thang","credit":"none"},{"text":"Lục vị địa hoàng hoàn","credit":"none"}],"huyet":[{"text":"Hợp cốc","credit":"full"},{"text":"Khúc trì","credit":"full"},{"text":"Dương trì","credit":"full"},{"text":"Ngoại quan","credit":"full"},{"text":"Mệnh môn","credit":"none"},{"text":"Thận du","credit":"none"},{"text":"Thiên khu","credit":"none"},{"text":"Liệt khuyết","credit":"none"}]},"action_options":[{"text":"Chuyển hoặc hội chẩn bác sĩ cơ xương khớp để khởi trị thuốc DMARD (thường methotrexate) sớm, kèm acid folic, theo dõi men gan, huyết học","time_minutes":20,"grade":"recommended","rationale":"Điều trị sớm theo mục tiêu giảm hoạt tính bệnh, tránh hủy khớp."},{"text":"Sàng lọc viêm gan B, C, lao tiềm ẩn và kiểm tra chức năng gan thận trước khi dùng DMARD","time_minutes":10,"grade":"recommended","rationale":"Chuẩn bị an toàn trước điều trị ức chế miễn dịch."},{"text":"Dùng thuốc YHCT Bạch hổ quế chi thang gia giảm theo thể Phong thấp nhiệt, theo dõi tiêu hóa","time_minutes":10,"grade":"recommended","rationale":"Thanh nhiệt trừ phong thấp, hỗ trợ giảm đau sưng."},{"text":"Châm Hợp cốc, Khúc trì, Dương trì, Ngoại quan, có thể phối hợp huyệt tại chỗ","time_minutes":20,"grade":"recommended","rationale":"Thông kinh lạc, giảm đau, giảm sưng khớp."},{"text":"Dùng NSAID ngắn ngày, liều thấp nhất có hiệu quả, che chắn dạ dày nếu cần","time_minutes":5,"grade":"recommended","rationale":"Giảm triệu chứng trong lúc chờ DMARD phát huy tác dụng."},{"text":"Hướng dẫn giữ ấm vừa phải, tập vận động khớp nhẹ, khám theo dõi định kỳ","time_minutes":5,"grade":"recommended","rationale":"Giữ chức năng khớp, theo dõi hoạt tính bệnh."},{"text":"Chọc hút dịch khớp tìm tinh thể urat","time_minutes":30,"grade":"waste","rationale":"Không có chỉ định ở ca này."},{"text":"Tự ý dùng corticoid kéo dài hoặc thuốc nam trộn corticoid không rõ nguồn gốc","time_minutes":2,"grade":"harmful","rationale":"Hội chứng Cushing, loãng xương, loét tiêu hóa, bùng phát bệnh khi ngưng đột ngột."},{"text":"Dùng Mã tiền, Phụ tử liều cao tự ý khi chưa có thầy thuốc theo dõi","time_minutes":2,"grade":"harmful","rationale":"Độc tính thần kinh, tim mạch; thể này thiên nhiệt không dùng thuốc đại nhiệt."}],"teaching_explanation":"Viêm khớp dạng thấp sớm thường biểu hiện viêm nhiều khớp nhỏ đối xứng, cứng khớp buổi sáng trên 30 phút, RF và anti-CCP dương tính. Phải khởi trị DMARD sớm; YHCT là phối hợp. Thể Phong thấp nhiệt tý: khớp sưng nóng đỏ, lưỡi đỏ rêu vàng nhờn, mạch hoạt sác, dùng Bạch hổ quế chi thang gia giảm; tránh dùng thuốc ôn nhiệt. Cảnh giác thuốc trộn corticoid và độc tính của vị thuốc như Mã tiền, Phụ tử."}'::jsonb,
  '6525210542a1a6ae01bd9240e1ddd3e5b3fb015a16ca9436a5d17de9ee01f82e'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'yhct-kham-002',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nam 62 tuổi khó thở khi gắng sức, khò khè tái phát, hít thở ngắn","setting":"phongkham","level":"Khó","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":62,"sex":"nam","patient_label":"Người bệnh mô phỏng Nguyễn V. P."},"presentation":{"intro":"Phòng khám Nội hô hấp YHCT. Ông bị hen từ nhỏ, đến khám vì khó thở khi gắng sức tăng dần, khò khè về đêm, hít vào ngắn, mệt lả.","place":"Phòng khám Nội hô hấp YHCT","clock":"09:10","night":false},"vitals":{"hr":88,"sbp":132,"dbp":80,"rr":20,"temperature_c":36.8,"spo2":94},"history":[{"question":"Khó thở khi nào, khò khè về đêm hay sáng sớm, tần suất cơn?","response":"Khò khè và khó thở gần như hằng tuần, nhất là về đêm và sáng sớm, leo một tầng lầu là phải nghỉ."},{"question":"Hít vào hay thở ra khó hơn? Cảm giác hít ngắn, không xuống sâu?","response":"Thở ra khò khè, hít vào ngắn, khó hít sâu xuống bụng."},{"question":"Có ho đờm, sốt, đau ngực, khạc máu không?","response":"Ho ít, đờm trắng loãng, không sốt, không đau ngực, không ho máu."},{"question":"Đang dùng thuốc xịt gì? Có tự ngưng thuốc dự phòng không?","response":"Dùng ống xịt cắt cơn salbutamol thường xuyên, thuốc dự phòng thì ngưng mấy tháng vì thấy đỡ."},{"question":"Có hút thuốc, bệnh tim, tăng huyết áp, tiền sử dị ứng không?","response":"Bỏ thuốc lá 5 năm, trước đó 20 gói năm. Có tăng huyết áp đang uống thuốc."},{"question":"Có sợ lạnh, tay chân lạnh, đau lưng mỏi gối, tiểu đêm không?","response":"Sợ lạnh, hay mệt, mỏi lưng gối, tiểu đêm 2 lần."},{"question":"Dị ứng thuốc, aspirin, NSAID gây khó thở không?","response":"Không dị ứng thuốc đã biết."}],"examination":[{"group":"V","item":"Thần sắc, hình thể","finding":"Sắc mặt nhợt, tinh thần mệt, thở nông, lồng ngực hơi căng."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, bệu, rêu trắng mỏng."},{"group":"M","item":"Giọng nói, tiếng thở","finding":"Giọng nhỏ, thở ra có tiếng khò khè nhẹ."},{"group":"T","item":"Mạch","finding":"Mạch trầm tế vô lực."},{"group":"K","item":"Nghe phổi","finding":"Rì rào phế nang giảm nhẹ, ran rít cuối thì thở ra hai phế trường, không ran ẩm."},{"group":"K","item":"Khám tim, phù, tay chân","finding":"Tim đều, không phù, tay chân mát, ngón tay không dùi trống."}],"investigations":[{"name":"Hô hấp ký trước và sau test giãn phế quản","duration_minutes":10,"result":"FEV1 62 phần trăm dự đoán, FEV1 trên FVC 0,64, tăng FEV1 sau giãn phế quản 15 phần trăm và 280 mL."},{"name":"Đo lưu lượng đỉnh PEF, ghi nhật ký","duration_minutes":10,"result":"PEF 55 phần trăm trị số tốt nhất, biến thiên ngày đêm 28 phần trăm."},{"name":"X-quang ngực thẳng","duration_minutes":10,"result":"Phổi tăng sáng nhẹ, không thâm nhiễm, bóng tim bình thường."},{"name":"Công thức máu, bạch cầu ái toan","duration_minutes":10,"result":"Bạch cầu ái toan 6 phần trăm, không tăng bạch cầu trung tính."},{"name":"CT ngực có cản quang để chẩn đoán hen","duration_minutes":40,"result":"Không có chỉ định thường quy ở ca hen đã có hô hấp ký phù hợp."}],"choices":{"diagnosis":{"ydx":["Viêm phế quản cấp","Bệnh phổi tắc nghẽn mạn tính (COPD) thuần túy","Hen phế quản mạn, chưa kiểm soát, nghi bỏ thuốc dự phòng","Suy tim trái","Thuyên tắc phổi"],"bd":["Phế nuy","Đàm ẩm","Kết hung","Háo suyễn","Phế ung"],"bc":["Biểu – Thực – Hàn","Biểu – Hư – Nhiệt","Lý – Thực – Nhiệt","Lý – Hư – Nhiệt","Lý – Hư – Hàn"],"the":["Phế khí hư","Phế thận khí hư","Hàn đàm trở phế","Tâm thận dương hư","Nhiệt đàm uất phế"],"phap":["Bổ phế ích thận, nạp khí bình suyễn","Ôn dương lợi thủy","Thanh nhiệt hóa đàm, bình suyễn","Ôn phế tán hàn, hóa đàm","Bổ phế khí, cố biểu"],"phuong":["Bổ phế thang hợp Thận khí hoàn","Ngọc bình phong tán","Định suyễn thang","Tiểu thanh long thang","Sinh mạch tán hợp Thận khí hoàn"],"huyet":["Thái xung","Khí hải","Định suyễn","Thận du","Hợp cốc","Túc tam lý","Phong long","Phế du"]},"actions":["Dùng thuốc chứa Ma hoàng liều cao hoặc kéo dài khi có tăng huyết áp","Dùng thuốc YHCT Bổ phế thang hợp Thận khí hoàn gia giảm ngoài cơn","Chỉ dùng thuốc cắt cơn kéo dài và để người bệnh tự ngưng thuốc dự phòng","Tập thở bụng, thở chúm môi, tư vấn tiêm vắc-xin cúm và phế cầu","Châm cứu Phế du, Thận du, Định suyễn, Khí hải, Túc tam lý (có thể cứu ngoài cơn)","Xác định và tránh yếu tố khởi phát (lạnh, khói, dị nguyên), tái khám sau 2 đến 4 tuần","Đo SpO2, PEF, dặn dấu hiệu nặng cần đến cấp cứu ngay (nói từng từ, tím tái, lơ mơ)","Chụp CT ngực có cản quang","Đánh giá mức độ kiểm soát hen, kỹ thuật dùng ống xịt, tái khởi trị thuốc dự phòng ICS hoặc ICS kết hợp LABA theo bậc điều trị GINA"]}}'::jsonb,
  '3ac624c1726bee3ad7119d2dd32607c6b006d9f6e3405d3a889fcf3ebb7ed9c4'
)
