_essential_indices":[0,1,2,3,4],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Hen phế quản mạn, chưa kiểm soát, nghi bỏ thuốc dự phòng","credit":"full"},{"text":"Bệnh phổi tắc nghẽn mạn tính (COPD) thuần túy","credit":"none"},{"text":"Suy tim trái","credit":"none"},{"text":"Thuyên tắc phổi","credit":"none"},{"text":"Viêm phế quản cấp","credit":"none"}],"bd":[{"text":"Háo suyễn","credit":"full"},{"text":"Phế ung","credit":"none"},{"text":"Phế nuy","credit":"none"},{"text":"Kết hung","credit":"none"},{"text":"Đàm ẩm","credit":"none"}],"bc":[{"text":"Lý – Hư – Hàn","credit":"full"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"},{"text":"Biểu – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Phế thận khí hư","credit":"full"},{"text":"Hàn đàm trở phế","credit":"none"},{"text":"Nhiệt đàm uất phế","credit":"none"},{"text":"Phế khí hư","credit":"none"},{"text":"Tâm thận dương hư","credit":"none"}],"phap":[{"text":"Bổ phế ích thận, nạp khí bình suyễn","credit":"full"},{"text":"Ôn phế tán hàn, hóa đàm","credit":"none"},{"text":"Thanh nhiệt hóa đàm, bình suyễn","credit":"none"},{"text":"Bổ phế khí, cố biểu","credit":"none"},{"text":"Ôn dương lợi thủy","credit":"none"}],"phuong":[{"text":"Bổ phế thang hợp Thận khí hoàn","credit":"full"},{"text":"Sinh mạch tán hợp Thận khí hoàn","credit":"partial"},{"text":"Tiểu thanh long thang","credit":"none"},{"text":"Định suyễn thang","credit":"none"},{"text":"Ngọc bình phong tán","credit":"none"}],"huyet":[{"text":"Phế du","credit":"full"},{"text":"Thận du","credit":"full"},{"text":"Định suyễn","credit":"full"},{"text":"Khí hải","credit":"full"},{"text":"Túc tam lý","credit":"full"},{"text":"Thái xung","credit":"none"},{"text":"Hợp cốc","credit":"none"},{"text":"Phong long","credit":"none"}]},"action_options":[{"text":"Đánh giá mức độ kiểm soát hen, kỹ thuật dùng ống xịt, tái khởi trị thuốc dự phòng ICS hoặc ICS kết hợp LABA theo bậc điều trị GINA","time_minutes":10,"grade":"recommended","rationale":"Hen mạn cần thuốc kiểm soát, không chỉ cắt cơn."},{"text":"Đo SpO2, PEF, dặn dấu hiệu nặng cần đến cấp cứu ngay (nói từng từ, tím tái, lơ mơ)","time_minutes":5,"grade":"recommended","rationale":"Phát hiện sớm cơn hen cấp nặng."},{"text":"Dùng thuốc YHCT Bổ phế thang hợp Thận khí hoàn gia giảm ngoài cơn","time_minutes":10,"grade":"recommended","rationale":"Bổ phế ích thận, nạp khí, giảm tái phát."},{"text":"Châm cứu Phế du, Thận du, Định suyễn, Khí hải, Túc tam lý (có thể cứu ngoài cơn)","time_minutes":20,"grade":"recommended","rationale":"Bổ phế thận, cải thiện chức năng hô hấp."},{"text":"Tập thở bụng, thở chúm môi, tư vấn tiêm vắc-xin cúm và phế cầu","time_minutes":10,"grade":"recommended","rationale":"Phòng đợt kịch phát, nâng cao thể trạng."},{"text":"Xác định và tránh yếu tố khởi phát (lạnh, khói, dị nguyên), tái khám sau 2 đến 4 tuần","time_minutes":5,"grade":"recommended","rationale":"Duy trì kiểm soát hen lâu dài."},{"text":"Chụp CT ngực có cản quang","time_minutes":40,"grade":"waste","rationale":"Không có chỉ định."},{"text":"Chỉ dùng thuốc cắt cơn kéo dài và để người bệnh tự ngưng thuốc dự phòng","time_minutes":2,"grade":"harmful","rationale":"Tăng nguy cơ cơn hen nặng và tử vong."},{"text":"Dùng thuốc chứa Ma hoàng liều cao hoặc kéo dài khi có tăng huyết áp","time_minutes":2,"grade":"harmful","rationale":"Ma hoàng có ephedrin, tăng huyết áp, loạn nhịp; không phù hợp thể hư."}],"teaching_explanation":"Hen phế quản mạn cần thuốc kiểm soát theo bậc GINA; bỏ thuốc dự phòng là nguyên nhân tái phát thường gặp. Thể Phế thận khí hư: khó thở khi gắng sức, hít vào ngắn, sợ lạnh, mỏi lưng gối, lưỡi nhạt, mạch trầm tế, dùng bổ phế ích thận nạp khí ngoài cơn. Cơn nặng cần xử trí cấp cứu YHHĐ; thận trọng Ma hoàng ở người tăng huyết áp."}'::jsonb,
