values (
  'yhct-kham-003',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-003","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nam 46 tuổi đau bụng quặn rồi đi tiêu phân lỏng lúc rạng sáng nhiều tháng","setting":"chamcuu","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":46,"sex":"nam","patient_label":"Người bệnh mô phỏng Trần Đ. K."},"presentation":{"intro":"Phòng châm cứu YHCT. Ông là tài xế, đến khám vì đi tiêu phân lỏng nhiều lần vào rạng sáng khoảng 5 tháng, đau bụng quặn rồi đi, tay chân lạnh.","place":"Phòng châm cứu YHCT","clock":"14:15","night":false},"vitals":{"hr":72,"sbp":118,"dbp":72,"rr":16,"temperature_c":36.6,"spo2":98},"history":[{"question":"Đi ngoài mấy lần một ngày, phân thế nào, có máu hay nhầy không?","response":"Khoảng 3 đến 4 lần, nhiều nhất lúc 4 đến 5 giờ sáng, phân sệt, không máu, không nhầy."},{"question":"Có đau bụng, sốt, sụt cân, tiêu đêm đánh thức không?","response":"Đau quặn quanh rốn rồi đi, sau đó hết đau, không sốt, cân nặng ổn định."},{"question":"Sợ lạnh, tay chân lạnh, đau lưng, tiểu đêm, kém ăn?","response":"Sợ lạnh, chân tay lạnh, đau mỏi lưng, tiểu đêm, ăn kém, ăn đồ lạnh là đi."},{"question":"Có đi du lịch, dùng kháng sinh, thuốc nhuận tràng, rượu bia gần đây?","response":"Không đi đâu xa, không dùng kháng sinh, thỉnh thoảng uống bia."},{"question":"Tiền sử gia đình ung thư đại tràng, viêm ruột, bệnh celiac?","response":"Không có."},{"question":"Có dùng thuốc cầm tiêu (loperamide) tự mua không?","response":"Thỉnh thoảng uống khi đi nhiều, đỡ vài hôm lại tái phát."}],"examination":[{"group":"V","item":"Thần sắc, thể trạng","finding":"Sắc mặt vàng nhợt, người gầy vừa, tinh thần mệt."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt bệu, rêu trắng mỏng, có dấu răng."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Giọng nhỏ, hơi thở không hôi."},{"group":"T","item":"Mạch","finding":"Mạch trầm tế nhược, bộ xích yếu."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, không chướng, ấn nhẹ vùng quanh rốn thấy thích ấm, không phản ứng thành bụng, không khối."},{"group":"K","item":"Sờ tay chân, thăm hậu môn","finding":"Tay chân lạnh, thăm trực tràng không khối, không máu."}],"investigations":[{"name":"Công thức máu, CRP","duration_minutes":10,"result":"Hb 14,1 g/dL, bạch cầu bình thường, CRP 2 mg/L."},{"name":"Calprotectin phân","duration_minutes":10,"result":"Dưới 50 microgam/g, bình thường."},{"name":"Soi, cấy phân, tìm ký sinh trùng","duration_minutes":10,"result":"Âm tính."},{"name":"TSH, kháng thể kháng transglutaminase mô","duration_minutes":10,"result":"TSH bình thường, âm tính."},{"name":"CT bụng chậu có cản quang để tìm nguyên nhân","duration_minutes":40,"result":"Không có chỉ định, không có dấu hiệu báo động."}],"choices":{"diagnosis":{"ydx":["Cường giáp","Bệnh Crohn","Ung thư đại tràng","Viêm loét đại trực tràng chảy máu","Tiêu chảy mạn chức năng (hội chứng ruột kích thích thể tiêu chảy), đã loại trừ viêm ruột và nhiễm trùng"],"bd":["Lỵ","Hoắc loạn","Tiện bí","Tiết tả (Ngũ canh tả)","Phúc thống"],"bc":["Lý – Hư – Nhiệt","Lý – Hư – Hàn","Biểu – Thực – Hàn","Biểu – Hư – Hàn","Lý – Thực – Nhiệt"],"the":["Tỳ thận dương hư","Thấp nhiệt","Can khí phạm tỳ","Thực tích","Tỳ vị hư nhược"],"phap":["Ôn bổ tỳ thận, cố sáp chỉ tả","Sơ can kiện tỳ","Tiêu thực đạo trệ","Thanh nhiệt lợi thấp","Kiện tỳ, ích khí, hóa thấp"],"phuong":["Cát căn cầm liên thang","Phụ tử lý trung thang","Bảo hòa hoàn","Thống tả yếu phương","Tứ thần hoàn"],"huyet":["Tỳ du","Quan nguyên","Phong trì","Liệt khuyết","Hợp cốc","Thiên khu","Túc tam lý","Mệnh môn"]},"actions":["Dùng thuốc thanh nhiệt lợi thấp, hàn lương kéo dài cho thể dương hư","Hỏi và loại trừ dấu hiệu báo động (máu trong phân, sụt cân, thiếu máu, tiêu đêm, tiền sử gia đình) trước khi kết luận chức năng","Hướng dẫn giữ ấm bụng và lưng, ăn ấm, chia nhỏ bữa","Tư vấn bù dịch, tránh thức ăn lạnh, kích thích, rượu bia, theo dõi nhật ký ăn uống và phân","Dùng Tứ thần hoàn gia giảm theo thể Tỳ thận dương hư, theo dõi đáp ứng","Tiếp tục tự uống loperamide kéo dài khi chưa loại trừ nhiễm trùng, viêm ruột","Hẹn tái khám, chuyển nội soi đại tràng nếu không đáp ứng hoặc xuất hiện dấu hiệu báo động","Cứu hoặc châm Thiên khu, Quan nguyên, Túc tam lý, Mệnh môn, Tỳ du","Chụp CT bụng chậu có cản quang"]}}'::jsonb,
  'a8009e6de10316f55bf982d4b4285b33f39810e19d3fd8a780918ac1350e5b0e'
)
