:2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Tiêu chảy mạn chức năng (hội chứng ruột kích thích thể tiêu chảy), đã loại trừ viêm ruột và nhiễm trùng","credit":"full"},{"text":"Bệnh Crohn","credit":"none"},{"text":"Viêm loét đại trực tràng chảy máu","credit":"none"},{"text":"Cường giáp","credit":"none"},{"text":"Ung thư đại tràng","credit":"none"}],"bd":[{"text":"Tiết tả (Ngũ canh tả)","credit":"full"},{"text":"Lỵ","credit":"none"},{"text":"Tiện bí","credit":"none"},{"text":"Hoắc loạn","credit":"none"},{"text":"Phúc thống","credit":"none"}],"bc":[{"text":"Lý – Hư – Hàn","credit":"full"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"},{"text":"Biểu – Hư – Hàn","credit":"none"}],"the":[{"text":"Tỳ thận dương hư","credit":"full"},{"text":"Tỳ vị hư nhược","credit":"none"},{"text":"Can khí phạm tỳ","credit":"none"},{"text":"Thấp nhiệt","credit":"none"},{"text":"Thực tích","credit":"none"}],"phap":[{"text":"Ôn bổ tỳ thận, cố sáp chỉ tả","credit":"full"},{"text":"Kiện tỳ, ích khí, hóa thấp","credit":"none"},{"text":"Sơ can kiện tỳ","credit":"none"},{"text":"Thanh nhiệt lợi thấp","credit":"none"},{"text":"Tiêu thực đạo trệ","credit":"none"}],"phuong":[{"text":"Tứ thần hoàn","credit":"full"},{"text":"Phụ tử lý trung thang","credit":"partial"},{"text":"Thống tả yếu phương","credit":"none"},{"text":"Cát căn cầm liên thang","credit":"none"},{"text":"Bảo hòa hoàn","credit":"none"}],"huyet":[{"text":"Thiên khu","credit":"full"},{"text":"Quan nguyên","credit":"full"},{"text":"Túc tam lý","credit":"full"},{"text":"Mệnh môn","credit":"full"},{"text":"Tỳ du","credit":"full"},{"text":"Phong trì","credit":"none"},{"text":"Liệt khuyết","credit":"none"},{"text":"Hợp cốc","credit":"none"}]},"action_options":[{"text":"Hỏi và loại trừ dấu hiệu báo động (máu trong phân, sụt cân, thiếu máu, tiêu đêm, tiền sử gia đình) trước khi kết luận chức năng","time_minutes":5,"grade":"recommended","rationale":"Tiêu chảy mạn cần loại trừ nguyên nhân thực tổn."},{"text":"Tư vấn bù dịch, tránh thức ăn lạnh, kích thích, rượu bia, theo dõi nhật ký ăn uống và phân","time_minutes":5,"grade":"recommended","rationale":"Giảm yếu tố khởi phát."},{"text":"Dùng Tứ thần hoàn gia giảm theo thể Tỳ thận dương hư, theo dõi đáp ứng","time_minutes":10,"grade":"recommended","rationale":"Ôn thận kiện tỳ, cố sáp chỉ tả."},{"text":"Cứu hoặc châm Thiên khu, Quan nguyên, Túc tam lý, Mệnh môn, Tỳ du","time_minutes":25,"grade":"recommended","rationale":"Ôn dương, kiện tỳ, cố tràng."},{"text":"Hướng dẫn giữ ấm bụng và lưng, ăn ấm, chia nhỏ bữa","time_minutes":5,"grade":"recommended","rationale":"Hỗ trợ điều trị theo YHCT."},{"text":"Hẹn tái khám, chuyển nội soi đại tràng nếu không đáp ứng hoặc xuất hiện dấu hiệu báo động","time_minutes":5,"grade":"recommended","rationale":"Kiểm soát nguy cơ bỏ sót bệnh thực tổn."},{"text":"Chụp CT bụng chậu có cản quang","time_minutes":40,"grade":"waste","rationale":"Không có chỉ định."},{"text":"Tiếp tục tự uống loperamide kéo dài khi chưa loại trừ nhiễm trùng, viêm ruột","time_minutes":2,"grade":"harmful","rationale":"Che lấp bệnh, nguy cơ giãn đại tràng nhiễm độc nếu viêm ruột nặng."},{"text":"Dùng thuốc thanh nhiệt lợi thấp, hàn lương kéo dài cho thể dương hư","time_minutes":2,"grade":"harmful","rationale":"Làm tổn thương thêm dương khí, bệnh nặng hơn."}],"teaching_explanation":"Tiêu chảy mạn trên 4 tuần cần loại trừ nhiễm trùng, viêm ruột (calprotectin), bệnh celiac, cường giáp và dấu hiệu báo động trước khi kết luận thể chức năng. Thể Tỳ thận dương hư (Ngũ canh tả): tiêu chảy rạng sáng, sợ lạnh, mỏi lưng, lưỡi nhạt bệu, mạch trầm tế nhược, dùng Tứ thần hoàn ôn bổ tỳ thận cố sáp. Không dùng thuốc cầm tiêu bừa bãi."}'::jsonb,
