  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-004","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nữ 38 tuổi nghẹt mũi, chảy mũi trong dai dẳng, hay cảm lạnh","setting":"chamcuu","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":38,"sex":"nữ","patient_label":"Người bệnh mô phỏng Lê T. M."},"presentation":{"intro":"Phòng châm cứu YHCT. Chị là nhân viên văn phòng, nghẹt mũi, chảy dịch mũi trong dai dẳng khoảng 6 tháng, đau nặng vùng gốc mũi, hay cảm lạnh.","place":"Phòng châm cứu YHCT","clock":"10:20","night":false},"vitals":{"hr":78,"sbp":114,"dbp":70,"rr":16,"temperature_c":36.7,"spo2":99},"history":[{"question":"Nghẹt mũi, chảy mũi kéo dài bao lâu? Dịch mũi màu gì?","response":"Khoảng 6 tháng, dịch trong hoặc trắng đục dai, nghẹt mũi nặng hơn khi gặp lạnh."},{"question":"Có đau nặng vùng má, trán, giảm mùi, chảy dịch xuống họng?","response":"Nặng vùng gốc mũi và má nhẹ, giảm mùi, chảy dịch xuống họng gây húng hắng."},{"question":"Có sốt cao, sưng quanh mắt, nhìn đôi, đau đầu dữ dội?","response":"Không sốt, không sưng mắt, thị lực bình thường."},{"question":"Sợ lạnh, dễ cảm, hay hắt hơi buổi sáng, mệt?","response":"Sợ gió lạnh, dễ cảm, hắt hơi buổi sáng, người mệt, ra mồ hôi tay."},{"question":"Đã dùng kháng sinh, thuốc xịt mũi co mạch, corticoid xịt?","response":"Dùng thuốc xịt co mạch tự mua mỗi khi nghẹt, một số đợt kháng sinh ngắn."},{"question":"Tiền sử dị ứng, hen, polyp mũi, hút thuốc?","response":"Có viêm mũi dị ứng, không hen, không hút thuốc."}],"examination":[{"group":"V","item":"Thần sắc, vùng mũi","finding":"Sắc mặt hơi nhợt, cánh mũi đỏ nhẹ do dùng thuốc xịt."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, rêu trắng mỏng."},{"group":"M","item":"Giọng nói","finding":"Giọng nói nghẹt mũi, nhỏ."},{"group":"T","item":"Mạch","finding":"Mạch tế nhược, hơi trì."},{"group":"K","item":"Nội soi mũi","finding":"Niêm mạc mũi nhợt phù nề, dịch nhầy trong ở khe giữa, không polyp, không mủ đặc."},{"group":"K","item":"Ấn đau các xoang, khám mắt","finding":"Ấn đau nhẹ vùng gốc mũi, không đỏ sưng quanh mắt, vận nhãn bình thường."}],"investigations":[{"name":"Nội soi tai mũi họng (đã ghi nhận ở trên) và khám chuyên khoa","duration_minutes":20,"result":"Phù nề niêm mạc khe giữa, dịch nhầy, không polyp."},{"name":"CT xoang không cản quang","duration_minutes":40,"result":"Dày niêm mạc xoang hàm và sàng hai bên, không mức dịch khí, không biến chứng."},{"name":"Test lẩy da dị nguyên","duration_minutes":10,"result":"Dương tính với mạt nhà."},{"name":"Công thức máu, CRP","duration_minutes":10,"result":"Bình thường."},{"name":"MRI sọ não có cản từ để chẩn đoán viêm xoang mạn","duration_minutes":10,"result":"Không có chỉ định khi không có dấu hiệu biến chứng."}],"choices":{"diagnosis":{"ydx":["Lệch vách ngăn đơn thuần","U vùng mũi xoang","Polyp mũi","Viêm xoang cấp do vi khuẩn","Viêm mũi xoang mạn không polyp, nền viêm mũi dị ứng"],"bd":["Tỵ uyên","Tỵ nục","Hầu tý","Tỵ cừu","Tỵ khâu"],"bc":["Biểu – Thực – Nhiệt","Lý – Thực – Nhiệt","Biểu – Thực – Hàn","Lý – Hư – Nhiệt","Lý – Hư – Hàn"],"the":["Phế khí hư hàn","Tỳ khí hư","Tỳ vị thấp nhiệt","Đởm kinh uất nhiệt","Phế kinh phong nhiệt"],"phap":["Sơ phong thanh nhiệt, thông khiếu","Thanh đởm, tả nhiệt, thông khiếu","Thanh nhiệt lợi thấp, thông khiếu","Kiện tỳ ích khí","Ôn bổ phế khí, tán hàn thông khiếu"],"phuong":["Long đởm tả can thang","Bổ trung ích khí thang","Ngọc bình phong tán hợp Thương nhĩ tử tán","Tân di thanh phế thang","Ôn phế chỉ lưu đan"],"huyet":["Túc tam lý","Hợp cốc","Nghênh hương","Phế du","Thái xung","Hành gian","Dương lăng tuyền","Ấn đường"]},"actions":["Hướng dẫn rửa mũi bằng nước muối sinh lý, dùng corticoid xịt mũi dài ngày theo chỉ định","Dùng kháng sinh kéo dài, lặp lại không có bằng chứng nhiễm khuẩn","Châm Nghênh hương, Ấn đường, Hợp cốc, Phế du, Túc tam lý","Điều trị viêm mũi dị ứng, tránh dị nguyên mạt nhà","Tiếp tục dùng thuốc xịt co mạch nhiều tuần","Ngưng thuốc xịt co mạch dùng kéo dài, giải thích nguy cơ viêm mũi do thuốc","Chụp MRI sọ não có cản từ","Dùng Ôn phế chỉ lưu đan gia giảm theo thể Phế khí hư hàn","Dặn dấu hiệu cần đến ngay: sưng đỏ quanh mắt, nhìn đôi, đau đầu dữ dội, sốt cao"]}}'::jsonb,
