values (
  'yhct-kham-004',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-004","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-004-1","resource_type":"other","source":"Fokkens WJ, et al. European Position Paper on Rhinosinusitis and Nasal Polyps (EPOS), Rhinology.","title":"Fokkens WJ, et al. European Position Paper on Rhinosinusitis and Nasal Polyps (EPOS), Rhinology.","organization":null,"year_version":null,"citation":"Fokkens WJ, et al. European Position Paper on Rhinosinusitis and Nasal Polyps (EPOS), Rhinology.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-004-2","resource_type":"other","source":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh tai mũi họng.","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh tai mũi họng.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh tai mũi họng.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[1,3,4],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm mũi xoang mạn không polyp, nền viêm mũi dị ứng","credit":"full"},{"text":"Viêm xoang cấp do vi khuẩn","credit":"none"},{"text":"Polyp mũi","credit":"none"},{"text":"U vùng mũi xoang","credit":"none"},{"text":"Lệch vách ngăn đơn thuần","credit":"none"}],"bd":[{"text":"Tỵ uyên","credit":"full"},{"text":"Tỵ cừu","credit":"none"},{"text":"Tỵ khâu","credit":"none"},{"text":"Tỵ nục","credit":"none"},{"text":"Hầu tý","credit":"none"}],"bc":[{"text":"Lý – Hư – Hàn","credit":"full"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Biểu – Thực – Nhiệt","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Phế khí hư hàn","credit":"full"},{"text":"Phế kinh phong nhiệt","credit":"none"},{"text":"Đởm kinh uất nhiệt","credit":"none"},{"text":"Tỳ vị thấp nhiệt","credit":"none"},{"text":"Tỳ khí hư","credit":"none"}],"phap":[{"text":"Ôn bổ phế khí, tán hàn thông khiếu","credit":"full"},{"text":"Sơ phong thanh nhiệt, thông khiếu","credit":"none"},{"text":"Thanh đởm, tả nhiệt, thông khiếu","credit":"none"},{"text":"Thanh nhiệt lợi thấp, thông khiếu","credit":"none"},{"text":"Kiện tỳ ích khí","credit":"none"}],"phuong":[{"text":"Ôn phế chỉ lưu đan","credit":"full"},{"text":"Ngọc bình phong tán hợp Thương nhĩ tử tán","credit":"partial"},{"text":"Tân di thanh phế thang","credit":"none"},{"text":"Long đởm tả can thang","credit":"none"},{"text":"Bổ trung ích khí thang","credit":"none"}],"huyet":[{"text":"Nghênh hương","credit":"full"},{"text":"Ấn đường","credit":"full"},{"text":"Hợp cốc","credit":"full"},{"text":"Phế du","credit":"full"},{"text":"Túc tam lý","credit":"full"},{"text":"Thái xung","credit":"none"},{"text":"Hành gian","credit":"none"},{"text":"Dương lăng tuyền","credit":"none"}]},"action_options":[{"text":"Hướng dẫn rửa mũi bằng nước muối sinh lý, dùng corticoid xịt mũi dài ngày theo chỉ định","time_minutes":10,"grade":"recommended","rationale":"Nền tảng điều trị viêm mũi xoang mạn không polyp."},{"text":"Ngưng thuốc xịt co mạch dùng kéo dài, giải thích nguy cơ viêm mũi do thuốc","time_minutes":5,"grade":"recommended","rationale":"Tránh viêm mũi do thuốc và nghẹt mũi hồi ứng."},{"text":"Điều trị viêm mũi dị ứng, tránh dị nguyên mạt nhà","time_minutes":10,"grade":"recommended","rationale":"Giảm yếu tố nền gây viêm."},{"text":"Dùng Ôn phế chỉ lưu đan gia giảm theo thể Phế khí hư hàn","time_minutes":10,"grade":"recommended","rationale":"Ôn phế tán hàn, thông khiếu."},{"text":"Châm Nghênh hương, Ấn đường, Hợp cốc, Phế du, Túc tam lý","time_minutes":20,"grade":"recommended","rationale":"Thông mũi khiếu, bổ phế khí."},{"text":"Dặn dấu hiệu cần đến ngay: sưng đỏ quanh mắt, nhìn đôi, đau đầu dữ dội, sốt cao","time_minutes":5,"grade":"recommended","rationale":"Phát hiện biến chứng nội sọ, hốc mắt."},{"text":"Chụp MRI sọ não có cản từ","time_minutes":50,"grade":"waste","rationale":"Không có chỉ định."},{"text":"Dùng kháng sinh kéo dài, lặp lại không có bằng chứng nhiễm khuẩn","time_minutes":2,"grade":"harmful","rationale":"Kháng thuốc, tác dụng phụ không cần thiết."},{"text":"Tiếp tục dùng thuốc xịt co mạch nhiều tuần","time_minutes":2,"grade":"harmful","rationale":"Viêm mũi do thuốc, teo niêm mạc."}],"teaching_explanation":"Viêm mũi xoang mạn là viêm trên 12 tuần, nền tảng điều trị là rửa mũi và corticoid xịt mũi; kháng sinh chỉ khi có bằng chứng nhiễm khuẩn. Thể Phế khí hư hàn: chảy mũi trong dai, sợ lạnh, dễ cảm, lưỡi nhạt, mạch tế nhược, dùng Ôn phế chỉ lưu đan. Cần nhận biết dấu hiệu biến chứng và tránh lạm dụng thuốc co mạch."}'::jsonb,
  'fd06592af236efddd731ec1e583b7538bbe67397bd4bc15b7948329ffa232f1f'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'yhct-kham-005',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-005","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nam 47 tuổi đại tiện ra máu đỏ tươi, hậu môn nóng rát","setting":"phongkham","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":47,"sex":"nam","patient_label":"Người bệnh mô phỏng Phạm Q. H."},"presentation":{"intro":"Phòng khám Ngoại YHCT. Ông là nhân viên kinh doanh hay tiếp khách, đến khám vì đại tiện ra máu đỏ tươi nhỏ giọt cuối bãi, hậu môn nóng rát khoảng 3 tuần.","place":"Phòng khám Ngoại YHCT","clock":"08:55","night":false},"vitals":{"hr":78,"sbp":128,"dbp":80,"rr":16,"temperature_c":36.8,"spo2":98},"history":[{"question":"Máu ra thế nào: nhỏ giọt, phun, lẫn trong phân, màu gì?","response":"Máu đỏ tươi nhỏ giọt cuối bãi, dính giấy, không lẫn trong phân."},{"question":"Có đau hậu môn, búi nhô ra, ngứa, nóng rát không?","response":"Hậu môn nóng rát, có búi mềm nhô ra khi rặn, tự co lên, không đau nhiều."},{"question":"Có thay đổi thói quen đại tiện, sụt cân, phân nhỏ dẹt, thiếu máu?","response":"Hơi táo, không sụt cân, phân không nhỏ dẹt, không chóng mặt."},{"question":"Ăn uống, rượu bia, ngồi lâu, táo bón?","response":"Hay ăn cay, uống rượu bia khi tiếp khách, ngồi lâu, đại tiện táo."},{"question":"Tiền sử gia đình ung thư đại tràng, đã nội soi đại tràng chưa?","response":"Không ai mắc; chưa nội soi bao giờ."},{"question":"Có dùng thuốc chống đông hoặc thuốc kháng tiểu cầu?","response":"Không dùng."}],"examination":[{"group":"V","item":"Thần sắc","finding":"Sắc mặt hơi đỏ, người khỏe, không xanh xao."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi đỏ, rêu vàng nhờn."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Giọng rõ to, hơi thở hơi hôi do uống rượu."},{"group":"T","item":"Mạch","finding":"Mạch hoạt sác."},{"group":"K","item":"Nhìn và khám hậu môn","finding":"Búi trĩ nội độ II ở vị trí 3 giờ và 7 giờ, niêm mạc đỏ, dễ chảy máu, không huyết khối ngoại, không nứt hậu môn."},{"group":"K","item":"Thăm trực tràng","finding":"Không khối trong trực tràng, găng dính máu đỏ tươi, trương lực cơ thắt bình thường."}],"investigations":[{"name":"Công thức máu","duration_minutes":10,"result":"Hb 14,6 g/dL, bình thường."},{"name":"Xét nghiệm máu ẩn trong phân (FIT)","duration_minutes":10,"result":"Dương tính do chảy máu hậu môn, cần soi đại tràng loại trừ."},{"name":"Nội soi đại tràng","duration_minutes":20,"result":"Trĩ nội độ II chảy máu, không polyp, không khối u."},{"name":"Đông máu cơ bản","duration_minutes":10,"result":"Bình thường."},{"name":"CT bụng chậu có cản quang","duration_minutes":40,"result":"Không có chỉ định để chẩn đoán trĩ."}],"choices":{"diagnosis":{"ydx":["Bệnh trĩ nội độ II có chảy máu, đã loại trừ tổn thương đại trực tràng","Nứt kẽ hậu môn","Ung thư đại trực tràng","Viêm loét đại trực tràng chảy máu","Polyp đại tràng"],"bd":["Tiện huyết do lỵ","Táo bón","Tả lỵ","Phúc thống","Trĩ (Tạng độc, Trĩ nội)"],"bc":["Lý – Hư – Nhiệt","Biểu – Thực – Nhiệt","Biểu – Thực – Hàn","Lý – Thực – Nhiệt","Lý – Hư – Hàn"],"the":["Thấp nhiệt hạ chú (Huyết nhiệt)","Huyết ứ","Khí huyết hư","Tỳ hư khí hãm","Phong nhiệt"],"phap":["Thăng đề trung khí","Thanh nhiệt lợi thấp, lương huyết chỉ huyết","Sơ phong thanh nhiệt","Bổ khí dưỡng huyết","Hoạt huyết hóa ứ"],"phuong":["Bổ trung ích khí thang","Hòe giác hoàn","Quy tỳ thang","Huyết phủ trục ứ thang","Hòe hoa tán gia giảm"],"huyet":["Phong trì","Nội quan","Khổng tối","Liệt khuyết","Trường cường","Thái dương","Đại trường du","Thừa sơn"]},"actions":["Khám hậu môn trực tràng, nội soi đại tràng loại trừ ung thư, polyp ở người trên 45 tuổi có chảy máu","Tự cho là trĩ rồi bỏ qua nội soi khi có máu trong phân ở tuổi trên 45","Hẹn tái khám, đánh giá thủ thuật (thắt trĩ cao su) nếu triệu chứng kéo dài","Châm Thừa sơn, Trường cường, Đại trường du, Khổng tối","Chụp CT bụng chậu có cản quang","Ngâm nước ấm, dùng thuốc tại chỗ và thuốc tăng bền thành mạch (flavonoid) theo chỉ định","Tư vấn ăn nhiều rau xơ, uống đủ nước, tập thói quen đại tiện, tránh rặn lâu","Dùng Hòe hoa tán gia giảm theo thể Thấp nhiệt hạ chú","Tiếp tục ăn cay, rượu bia, dùng thuốc ôn nhiệt"]}}'::jsonb,
  'e318403b487df91e0bf3a66110fa418bc3542ae54ffb38769ec1906d40430f64'
)
