values (
  'yhct-kham-005',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-005","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-005-1","resource_type":"other","source":"Hội Ngoại khoa Việt Nam, hướng dẫn chẩn đoán và điều trị bệnh trĩ.","title":"Hội Ngoại khoa Việt Nam, hướng dẫn chẩn đoán và điều trị bệnh trĩ.","organization":null,"year_version":null,"citation":"Hội Ngoại khoa Việt Nam, hướng dẫn chẩn đoán và điều trị bệnh trĩ.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-005-2","resource_type":"other","source":"Davis BR, et al. The American Society of Colon and Rectal Surgeons Clinical Practice Guidelines for the Management of Hemorrhoids. Dis Colon Rectum 2018.","title":"Davis BR, et al. The American Society of Colon and Rectal Surgeons Clinical Practice Guidelines for the Management of Hemorrhoids. Dis Colon Rectum 2018.","organization":null,"year_version":null,"citation":"Davis BR, et al. The American Society of Colon and Rectal Surgeons Clinical Practice Guidelines for the Management of Hemorrhoids. Dis Colon Rectum 2018.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[1,3,4,5],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Bệnh trĩ nội độ II có chảy máu, đã loại trừ tổn thương đại trực tràng","credit":"full"},{"text":"Ung thư đại trực tràng","credit":"none"},{"text":"Nứt kẽ hậu môn","credit":"none"},{"text":"Polyp đại tràng","credit":"none"},{"text":"Viêm loét đại trực tràng chảy máu","credit":"none"}],"bd":[{"text":"Trĩ (Tạng độc, Trĩ nội)","credit":"full"},{"text":"Tiện huyết do lỵ","credit":"none"},{"text":"Táo bón","credit":"none"},{"text":"Phúc thống","credit":"none"},{"text":"Tả lỵ","credit":"none"}],"bc":[{"text":"Lý – Thực – Nhiệt","credit":"full"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Biểu – Thực – Nhiệt","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"}],"the":[{"text":"Thấp nhiệt hạ chú (Huyết nhiệt)","credit":"full"},{"text":"Khí huyết hư","credit":"none"},{"text":"Tỳ hư khí hãm","credit":"none"},{"text":"Phong nhiệt","credit":"none"},{"text":"Huyết ứ","credit":"none"}],"phap":[{"text":"Thanh nhiệt lợi thấp, lương huyết chỉ huyết","credit":"full"},{"text":"Bổ khí dưỡng huyết","credit":"none"},{"text":"Thăng đề trung khí","credit":"none"},{"text":"Sơ phong thanh nhiệt","credit":"none"},{"text":"Hoạt huyết hóa ứ","credit":"none"}],"phuong":[{"text":"Hòe hoa tán gia giảm","credit":"full"},{"text":"Hòe giác hoàn","credit":"partial"},{"text":"Bổ trung ích khí thang","credit":"none"},{"text":"Quy tỳ thang","credit":"none"},{"text":"Huyết phủ trục ứ thang","credit":"none"}],"huyet":[{"text":"Thừa sơn","credit":"full"},{"text":"Trường cường","credit":"full"},{"text":"Đại trường du","credit":"full"},{"text":"Khổng tối","credit":"full"},{"text":"Phong trì","credit":"none"},{"text":"Liệt khuyết","credit":"none"},{"text":"Thái dương","credit":"none"},{"text":"Nội quan","credit":"none"}]},"action_options":[{"text":"Khám hậu môn trực tràng, nội soi đại tràng loại trừ ung thư, polyp ở người trên 45 tuổi có chảy máu","time_minutes":45,"grade":"recommended","rationale":"Chảy máu hậu môn cần loại trừ tổn thương khác."},{"text":"Tư vấn ăn nhiều rau xơ, uống đủ nước, tập thói quen đại tiện, tránh rặn lâu","time_minutes":5,"grade":"recommended","rationale":"Giảm táo bón, giảm áp lực búi trĩ."},{"text":"Ngâm nước ấm, dùng thuốc tại chỗ và thuốc tăng bền thành mạch (flavonoid) theo chỉ định","time_minutes":10,"grade":"recommended","rationale":"Giảm triệu chứng, hạn chế chảy máu."},{"text":"Dùng Hòe hoa tán gia giảm theo thể Thấp nhiệt hạ chú","time_minutes":10,"grade":"recommended","rationale":"Thanh nhiệt lợi thấp, lương huyết chỉ huyết."},{"text":"Châm Thừa sơn, Trường cường, Đại trường du, Khổng tối","time_minutes":20,"grade":"recommended","rationale":"Điều hòa khí huyết vùng hậu môn, giảm sưng chảy máu."},{"text":"Hẹn tái khám, đánh giá thủ thuật (thắt trĩ cao su) nếu triệu chứng kéo dài","time_minutes":5,"grade":"recommended","rationale":"Điều trị can thiệp khi cần theo độ trĩ."},{"text":"Chụp CT bụng chậu có cản quang","time_minutes":40,"grade":"waste","rationale":"Không có chỉ định."},{"text":"Tự cho là trĩ rồi bỏ qua nội soi khi có máu trong phân ở tuổi trên 45","time_minutes":2,"grade":"harmful","rationale":"Có thể bỏ sót ung thư đại trực tràng."},{"text":"Tiếp tục ăn cay, rượu bia, dùng thuốc ôn nhiệt","time_minutes":2,"grade":"harmful","rationale":"Làm nặng thêm thấp nhiệt, chảy máu tăng."}],"teaching_explanation":"Chảy máu hậu môn ở người trên 45 tuổi cần nội soi đại tràng loại trừ ung thư, polyp trước khi quy cho trĩ. Trĩ nội độ II điều trị bảo tồn: chế độ ăn nhiều xơ, thuốc tăng bền thành mạch, can thiệp nếu thất bại. Thể Thấp nhiệt hạ chú: máu đỏ tươi, hậu môn nóng rát, lưỡi đỏ rêu vàng nhờn, mạch hoạt sác, dùng thanh nhiệt lợi thấp lương huyết chỉ huyết."}'::jsonb,
  '42b595e28d19965d9e8d16e31369a7c0842806292c1140f04ede7db45fbd03c5'
)
