insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'yhct-kham-006',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-006","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nữ 55 tuổi đau đầu thái dương, chóng mặt, mặt đỏ, hay cáu gắt","setting":"chamcuu","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":55,"sex":"nữ","patient_label":"Người bệnh mô phỏng Đỗ T. H."},"presentation":{"intro":"Phòng châm cứu YHCT. Bà là kế toán, đến khám vì đau đầu vùng thái dương, chóng mặt, mặt đỏ, hay cáu gắt khoảng 3 tuần, chưa từng điều trị tăng huyết áp.","place":"Phòng châm cứu YHCT","clock":"15:05","night":false},"vitals":{"hr":84,"sbp":168,"dbp":98,"rr":18,"temperature_c":36.8,"spo2":98},"history":[{"question":"Đau đầu vị trí nào, tính chất, thời điểm, có nặng đột ngột không?","response":"Đau căng vùng thái dương hai bên, tăng khi tức giận, không đau dữ dội đột ngột."},{"question":"Chóng mặt kiểu quay hay mất thăng bằng, có buồn nôn?","response":"Cảm giác choáng váng, đầu nặng, thỉnh thoảng buồn nôn nhẹ, không quay cuồng khi xoay đầu."},{"question":"Có yếu liệt, méo miệng, nói khó, nhìn đôi, ngất, đau ngực?","response":"Không có."},{"question":"Tiền sử tăng huyết áp, tiểu đường, hút thuốc, mãn kinh?","response":"Mãn kinh 3 năm, chưa từng đo huyết áp thường xuyên, bố bị tăng huyết áp."},{"question":"Miệng đắng, mất ngủ, dễ cáu, ù tai, mỏi lưng gối?","response":"Miệng đắng, ngủ ít, dễ cáu, ù tai nhẹ, hay bốc hỏa."},{"question":"Đang dùng thuốc nào, thuốc nam, giảm đau, hormon?","response":"Chỉ uống thuốc giảm đau khi đau đầu."}],"examination":[{"group":"V","item":"Thần sắc","finding":"Mặt đỏ, mắt đỏ, vẻ bực dọc."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi đỏ, rêu vàng mỏng."},{"group":"M","item":"Giọng nói","finding":"Giọng to, nói nhanh, dễ kích động."},{"group":"T","item":"Mạch","finding":"Mạch huyền hữu lực."},{"group":"K","item":"Huyết áp hai tay, nhịp tim","finding":"Huyết áp tay phải 168/98, tay trái 166/96 mmHg, nhịp tim đều."},{"group":"K","item":"Thần kinh","finding":"Tỉnh, vận nhãn bình thường, không rung giật nhãn cầu, sức cơ 5/5, không dấu thần kinh khu trú, nghiệm pháp Romberg âm tính."}],"investigations":[{"name":"Đo huyết áp tại nhà hoặc đo 24 giờ","duration_minutes":10,"result":"Trung bình 24 giờ 158/94 mmHg."},{"name":"Đường huyết, mỡ máu, creatinin, điện giải đồ, TSH","duration_minutes":10,"result":"Cholesterol toàn phần 6,0 mmol/L, đường huyết đói 5,4, creatinin bình thường, K 4,1, TSH bình thường."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp xoang, dày thất trái nhẹ."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Không đạm, không máu."},{"name":"MRI sọ não có cản từ thường quy","duration_minutes":10,"result":"Không có chỉ định khi không có dấu thần kinh khu trú."}],"choices":{"diagnosis":{"ydx":["Đau đầu căng cơ đơn thuần","Chóng mặt tư thế kịch phát lành tính","Cường giáp","Tăng huyết áp nguyên phát độ 2 gây đau đầu, chóng mặt, chưa có dấu tổn thương thần kinh","Đột quỵ não cấp"],"bd":["Trúng phong","Kinh phong","Tâm quý","Huyễn vựng, Đầu thống","Thất miên"],"bc":["Lý – Thực – Nhiệt","Biểu – Thực – Nhiệt","Biểu – Thực – Hàn","Lý – Hư – Hàn","Lý – Hư – Nhiệt"],"the":["Khí huyết hư","Huyết ứ","Thận tinh bất túc","Can dương thượng cang","Đàm thấp trung trở"],"phap":["Bình can tiềm dương, tư dưỡng can thận","Táo thấp hóa đàm, kiện tỳ","Bổ thận điền tinh","Bổ ích khí huyết","Hoạt huyết hóa ứ"],"phuong":["Trấn can tức phong thang","Quy tỳ thang","Bán hạ bạch truật thiên ma thang","Thiên ma câu đằng ẩm","Lục vị địa hoàng hoàn"],"huyet":["Quan nguyên","Thiên khu","Phong trì","Hành gian","Thái xung","Khí hải","Thái khê","Phế du"]},"actions":["Dặn dấu hiệu cần cấp cứu: yếu liệt, méo miệng, nói khó, đau đầu dữ dội đột ngột, đau ngực","Chỉ dùng châm cứu và thuốc thang, tự ngừng thuốc hạ huyết áp","Khởi trị thuốc hạ huyết áp theo bác sĩ, thay đổi lối sống, hẹn đo lại huyết áp sớm","Tư vấn giảm muối, bỏ rượu, vận động đều, ngủ đủ, giảm căng thẳng","Dùng Thiên ma câu đằng ẩm gia giảm theo thể Can dương thượng cang, theo dõi huyết áp","Hạ huyết áp quá nhanh bằng thuốc liều cao ở người cao tuổi chưa có chỉ định cấp cứu","Chụp MRI sọ não có cản từ thường quy","Đo huyết áp chuẩn, loại trừ dấu hiệu đột quỵ, đánh giá tổn thương cơ quan đích","Châm Phong trì, Thái xung, Hành gian, Thái khê"]}}'::jsonb,
  '8887d6eed8d20fe8ac9e1b1cbb4d3d821bcdd809d77d9ba7317e006c488f926d'
)
