tion_essential_indices":[1,3,4,5],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Tăng huyết áp nguyên phát độ 2 gây đau đầu, chóng mặt, chưa có dấu tổn thương thần kinh","credit":"full"},{"text":"Đột quỵ não cấp","credit":"none"},{"text":"Chóng mặt tư thế kịch phát lành tính","credit":"none"},{"text":"Đau đầu căng cơ đơn thuần","credit":"none"},{"text":"Cường giáp","credit":"none"}],"bd":[{"text":"Huyễn vựng, Đầu thống","credit":"full"},{"text":"Trúng phong","credit":"none"},{"text":"Kinh phong","credit":"none"},{"text":"Tâm quý","credit":"none"},{"text":"Thất miên","credit":"none"}],"bc":[{"text":"Lý – Thực – Nhiệt","credit":"full"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Nhiệt","credit":"none"}],"the":[{"text":"Can dương thượng cang","credit":"full"},{"text":"Đàm thấp trung trở","credit":"none"},{"text":"Khí huyết hư","credit":"none"},{"text":"Thận tinh bất túc","credit":"none"},{"text":"Huyết ứ","credit":"none"}],"phap":[{"text":"Bình can tiềm dương, tư dưỡng can thận","credit":"full"},{"text":"Táo thấp hóa đàm, kiện tỳ","credit":"none"},{"text":"Bổ ích khí huyết","credit":"none"},{"text":"Bổ thận điền tinh","credit":"none"},{"text":"Hoạt huyết hóa ứ","credit":"none"}],"phuong":[{"text":"Thiên ma câu đằng ẩm","credit":"full"},{"text":"Trấn can tức phong thang","credit":"partial"},{"text":"Bán hạ bạch truật thiên ma thang","credit":"none"},{"text":"Quy tỳ thang","credit":"none"},{"text":"Lục vị địa hoàng hoàn","credit":"none"}],"huyet":[{"text":"Phong trì","credit":"full"},{"text":"Thái xung","credit":"full"},{"text":"Hành gian","credit":"full"},{"text":"Thái khê","credit":"full"},{"text":"Khí hải","credit":"none"},{"text":"Quan nguyên","credit":"none"},{"text":"Phế du","credit":"none"},{"text":"Thiên khu","credit":"none"}]},"action_options":[{"text":"Đo huyết áp chuẩn, loại trừ dấu hiệu đột quỵ, đánh giá tổn thương cơ quan đích","time_minutes":10,"grade":"recommended","rationale":"Phân tầng nguy cơ tim mạch, loại trừ cấp cứu."},{"text":"Khởi trị thuốc hạ huyết áp theo bác sĩ, thay đổi lối sống, hẹn đo lại huyết áp sớm","time_minutes":10,"grade":"recommended","rationale":"Điều trị nền tảng bắt buộc cho tăng huyết áp độ 2."},{"text":"Dùng Thiên ma câu đằng ẩm gia giảm theo thể Can dương thượng cang, theo dõi huyết áp","time_minutes":10,"grade":"recommended","rationale":"Bình can tiềm dương, hỗ trợ giảm triệu chứng."},{"text":"Châm Phong trì, Thái xung, Hành gian, Thái khê","time_minutes":20,"grade":"recommended","rationale":"Bình can, tiềm dương, giảm đau đầu chóng mặt."},{"text":"Tư vấn giảm muối, bỏ rượu, vận động đều, ngủ đủ, giảm căng thẳng","time_minutes":5,"grade":"recommended","rationale":"Kiểm soát huyết áp lâu dài."},{"text":"Dặn dấu hiệu cần cấp cứu: yếu liệt, méo miệng, nói khó, đau đầu dữ dội đột ngột, đau ngực","time_minutes":5,"grade":"recommended","rationale":"Nhận biết đột quỵ, hội chứng vành cấp."},{"text":"Chụp MRI sọ não có cản từ thường quy","time_minutes":50,"grade":"waste","rationale":"Không có chỉ định."},{"text":"Chỉ dùng châm cứu và thuốc thang, tự ngừng thuốc hạ huyết áp","time_minutes":2,"grade":"harmful","rationale":"Tăng nguy cơ đột quỵ, tổn thương cơ quan đích."},{"text":"Hạ huyết áp quá nhanh bằng thuốc liều cao ở người cao tuổi chưa có chỉ định cấp cứu","time_minutes":2,"grade":"harmful","rationale":"Giảm tưới máu não, ngã, té."}],"teaching_explanation":"Đau đầu chóng mặt kèm tăng huyết áp cần đo huyết áp chuẩn, loại trừ đột quỵ và tổn thương cơ quan đích; điều trị nền tảng là thuốc hạ áp và lối sống. Thể Can dương thượng cang: đau đầu, chóng mặt, mặt đỏ, cáu gắt, miệng đắng, lưỡi đỏ rêu vàng mỏng, mạch huyền hữu lực, dùng Thiên ma câu đằng ẩm. Châm cứu và thuốc thang chỉ phối hợp, không thay thế thuốc hạ áp."}'::jsonb,
  'ebe6527e71ac1370c4f0c947ddf79df51f580d732774e66fbe5e0c247d6de396'
)
