values (
  'yhct-kham-007',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-007","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nam 38 tuổi đau quặn thắt lưng lan xuống bẹn, tiểu buốt, tiểu máu","setting":"phongkham","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":38,"sex":"nam","patient_label":"Người bệnh mô phỏng Vũ M. T."},"presentation":{"intro":"Phòng khám YHCT. Ông là công nhân, đến khám vì cơn đau quặn thắt lưng phải lan xuống bẹn và đùi trong từ sáng, tiểu buốt, nước tiểu hồng.","place":"Phòng khám YHCT","clock":"10:30","night":false},"vitals":{"hr":92,"sbp":136,"dbp":84,"rr":18,"temperature_c":37,"spo2":98},"history":[{"question":"Đau như thế nào, vị trí, lan đi đâu, đau từng cơn hay liên tục?","response":"Đau quặn từng cơn thắt lưng phải lan xuống bẹn, bìu, đùi trong, vật vã không nằm yên."},{"question":"Có sốt, rét run, tiểu đục, tiểu ít hoặc không tiểu được không?","response":"Không sốt, không rét run, nước tiểu hồng, tiểu vẫn được nhưng buốt."},{"question":"Có buồn nôn, nôn, chướng bụng?","response":"Buồn nôn, nôn một lần."},{"question":"Tiền sử sỏi tiết niệu, gút, uống ít nước, làm việc nóng?","response":"Từng đau như vậy 2 năm trước, làm việc ngoài nóng, uống ít nước, ăn nhiều đạm."},{"question":"Có bệnh thận, chỉ có một thận, đang dùng thuốc, dị ứng NSAID?","response":"Không bệnh thận, không dị ứng thuốc đã biết."},{"question":"Miệng khô khát, tiểu vàng sẫm, táo bón?","response":"Khát, tiểu vàng sẫm, hơi táo."}],"examination":[{"group":"V","item":"Thần sắc","finding":"Vẻ mặt đau đớn, vã mồ hôi, trằn trọc."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi đỏ, rêu vàng nhờn."},{"group":"M","item":"Giọng nói","finding":"Rên rỉ, nói ngắt quãng vì đau."},{"group":"T","item":"Mạch","finding":"Mạch huyền sác."},{"group":"K","item":"Khám thận, vùng hông lưng","finding":"Dấu chạm thận và rung thận phải dương tính, ấn đau điểm niệu quản, bụng mềm."},{"group":"K","item":"Dấu hiệu nhiễm trùng, huyết động","finding":"Không sốt, huyết động ổn, không rét run."}],"investigations":[{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Hồng cầu nhiều, bạch cầu ít, nitrit âm tính."},{"name":"Siêu âm hệ tiết niệu","duration_minutes":15,"result":"Giãn đài bể thận phải mức nhẹ, nghi sỏi niệu quản đoạn dưới."},{"name":"CT bụng chậu không cản quang liều thấp","duration_minutes":40,"result":"Sỏi niệu quản phải đoạn 1/3 dưới 5 mm, giãn đài bể thận nhẹ."},{"name":"Creatinin, công thức máu, CRP, điện giải","duration_minutes":10,"result":"Creatinin 88 micromol/L, bạch cầu bình thường, CRP 4 mg/L."},{"name":"CT bụng chậu có cản quang để chẩn đoán sỏi","duration_minutes":40,"result":"Không cần cản quang, tăng nguy cơ không cần thiết."}],"choices":{"diagnosis":{"ydx":["Xoắn tinh hoàn","Viêm bể thận cấp","Phình tách động mạch chủ bụng","Viêm ruột thừa cấp","Cơn đau quặn thận do sỏi niệu quản phải 5 mm, giãn nhẹ, chưa nhiễm trùng"],"bd":["Thạch lâm","Cao lâm","Khí lâm","Lao lâm","Huyết lâm"],"bc":["Lý – Hư – Nhiệt","Lý – Thực – Nhiệt","Biểu – Thực – Hàn","Biểu – Thực – Nhiệt","Lý – Hư – Hàn"],"the":["Thấp nhiệt hạ chú","Thận hư","Khí trệ","Huyết ứ","Hàn thấp"],"phap":["Ôn thận tán hàn","Hoạt huyết hóa ứ, thông lâm","Hành khí giải uất, thông lâm","Thanh nhiệt lợi thấp, bài thạch thông lâm","Bổ thận, lợi thủy"],"phuong":["Lục vị địa hoàng hoàn","Ngọc bình phong tán","Tiểu sài hồ thang","Thạch vi tán","Bát chính tán gia Kim tiền thảo, Hải kim sa"],"huyet":["Thủy đạo","Âm lăng tuyền","Liệt khuyết","Tam âm giao","Bàng quang du","Thái dương","Phong trì","Thận du"]},"actions":["Châm Thận du, Bàng quang du, Thủy đạo, Tam âm giao, Âm lăng tuyền","Dùng Bát chính tán gia Kim tiền thảo, Hải kim sa theo thể Thấp nhiệt hạ chú","Giảm đau bằng NSAID (diclofenac hoặc ketorolac) nếu không chống chỉ định, đánh giá chức năng thận","Chỉ châm cứu, thuốc thang và chờ khi có sốt, rét run hoặc vô niệu","Chụp CT bụng chậu có cản quang","Cho thuốc tống sỏi nội khoa (tamsulosin) cho sỏi niệu quản đoạn xa 5 mm, uống nhiều nước","Hướng dẫn lọc nước tiểu tìm sỏi, hẹn tái khám với bác sĩ tiết niệu, dặn dấu hiệu cần cấp cứu (sốt, rét run, vô niệu, đau tăng)","Đánh giá dấu hiệu nhiễm trùng, thận ứ nước và lưu thông nước tiểu, chụp CT liều thấp","Dùng Mộc thông (Quan mộc thông) hoặc vị chứa acid aristolochic trong bài thuốc lợi niệu"]}}'::jsonb,
  '3df3c0dc04c5643539e1c7e4f4244b360a56726c82c193cf4fa87e94ef1e2851'
)
