insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'yhct-kham-007',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-007","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-eau-urolithiasis-a371e1e02fb2","resource_type":"guideline","source":"https://uroweb.org/guidelines/urolithiasis","title":"European Association of Urology, EAU Guidelines on Urolithiasis, bản cập nhật.","organization":null,"year_version":null,"citation":"European Association of Urology, EAU Guidelines on Urolithiasis, bản cập nhật.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-007-2","resource_type":"other","source":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị sỏi tiết niệu.","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị sỏi tiết niệu.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị sỏi tiết niệu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[1,3,4,5],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Cơn đau quặn thận do sỏi niệu quản phải 5 mm, giãn nhẹ, chưa nhiễm trùng","credit":"full"},{"text":"Viêm bể thận cấp","credit":"none"},{"text":"Viêm ruột thừa cấp","credit":"none"},{"text":"Phình tách động mạch chủ bụng","credit":"none"},{"text":"Xoắn tinh hoàn","credit":"none"}],"bd":[{"text":"Thạch lâm","credit":"full"},{"text":"Huyết lâm","credit":"none"},{"text":"Cao lâm","credit":"none"},{"text":"Khí lâm","credit":"none"},{"text":"Lao lâm","credit":"none"}],"bc":[{"text":"Lý – Thực – Nhiệt","credit":"full"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Biểu – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Thấp nhiệt hạ chú","credit":"full"},{"text":"Khí trệ","credit":"none"},{"text":"Thận hư","credit":"none"},{"text":"Huyết ứ","credit":"none"},{"text":"Hàn thấp","credit":"none"}],"phap":[{"text":"Thanh nhiệt lợi thấp, bài thạch thông lâm","credit":"full"},{"text":"Hành khí giải uất, thông lâm","credit":"none"},{"text":"Bổ thận, lợi thủy","credit":"none"},{"text":"Hoạt huyết hóa ứ, thông lâm","credit":"none"},{"text":"Ôn thận tán hàn","credit":"none"}],"phuong":[{"text":"Bát chính tán gia Kim tiền thảo, Hải kim sa","credit":"full"},{"text":"Thạch vi tán","credit":"partial"},{"text":"Tiểu sài hồ thang","credit":"none"},{"text":"Lục vị địa hoàng hoàn","credit":"none"},{"text":"Ngọc bình phong tán","credit":"none"}],"huyet":[{"text":"Thận du","credit":"full"},{"text":"Bàng quang du","credit":"full"},{"text":"Thủy đạo","credit":"full"},{"text":"Tam âm giao","credit":"full"},{"text":"Âm lăng tuyền","credit":"full"},{"text":"Phong trì","credit":"none"},{"text":"Liệt khuyết","credit":"none"},{"text":"Thái dương","credit":"none"}]},"action_options":[{"text":"Giảm đau bằng NSAID (diclofenac hoặc ketorolac) nếu không chống chỉ định, đánh giá chức năng thận","time_minutes":10,"grade":"recommended","rationale":"NSAID là lựa chọn đầu tay giảm đau cơn đau quặn thận."},{"text":"Đánh giá dấu hiệu nhiễm trùng, thận ứ nước và lưu thông nước tiểu, chụp CT liều thấp","time_minutes":30,"grade":"recommended","rationale":"Phát hiện biến chứng cần xử trí cấp cứu tiết niệu."},{"text":"Cho thuốc tống sỏi nội khoa (tamsulosin) cho sỏi niệu quản đoạn xa 5 mm, uống nhiều nước","time_minutes":5,"grade":"recommended","rationale":"Tăng khả năng tự thoát sỏi, giảm cơn đau."},{"text":"Dùng Bát chính tán gia Kim tiền thảo, Hải kim sa theo thể Thấp nhiệt hạ chú","time_minutes":10,"grade":"recommended","rationale":"Thanh nhiệt lợi thấp, bài thạch."},{"text":"Châm Thận du, Bàng quang du, Thủy đạo, Tam âm giao, Âm lăng tuyền","time_minutes":20,"grade":"recommended","rationale":"Giảm co thắt, hỗ trợ giảm đau, bài thạch."},{"text":"Hướng dẫn lọc nước tiểu tìm sỏi, hẹn tái khám với bác sĩ tiết niệu, dặn dấu hiệu cần cấp cứu (sốt, rét run, vô niệu, đau tăng)","time_minutes":5,"grade":"recommended","rationale":"Sỏi kèm nhiễm trùng hoặc tắc nghẽn là cấp cứu tiết niệu."},{"text":"Chụp CT bụng chậu có cản quang","time_minutes":40,"grade":"waste","rationale":"Không cần thiết để chẩn đoán sỏi."},{"text":"Chỉ châm cứu, thuốc thang và chờ khi có sốt, rét run hoặc vô niệu","time_minutes":2,"grade":"harmful","rationale":"Sỏi tắc nghẽn kèm nhiễm trùng có thể gây nhiễm trùng huyết, suy thận; cần dẫn lưu cấp cứu."},{"text":"Dùng Mộc thông (Quan mộc thông) hoặc vị chứa acid aristolochic trong bài thuốc lợi niệu","time_minutes":2,"grade":"harmful","rationale":"Độc thận, ung thư đường niệu; chỉ dùng Mộc thông (Akebia) đúng nguồn gốc."}],"teaching_explanation":"Cơn đau quặn thận cần giảm đau bằng NSAID, đánh giá nhiễm trùng và tắc nghẽn; CT liều thấp không cản quang là đủ. Sỏi niệu quản dưới 6 mm đoạn xa có thể tống sỏi nội khoa, uống nhiều nước. Sỏi kèm sốt, vô niệu hoặc thận ứ nước nặng là cấp cứu tiết niệu. Thể Thấp nhiệt hạ chú: đau quặn, tiểu buốt, tiểu máu, lưỡi đỏ rêu vàng nhờn, mạch huyền sác, dùng Bát chính tán gia vị bài thạch; cảnh giác vị có acid aristolochic."}'::jsonb,
  '9a730dcc69890e89353e42596c8b9d573ba73084d1d54506ae051240402ae51b'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'yhct-kham-008',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-008","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nam 64 tuổi mụn nước thành chùm kèm đau rát một bên ngực","setting":"chamcuu","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":64,"sex":"nam","patient_label":"Người bệnh mô phỏng Bùi V. D."},"presentation":{"intro":"Phòng châm cứu YHCT. Ông đã nghỉ hưu, đến khám vì đau rát và nổi mụn nước thành chùm trên nền ban đỏ ở một bên ngực phải từ 3 ngày nay.","place":"Phòng châm cứu YHCT","clock":"11:00","night":false},"vitals":{"hr":84,"sbp":138,"dbp":82,"rr":18,"temperature_c":37.6,"spo2":98},"history":[{"question":"Đau rát bắt đầu trước hay sau khi nổi mụn nước, vị trí, tính chất?","response":"Đau rát như bỏng một bên ngực phải 4 ngày, sau đó nổi mụn nước thành chùm từ 3 ngày."},{"question":"Tổn thương có vượt đường giữa, có ở vùng mắt, mũi, tai, mặt không?","response":"Chỉ một bên ngực phải theo dải, không qua đường giữa, không ở mặt hay mắt."},{"question":"Có sốt, mệt, hạch, suy giảm miễn dịch, dùng corticoid, ung thư, HIV?","response":"Sốt nhẹ, mệt; không dùng corticoid, không ung thư, chưa xét nghiệm HIV."},{"question":"Tiền sử thủy đậu, tiêm vắc-xin zona, tiểu đường?","response":"Từng bị thủy đậu nhỏ, chưa tiêm zona, không tiểu đường."},{"question":"Bệnh thận, đang dùng thuốc, dị ứng aciclovir?","response":"Không bệnh thận, không dị ứng thuốc đã biết."},{"question":"Miệng đắng, bứt rứt, ngủ kém, tiểu vàng, táo bón?","response":"Miệng đắng, cáu gắt, ngủ kém vì đau, tiểu vàng, táo bón."}],"examination":[{"group":"V","item":"Thần sắc, tổn thương da","finding":"Chùm mụn nước trên nền ban đỏ theo dải da một bên ngực phải ngang T6 đến T8, một số mụn nước đã đóng vảy, không loét hoại tử, không bội nhiễm."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi đỏ, rêu vàng."},{"group":"M","item":"Giọng nói","finding":"Giọng to, hơi bực dọc."},{"group":"T","item":"Mạch","finding":"Mạch huyền sác."},{"group":"K","item":"Khám cảm giác, thần kinh","finding":"Tăng cảm giác đau theo dải da T6 đến T8, không yếu liệt."},{"group":"K","item":"Khám hạch, mắt, tai","finding":"Không hạch to, không tổn thương mắt hoặc tai."}],"investigations":[{"name":"Chẩn đoán lâm sàng; PCR dịch mụn nước VZV nếu không điển hình","duration_minutes":10,"result":"Lâm sàng điển hình, không cần PCR thường quy."},{"name":"Công thức máu, creatinin","duration_minutes":10,"result":"Bạch cầu bình thường, creatinin 90 micromol/L, ước tính thanh thải bình thường."},{"name":"Đường huyết đói","duration_minutes":10,"result":"5,3 mmol/L."},{"name":"Tầm soát HIV khi có yếu tố nguy cơ hoặc tổn thương nặng","duration_minutes":10,"result":"Không có yếu tố nguy cơ; có thể tư vấn theo dõi."},{"name":"Chụp MRI cột sống ngực có cản từ để chẩn đoán","duration_minutes":10,"result":"Không có chỉ định ở zona điển hình."}],"choices":{"diagnosis":{"ydx":["Zona (herpes zoster) khoanh da T6 đến T8, chưa biến chứng","Chốc lở","Herpes simplex","Viêm da tiếp xúc","Đau thần kinh liên sườn đơn thuần"],"bd":["Xà đản (Hỏa đới sang)","Cam","Đơn độc","Thấp sang","Phong chẩn"],"bc":["Lý – Hư – Hàn","Biểu – Thực – Hàn","Biểu – Thực – Nhiệt","Lý – Thực – Hàn","Lý – Hư – Nhiệt"],"the":["Can kinh uất nhiệt","Tỳ kinh thấp nhiệt","Phong hàn","Khí trệ huyết ứ","Can thận âm hư"],"phap":["Sơ phong tán hàn","Kiện tỳ trừ thấp, thanh nhiệt","Tư bổ can thận","Hoạt huyết hóa ứ, hành khí chỉ thống","Thanh lợi can đởm thấp nhiệt, giải độc chỉ thống"],"phuong":["Lục vị địa hoàng hoàn","Ngân kiều tán","Cách hạ trục ứ thang","Long đởm tả can thang","Trừ thấp vị linh thang"],"huyet":["Thái khê","Chi câu","Giáp tích T6 đến T8","Hành gian","Mệnh môn","Quan nguyên","Túc tam lý","Dương lăng tuyền"]},"actions":["Dặn dấu hiệu cần chuyển chuyên khoa ngay: tổn thương vùng mắt, mũi, tai, mặt, suy giảm miễn dịch, tổn thương lan rộng","Dùng Long đởm tả can thang gia giảm theo thể Can kinh uất nhiệt, thận trọng vị chứa acid aristolochic","Chăm sóc tổn thương: giữ khô sạch, che phủ, không làm vỡ mụn nước, dặn lây cho người chưa miễn dịch","Bôi thuốc chứa corticoid hoặc trộn thuốc nam lên tổn thương zona chưa kiểm soát","Châm Chi câu, Dương lăng tuyền, Hành gian, Giáp tích T6 đến T8 ở vùng da lành xung quanh, vô khuẩn","Giảm đau theo bậc thang (paracetamol, NSAID, gabapentin hoặc pregabalin khi đau thần kinh)","Chụp MRI cột sống ngực có cản từ","Bắt đầu thuốc kháng virus (aciclovir hoặc valaciclovir), hiệu chỉnh liều theo thanh thải creatinin, ưu tiên trong 72 giờ đầu","Châm hoặc cứu trực tiếp lên vùng da có mụn nước hoặc bội nhiễm"]}}'::jsonb,
  '0a64131cbc259bfc70d1a437067d1a4fbaea9d1cf4a9053eb9671ed9e7d3ce17'
)
