  '{"schema_version":"1.0.0","case_id":"yhct-kham-008","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-008-1","resource_type":"other","source":"Dworkin RH, et al. Recommendations for the management of herpes zoster. Clin Infect Dis 2007.","title":"Dworkin RH, et al. Recommendations for the management of herpes zoster. Clin Infect Dis 2007.","organization":null,"year_version":null,"citation":"Dworkin RH, et al. Recommendations for the management of herpes zoster. Clin Infect Dis 2007.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-008-2","resource_type":"other","source":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh da liễu.","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh da liễu.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh da liễu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,3,4],"investigation_roles":[{"index":0,"role":"neutral"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Zona (herpes zoster) khoanh da T6 đến T8, chưa biến chứng","credit":"full"},{"text":"Herpes simplex","credit":"none"},{"text":"Viêm da tiếp xúc","credit":"none"},{"text":"Chốc lở","credit":"none"},{"text":"Đau thần kinh liên sườn đơn thuần","credit":"none"}],"bd":[{"text":"Xà đản (Hỏa đới sang)","credit":"full"},{"text":"Thấp sang","credit":"none"},{"text":"Phong chẩn","credit":"none"},{"text":"Đơn độc","credit":"none"},{"text":"Cam","credit":"none"}],"bc":[{"text":"Biểu – Thực – Nhiệt","credit":"full"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"},{"text":"Lý – Thực – Hàn","credit":"none"}],"the":[{"text":"Can kinh uất nhiệt","credit":"full"},{"text":"Tỳ kinh thấp nhiệt","credit":"none"},{"text":"Khí trệ huyết ứ","credit":"none"},{"text":"Can thận âm hư","credit":"none"},{"text":"Phong hàn","credit":"none"}],"phap":[{"text":"Thanh lợi can đởm thấp nhiệt, giải độc chỉ thống","credit":"full"},{"text":"Kiện tỳ trừ thấp, thanh nhiệt","credit":"none"},{"text":"Hoạt huyết hóa ứ, hành khí chỉ thống","credit":"none"},{"text":"Tư bổ can thận","credit":"none"},{"text":"Sơ phong tán hàn","credit":"none"}],"phuong":[{"text":"Long đởm tả can thang","credit":"full"},{"text":"Trừ thấp vị linh thang","credit":"partial"},{"text":"Cách hạ trục ứ thang","credit":"none"},{"text":"Lục vị địa hoàng hoàn","credit":"none"},{"text":"Ngân kiều tán","credit":"none"}],"huyet":[{"text":"Chi câu","credit":"full"},{"text":"Dương lăng tuyền","credit":"full"},{"text":"Hành gian","credit":"full"},{"text":"Giáp tích T6 đến T8","credit":"full"},{"text":"Quan nguyên","credit":"none"},{"text":"Mệnh môn","credit":"none"},{"text":"Túc tam lý","credit":"none"},{"text":"Thái khê","credit":"none"}]},"action_options":[{"text":"Bắt đầu thuốc kháng virus (aciclovir hoặc valaciclovir), hiệu chỉnh liều theo thanh thải creatinin, ưu tiên trong 72 giờ đầu","time_minutes":10,"grade":"recommended","rationale":"Giảm thời gian bệnh, giảm nguy cơ đau thần kinh sau zona."},{"text":"Giảm đau theo bậc thang (paracetamol, NSAID, gabapentin hoặc pregabalin khi đau thần kinh)","time_minutes":10,"grade":"recommended","rationale":"Kiểm soát đau cấp và nguy cơ đau mạn."},{"text":"Chăm sóc tổn thương: giữ khô sạch, che phủ, không làm vỡ mụn nước, dặn lây cho người chưa miễn dịch","time_minutes":5,"grade":"recommended","rationale":"Hạn chế bội nhiễm và lây."},{"text":"Dùng Long đởm tả can thang gia giảm theo thể Can kinh uất nhiệt, thận trọng vị chứa acid aristolochic","time_minutes":10,"grade":"recommended","rationale":"Thanh can đởm thấp nhiệt, giải độc chỉ thống."},{"text":"Châm Chi câu, Dương lăng tuyền, Hành gian, Giáp tích T6 đến T8 ở vùng da lành xung quanh, vô khuẩn","time_minutes":20,"grade":"recommended","rationale":"Sơ can giải uất, giảm đau thần kinh."},{"text":"Dặn dấu hiệu cần chuyển chuyên khoa ngay: tổn thương vùng mắt, mũi, tai, mặt, suy giảm miễn dịch, tổn thương lan rộng","time_minutes":5,"grade":"recommended","rationale":"Zona vùng mắt hoặc suy giảm miễn dịch cần xử trí chuyên khoa."},{"text":"Chụp MRI cột sống ngực có cản từ","time_minutes":50,"grade":"waste","rationale":"Không có chỉ định."},{"text":"Châm hoặc cứu trực tiếp lên vùng da có mụn nước hoặc bội nhiễm","time_minutes":2,"grade":"harmful","rationale":"Gây nhiễm trùng, bỏng, lan tổn thương."},{"text":"Bôi thuốc chứa corticoid hoặc trộn thuốc nam lên tổn thương zona chưa kiểm soát","time_minutes":2,"grade":"harmful","rationale":"Bội nhiễm, chậm lành, nguy cơ biến chứng."}],"teaching_explanation":"Zona là tái hoạt hóa virus varicella zoster; điều trị kháng virus sớm trong 72 giờ giúp giảm biến chứng và đau thần kinh sau zona. Zona vùng mắt, suy giảm miễn dịch hoặc tổn thương lan rộng cần chuyển chuyên khoa. Thể Can kinh uất nhiệt: mụn nước đỏ, đau rát dữ dội, miệng đắng, lưỡi đỏ rêu vàng, mạch huyền sác, dùng Long đởm tả can thang; không châm trực tiếp lên da tổn thương, cảnh giác vị chứa acid aristolochic."}'::jsonb,
  'f1f381466f294f644a98c229e5df546a6eaacabe92d3b02cb9881db7e2273bf3'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'yhct-kham-101',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-101","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nữ sinh viên 19 tuổi đau bụng dưới dữ dội mỗi kỳ kinh","setting":"phongkham","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":19,"sex":"nữ","patient_label":"Trần Thu Hương"},"presentation":{"intro":"Phòng khám Y học cổ truyền. Hương là sinh viên năm hai, đến khám vì đau bụng dưới quặn từng cơn mỗi kỳ kinh khoảng 2 năm, lần này đang là ngày thứ 2 của kỳ kinh, đau nhiều phải nghỉ học.","place":"Phòng khám Y học cổ truyền","clock":"08:40","night":false},"vitals":{"hr":82,"sbp":108,"dbp":68,"rr":18,"temperature_c":36.8,"spo2":99},"history":[{"question":"Đau bụng xuất hiện khi nào so với kỳ kinh, đau thế nào, mức đau, lan đi đâu?","response":"Đau từ 1 đến 2 ngày trước khi ra kinh và kéo dài 2 ngày đầu, quặn từng cơn ở bụng dưới, lan ra thắt lưng và mặt trong đùi, đau 7 trên 10. Đã đau như vậy khoảng 2 năm."},{"question":"Chu kỳ kinh, lượng kinh, màu sắc máu kinh?","response":"Chu kỳ 28 đến 30 ngày đều, hành kinh 5 ngày, lượng vừa, máu sẫm có cục nhỏ, ra cục thì đỡ đau."},{"question":"Chườm ấm hoặc uống nước ấm có đỡ không? Có sợ lạnh, tay chân lạnh không?","response":"Chườm ấm dễ chịu hơn rõ rệt. Hay lạnh tay chân, sợ lạnh, ăn đồ lạnh hoặc uống trà đá thì đau nhiều hơn."},{"question":"Có đau ngoài kỳ kinh, đau khi quan hệ, đau khi đại tiểu tiện, ra khí hư hôi, sốt không?","response":"Không đau ngoài kỳ kinh, chưa quan hệ tình dục, không khí hư bất thường, không sốt."},{"question":"Có nôn, buồn nôn, tiêu chảy, đau đầu kèm theo khi hành kinh không?","response":"Buồn nôn nhẹ, hơi đi lỏng ngày đầu kinh, không nôn nhiều."},{"question":"Đã dùng thuốc gì? Có dị ứng, đau dạ dày, hen không?","response":"Uống ibuprofen 400 mg một viên khi đau thì đỡ ít. Không đau dạ dày, không hen, không dị ứng thuốc."},{"question":"Tiền sử gia đình có ai đau bụng kinh nặng hoặc bị lạc nội mạc tử cung không?","response":"Mẹ cũng đau bụng kinh nhưng đỡ sau khi sinh. Không ai được chẩn đoán lạc nội mạc tử cung."},{"question":"Chế độ ăn uống, vận động, giấc ngủ, căng thẳng thi cử?","response":"Hay thức khuya, ngồi học nhiều, ít vận động, uống nước đá thường xuyên."}],"examination":[{"group":"V","item":"Thần sắc, dáng vẻ","finding":"Mặt nhợt nhạt, vẻ mặt đau đớn, gập người ôm bụng dưới."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi hơi tối, rìa có điểm ứ huyết nhỏ, rêu trắng mỏng."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Giọng nói nhỏ, ngắt quãng vì đau, hơi thở không hôi."},{"group":"T","item":"Mạch","finding":"Mạch trầm khẩn."},{"group":"T","item":"Sờ tay chân, bụng dưới","finding":"Tay chân lạnh, bụng dưới ấn đau, thích chườm ấm."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, đau nhẹ khi ấn hạ vị, không phản ứng thành bụng, không cảm ứng phúc mạc, không có khối."},{"group":"K","item":"Dấu hiệu sinh tồn, thiếu máu","finding":"Da niêm mạc hồng nhạt, không sốt, mạch và huyết áp ổn định."}],"investigations":[{"name":"Siêu âm bụng qua thành bụng, đánh giá tử cung và hai buồng trứng","duration_minutes":15,"result":"Tử cung kích thước bình thường, không u xơ, không u nang buồng trứng, không dịch ổ bụng."},{"name":"Công thức máu","duration_minutes":10,"result":"Hb 12,6 g/dL, bạch cầu bình thường."},{"name":"CRP","duration_minutes":10,"result":"Bình thường."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Bình thường, không có bạch cầu, hồng cầu."},{"name":"CA-125 máu","duration_minutes":10,"result":""},{"name":"Nội soi ổ bụng chẩn đoán","duration_minutes":20,"result":"Không có chỉ định ở bệnh nhân trẻ chưa thử điều trị nội khoa, xâm lấn."}],"choices":{"diagnosis":{"ydx":["Thai ngoài tử cung","U xơ tử cung","Viêm vùng chậu","Thống kinh nguyên phát","Lạc nội mạc tử cung (thống kinh thứ phát)"],"bd":["Thống kinh","Phúc thống","Kinh nguyệt hậu kỳ","Đới hạ","Băng lậu"],"bc":["Lý – Thực – Nhiệt","Biểu – Thực – Hàn","Lý – Hư – Hàn","Lý – Hư – Nhiệt","Lý – Thực – Hàn"],"the":["Khí trệ huyết ứ","Can thận hư tổn","Khí huyết hư nhược","Hàn ngưng huyết ứ","Thấp nhiệt uẩn kết"],"phap":["Thanh nhiệt lợi thấp","Tư bổ can thận","Bổ ích khí huyết","Sơ can giải uất, hành khí","Ôn kinh tán hàn, hoạt huyết chỉ thống"],"phuong":["Thánh dũ thang","Thanh nhiệt điều huyết thang","Tiêu dao tán","Thiếu phúc trục ứ thang","Lục vị địa hoàng hoàn"],"huyet":["Thứ liêu","Thái dương","Khí hải","Tam âm giao","Địa cơ","Quan nguyên","Phong trì","Đại chùy","Liệt khuyết"]},"actions":["Ibuprofen 400 mg uống mỗi 6 đến 8 giờ sau ăn trong 2 đến 3 ngày đầu kỳ kinh, sau khi đã hỏi tiền sử dạ dày, hen, thận","Chườm ấm bụng dưới, nghỉ ngơi, tránh đồ lạnh và nước đá","Châm cứu hoặc cứu Quan nguyên, Khí hải, Tam âm giao, Địa cơ, Thứ liêu, lưu kim 20 phút","Cho rằng đau bụng kinh là bình thường, không hỏi dấu hiệu báo động","Dặn tái khám sau 3 chu kỳ nếu không đáp ứng để siêu âm lại và đánh giá lạc nội mạc tử cung","Dùng thuốc hoạt huyết mạnh (Đào nhân, Hồng hoa, Tam lăng, Nga truật) hoặc châm Tam âm giao, Hợp cốc khi chưa loại trừ có thai","Đánh giá mức đau, hỏi kỹ dấu hiệu báo động: đau ngoài kỳ kinh, đau tăng dần, sốt, khí hư hôi, ra kinh nhiều","Làm CA-125 và nội soi ổ bụng chẩn đoán ngay","Thiếu phúc trục ứ thang gia giảm, sắc uống mỗi ngày một thang: Tiểu hồi hương 2 g, Can khương 3 g, Diên hồ sách 6 g, Một dược 6 g, Đương quy 9 g, Xuyên khung 6 g, Quan quế 3 g, Xích thược 6 g, Bồ hoàng 9 g, Ngũ linh chi 6 g; bắt đầu 5 đến 7 ngày trước kỳ kinh sau"]}}'::jsonb,
  'c738a79dbfa7a80eec72af8cbcd77a67669aa286a28549f5b95f1a904c77aebb'
)
