  '{"schema_version":"1.0.0","case_id":"yhct-kham-101","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-101-1","resource_type":"other","source":"American College of Obstetricians and Gynecologists, Committee Opinion No. 760: Dysmenorrhea and Endometriosis in the Adolescent, Obstet Gynecol 2018;132:e249-e258.","title":"American College of Obstetricians and Gynecologists, Committee Opinion No. 760: Dysmenorrhea and Endometriosis in the Adolescent, Obstet Gynecol 2018;132:e249-e258.","organization":null,"year_version":null,"citation":"American College of Obstetricians and Gynecologists, Committee Opinion No. 760: Dysmenorrhea and Endometriosis in the Adolescent, Obstet Gynecol 2018;132:e249-e258.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[{"path":"investigations[4].result","text":"Không có chỉ định ở thống kinh điển hình, dễ gây lo lắng không cần thiết.","reason":"Toàn bộ kết quả là nhận định chỉ định dựa trên chẩn đoán Thống kinh; không có dữ kiện thô độc lập để giữ công khai."}],"history_essential_indices":[0,1,2,3,5],"examination_essential_indices":[1,3,4,5],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"neutral"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Thống kinh nguyên phát","credit":"full"},{"text":"Lạc nội mạc tử cung (thống kinh thứ phát)","credit":"none"},{"text":"Viêm vùng chậu","credit":"none"},{"text":"Thai ngoài tử cung","credit":"none"},{"text":"U xơ tử cung","credit":"none"}],"bd":[{"text":"Thống kinh","credit":"full"},{"text":"Kinh nguyệt hậu kỳ","credit":"none"},{"text":"Phúc thống","credit":"none"},{"text":"Đới hạ","credit":"none"},{"text":"Băng lậu","credit":"none"}],"bc":[{"text":"Lý – Thực – Hàn","credit":"full"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Hàn ngưng huyết ứ","credit":"full"},{"text":"Khí trệ huyết ứ","credit":"none"},{"text":"Khí huyết hư nhược","credit":"none"},{"text":"Thấp nhiệt uẩn kết","credit":"none"},{"text":"Can thận hư tổn","credit":"none"}],"phap":[{"text":"Ôn kinh tán hàn, hoạt huyết chỉ thống","credit":"full"},{"text":"Sơ can giải uất, hành khí","credit":"none"},{"text":"Bổ ích khí huyết","credit":"none"},{"text":"Thanh nhiệt lợi thấp","credit":"none"},{"text":"Tư bổ can thận","credit":"none"}],"phuong":[{"text":"Thiếu phúc trục ứ thang","credit":"full"},{"text":"Thánh dũ thang","credit":"none"},{"text":"Tiêu dao tán","credit":"none"},{"text":"Thanh nhiệt điều huyết thang","credit":"none"},{"text":"Lục vị địa hoàng hoàn","credit":"none"}],"huyet":[{"text":"Quan nguyên","credit":"full"},{"text":"Khí hải","credit":"full"},{"text":"Tam âm giao","credit":"full"},{"text":"Địa cơ","credit":"full"},{"text":"Thứ liêu","credit":"full"},{"text":"Phong trì","credit":"none"},{"text":"Thái dương","credit":"none"},{"text":"Liệt khuyết","credit":"none"},{"text":"Đại chùy","credit":"none"}]},"action_options":[{"text":"Đánh giá mức đau, hỏi kỹ dấu hiệu báo động: đau ngoài kỳ kinh, đau tăng dần, sốt, khí hư hôi, ra kinh nhiều","time_minutes":5,"grade":"recommended","rationale":"Phân biệt thống kinh nguyên phát với thứ phát và nhiễm trùng vùng chậu."},{"text":"Ibuprofen 400 mg uống mỗi 6 đến 8 giờ sau ăn trong 2 đến 3 ngày đầu kỳ kinh, sau khi đã hỏi tiền sử dạ dày, hen, thận","time_minutes":3,"grade":"recommended","rationale":"NSAID là thuốc bước đầu cho thống kinh nguyên phát."},{"text":"Chườm ấm bụng dưới, nghỉ ngơi, tránh đồ lạnh và nước đá","time_minutes":3,"grade":"recommended","rationale":"Phù hợp thể hàn, giúp giảm co thắt tử cung."},{"text":"Thiếu phúc trục ứ thang gia giảm, sắc uống mỗi ngày một thang: Tiểu hồi hương 2 g, Can khương 3 g, Diên hồ sách 6 g, Một dược 6 g, Đương quy 9 g, Xuyên khung 6 g, Quan quế 3 g, Xích thược 6 g, Bồ hoàng 9 g, Ngũ linh chi 6 g; bắt đầu 5 đến 7 ngày trước kỳ kinh sau","time_minutes":10,"grade":"recommended","rationale":"Ôn kinh tán hàn, hoạt huyết chỉ thống; uống theo chu kỳ."},{"text":"Châm cứu hoặc cứu Quan nguyên, Khí hải, Tam âm giao, Địa cơ, Thứ liêu, lưu kim 20 phút","time_minutes":25,"grade":"recommended","rationale":"Ôn kinh, điều hòa khí huyết vùng hạ tiêu, giảm đau."},{"text":"Dặn tái khám sau 3 chu kỳ nếu không đáp ứng để siêu âm lại và đánh giá lạc nội mạc tử cung","time_minutes":3,"grade":"recommended","rationale":"Đau dai dẳng dù đã điều trị đúng cần tìm nguyên nhân thứ phát."},{"text":"Làm CA-125 và nội soi ổ bụng chẩn đoán ngay","time_minutes":60,"grade":"waste","rationale":"Không có chỉ định ở thống kinh điển hình chưa điều trị."},{"text":"Dùng thuốc hoạt huyết mạnh (Đào nhân, Hồng hoa, Tam lăng, Nga truật) hoặc châm Tam âm giao, Hợp cốc khi chưa loại trừ có thai","time_minutes":2,"grade":"harmful","rationale":"Có thể gây sảy thai nếu người bệnh có thai chưa biết."},{"text":"Cho rằng đau bụng kinh là bình thường, không hỏi dấu hiệu báo động","time_minutes":2,"grade":"harmful","rationale":"Bỏ sót lạc nội mạc tử cung, viêm vùng chậu, thai ngoài tử cung."}],"teaching_explanation":"Thống kinh nguyên phát điển hình: đau bụng dưới quặn trước và trong 1 đến 3 ngày đầu kỳ kinh, chu kỳ đều, siêu âm bình thường, đáp ứng NSAID và nhiệt. Đau ngoài kỳ kinh, đau tăng dần, đau khi giao hợp hoặc kém đáp ứng NSAID sau 3 chu kỳ gợi lạc nội mạc tử cung. Thể Hàn ngưng huyết ứ: đau lạnh, chườm ấm đỡ, máu sẫm có cục, tay chân lạnh, mạch trầm khẩn. Phải loại trừ có thai trước khi dùng thuốc hoạt huyết mạnh hoặc châm Tam âm giao, Hợp cốc."}'::jsonb,
  '843fd5959c46c0da4d290730d0fb27f43ab19d40c1cfb40a445c49ffb47d09e3'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'yhct-kham-102',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-102","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sản phụ 12 ngày sau sinh ít sữa, con chậm tăng cân","setting":"phongkham","level":"Dễ","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":28,"sex":"nữ","patient_label":"Lê Thị Mai"},"presentation":{"intro":"Phòng khám Y học cổ truyền. Chị Mai sinh con đầu lòng bằng đường âm đạo cách đây 12 ngày, thấy ngực mềm, ít sữa, con hay khóc đòi bú. Chị đến khám cùng chồng và bé.","place":"Phòng khám Y học cổ truyền","clock":"09:30","night":false},"vitals":{"hr":92,"sbp":102,"dbp":64,"rr":18,"temperature_c":36.7,"spo2":99},"history":[{"question":"Con bú mấy lần mỗi ngày, mỗi lần bú bao lâu, bú xong bé có ngủ yên không?","response":"Bé bú 6 đến 7 lần mỗi ngày, mỗi lần 10 phút rồi quấy khóc, bú xong vẫn đòi bú tiếp."},{"question":"Bé đi tiểu, đi đại tiện mấy lần mỗi ngày, màu sắc thế nào?","response":"Tã ướt khoảng 4 cái mỗi ngày, phân vàng ít, hai ngày nay hơi ít hơn."},{"question":"Cân nặng bé lúc sinh và hiện nay?","response":"Lúc sinh 3,1 kg, hôm nay cân ở trạm y tế được 3,0 kg."},{"question":"Ngực có căng tức, nóng đỏ, đau núm vú, nứt núm vú, sốt không?","response":"Ngực mềm, vắt ra rất ít sữa loãng, không nóng đỏ, không nứt núm, không sốt."},{"question":"Mẹ sinh có mất máu nhiều không? Hiện sản dịch, chóng mặt, hồi hộp thế nào?","response":"Sinh thường, mất máu khoảng 400 ml. Sản dịch ít dần, không hôi. Hay chóng mặt, hồi hộp, da xanh."},{"question":"Ăn, uống, ngủ của mẹ thế nào?","response":"Ăn ít vì không thấy ngon, ngủ không sâu vì con thức đêm, mệt mỏi, nói nhỏ không ra hơi."},{"question":"Có bú đêm không, có cho bé dùng bình sữa, ti giả, nước đường không?","response":"Mẹ không dám đánh thức nên đêm bé bú ít, chưa dùng bình sữa, chưa cho nước đường."},{"question":"Mẹ có dùng thuốc nào đang ảnh hưởng đến sữa không? Có chảy máu nhiều kéo dài, sụt cân, rụng tóc, lạnh bất thường không?","response":"Chỉ uống sắt và canxi theo toa. Không có triệu chứng nào kể trên."}],"examination":[{"group":"V","item":"Thần sắc, da niêm mạc","finding":"Mặt xanh nhợt, môi nhạt, tinh thần mệt mỏi."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, rêu trắng mỏng."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Giọng nói nhỏ, thiếu lực, hơi thở ngắn."},{"group":"T","item":"Mạch","finding":"Mạch tế nhược."},{"group":"K","item":"Khám vú","finding":"Hai vú mềm, không căng, không nóng đỏ, không khối, núm vú bình thường, vắt ra ít sữa loãng."},{"group":"K","item":"Khám bụng, tử cung, sản dịch","finding":"Đáy tử cung co hồi tốt, bụng mềm, sản dịch lượng ít màu hồng nhạt không hôi."},{"group":"K","item":"Quan sát bé bú","finding":"Bé ngậm bắt vú nông, chỉ ngậm phần đầu núm, nuốt ít."}],"investigations":[{"name":"Công thức máu","duration_minutes":10,"result":"Hb 10,2 g/dL, thiếu máu nhẹ, MCV hơi thấp."},{"name":"TSH máu","duration_minutes":10,"result":"Bình thường."},{"name":"Siêu âm tử cung sau sinh","duration_minutes":15,"result":"Tử cung co hồi tốt, buồng tử cung không sót nhau."},{"name":"Cân bé, theo dõi tã ướt và biểu đồ tăng cân","duration_minutes":10,"result":"Bé 3,0 kg, thấp hơn cân nặng lúc sinh."},{"name":"Prolactin máu thường quy","duration_minutes":10,"result":"Không cần thiết ở ca không nghi suy tuyến yên."},{"name":"MRI tuyến yên","duration_minutes":10,"result":"Không có chỉ định, không dấu hiệu hội chứng Sheehan."}],"choices":{"diagnosis":{"ydx":["Thiếu sữa thứ phát do kỹ thuật cho bú chưa đúng và thiếu máu sau sinh","Suy giáp sau sinh","Tắc tia sữa","Viêm vú","Hội chứng Sheehan"],"bd":["Ác lộ bất tuyệt","Nhũ ung","Sản hậu phát nhiệt","Sản hậu huyết vựng","Thiếu sữa"],"bc":["Lý – Thực – Nhiệt","Lý – Thực – Hàn","Biểu – Thực – Hàn","Lý – Hư – Hàn","Biểu – Hư – Nhiệt"],"the":["Thấp nhiệt","Đàm khí ngưng trệ","Can khí uất kết","Khí huyết hư nhược","Huyết ứ sau sinh"],"phap":["Hóa đàm thông lạc","Thanh nhiệt giải độc","Sơ can giải uất, thông nhũ","Bổ khí dưỡng huyết, thông nhũ","Hoạt huyết hóa ứ"],"phuong":["Hạ nhũ dũng tuyền thang","Sinh hóa thang","Thông nhũ đan","Tiêu dao tán","Đại thừa khí thang"],"huyet":["Thiếu trạch","Liệt khuyết","Túc tam lý","Phong trì","Tỳ du","Đản trung","Hoàn khiêu","Nhũ căn","Thái dương"]},"actions":["Thông nhũ đan gia giảm sắc uống mỗi ngày một thang: Hoàng kỳ 20 g, Đương quy 12 g, Đảng sâm 12 g, Mạch môn 12 g, Thông thảo 6 g, Cát cánh 6 g, Vương bất lưu hành 10 g","Dùng Xuyên sơn giáp hoặc Quan mộc thông trong bài thông nhũ","Dùng Mạch nha liều cao hoặc Sơn tra liều lớn, thuốc ức chế sữa, pseudoephedrine để điều trị","Vắt hoặc hút sữa sau các cữ bú, uống đủ nước, ăn đủ năng lượng và đạm","Châm hoặc xoa bóp bấm huyệt Đản trung, Nhũ căn, Thiếu trạch, Túc tam lý, Tỳ du","Bổ sung sắt theo toa, tái khám thiếu máu sau sinh","Làm prolactin máu và MRI tuyến yên","Đánh giá trẻ: cân lại sau 2 đến 3 ngày, đếm tã ướt, hội chẩn nhi khoa và bổ sung sữa mẹ vắt hoặc sữa công thức theo chỉ định nếu trẻ tiếp tục không tăng cân","Hướng dẫn tư thế bú, ngậm bắt vú đúng, cho bú theo nhu cầu ít nhất 8 lần mỗi 24 giờ, kể cả ban đêm, và tiếp xúc da kề da"]}}'::jsonb,
  '93a3884aa88e2c7af42900060e70502e4561b49437e3fd4e3f62a21c451b9ff6'
)
