YT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,3,4,5,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"neutral"},{"index":2,"role":"neutral"},{"index":3,"role":"essential"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Thiếu sữa thứ phát do kỹ thuật cho bú chưa đúng và thiếu máu sau sinh","credit":"full"},{"text":"Viêm vú","credit":"none"},{"text":"Suy giáp sau sinh","credit":"none"},{"text":"Hội chứng Sheehan","credit":"none"},{"text":"Tắc tia sữa","credit":"none"}],"bd":[{"text":"Thiếu sữa","credit":"full"},{"text":"Nhũ ung","credit":"none"},{"text":"Sản hậu phát nhiệt","credit":"none"},{"text":"Sản hậu huyết vựng","credit":"none"},{"text":"Ác lộ bất tuyệt","credit":"none"}],"bc":[{"text":"Lý – Hư – Hàn","credit":"full"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Thực – Hàn","credit":"none"},{"text":"Biểu – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Khí huyết hư nhược","credit":"full"},{"text":"Can khí uất kết","credit":"none"},{"text":"Đàm khí ngưng trệ","credit":"none"},{"text":"Thấp nhiệt","credit":"none"},{"text":"Huyết ứ sau sinh","credit":"none"}],"phap":[{"text":"Bổ khí dưỡng huyết, thông nhũ","credit":"full"},{"text":"Sơ can giải uất, thông nhũ","credit":"none"},{"text":"Hóa đàm thông lạc","credit":"none"},{"text":"Thanh nhiệt giải độc","credit":"none"},{"text":"Hoạt huyết hóa ứ","credit":"none"}],"phuong":[{"text":"Thông nhũ đan","credit":"full"},{"text":"Hạ nhũ dũng tuyền thang","credit":"none"},{"text":"Tiêu dao tán","credit":"none"},{"text":"Đại thừa khí thang","credit":"none"},{"text":"Sinh hóa thang","credit":"none"}],"huyet":[{"text":"Đản trung","credit":"full"},{"text":"Nhũ căn","credit":"full"},{"text":"Thiếu trạch","credit":"full"},{"text":"Túc tam lý","credit":"full"},{"text":"Tỳ du","credit":"full"},{"text":"Phong trì","credit":"none"},{"text":"Thái dương","credit":"none"},{"text":"Hoàn khiêu","credit":"none"},{"text":"Liệt khuyết","credit":"none"}]},"action_options":[{"text":"Hướng dẫn tư thế bú, ngậm bắt vú đúng, cho bú theo nhu cầu ít nhất 8 lần mỗi 24 giờ, kể cả ban đêm, và tiếp xúc da kề da","time_minutes":10,"grade":"recommended","rationale":"Kích thích tiết sữa bằng bú hiệu quả là biện pháp hàng đầu."},{"text":"Vắt hoặc hút sữa sau các cữ bú, uống đủ nước, ăn đủ năng lượng và đạm","time_minutes":5,"grade":"recommended","rationale":"Tăng kích thích tuyến vú, duy trì nguồn sữa."},{"text":"Đánh giá trẻ: cân lại sau 2 đến 3 ngày, đếm tã ướt, hội chẩn nhi khoa và bổ sung sữa mẹ vắt hoặc sữa công thức theo chỉ định nếu trẻ tiếp tục không tăng cân","time_minutes":5,"grade":"recommended","rationale":"Trẻ thấp hơn cân nặng lúc sinh ngày 12 và ít tã ướt cần theo dõi sát, không chỉ chờ tăng sữa."},{"text":"Bổ sung sắt theo toa, tái khám thiếu máu sau sinh","time_minutes":3,"grade":"recommended","rationale":"Hb 10,2 g/dL, thiếu máu góp phần mệt mỏi, giảm sữa."},{"text":"Thông nhũ đan gia giảm sắc uống mỗi ngày một thang: Hoàng kỳ 20 g, Đương quy 12 g, Đảng sâm 12 g, Mạch môn 12 g, Thông thảo 6 g, Cát cánh 6 g, Vương bất lưu hành 10 g","time_minutes":10,"grade":"recommended","rationale":"Bổ khí huyết, thông nhũ; dùng Thông thảo, không dùng Quan mộc thông."},{"text":"Châm hoặc xoa bóp bấm huyệt Đản trung, Nhũ căn, Thiếu trạch, Túc tam lý, Tỳ du","time_minutes":20,"grade":"recommended","rationale":"Thông lạc, điều hòa khí huyết, hỗ trợ tiết sữa."},{"text":"Làm prolactin máu và MRI tuyến yên","time_minutes":60,"grade":"waste","rationale":"Không có chỉ định, không dấu hiệu suy tuyến yên."},{"text":"Dùng Mạch nha liều cao hoặc Sơn tra liều lớn, thuốc ức chế sữa, pseudoephedrine để điều trị","time_minutes":2,"grade":"harmful","rationale":"Làm giảm tiết sữa thêm."},{"text":"Dùng Xuyên sơn giáp hoặc Quan mộc thông trong bài thông nhũ","time_minutes":2,"grade":"harmful","rationale":"Xuyên sơn giáp là loài bị cấm, Quan mộc thông chứa acid aristolochic độc thận."}],"teaching_explanation":"Thiếu sữa sau sinh thường do bú chưa hiệu quả (ngậm bắt vú nông, bú thưa), mất máu, thiếu máu, mệt mỏi; cần loại trừ nguyên nhân thực thể. Đánh giá trẻ bằng cân nặng, số tã ướt, phân; trẻ chưa lấy lại cân sinh sau 10 đến 14 ngày cần can thiệp. Thể Khí huyết hư nhược: ngực mềm, sữa ít loãng, mặt nhợt, mệt, lưỡi nhạt, mạch tế nhược, dùng Thông nhũ đan. Không dùng Xuyên sơn giáp, Quan mộc thông; tránh Mạch nha liều cao."}'::jsonb,
  '3220bbb2b71aba8c68bd8e6e38b545719d163263261c699000b4568131d80736'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'yhct-kham-103',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-103","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Bé trai 4 tuổi ho kéo dài 5 tuần sau cảm, ho nhiều về đêm","setting":"phongkham","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":4,"sex":"nam","patient_label":"Bé Phạm Gia Bảo"},"presentation":{"intro":"Phòng khám Y học cổ truyền. Mẹ đưa bé Bảo, 4 tuổi, cân nặng 15 kg, đến khám vì ho 5 tuần kể từ sau một đợt cảm, ho nhiều vào ban đêm và sáng sớm, có đờm.","place":"Phòng khám Y học cổ truyền","clock":"14:20","night":false},"vitals":{"hr":104,"sbp":94,"dbp":58,"rr":26,"temperature_c":36.8,"spo2":98},"history":[{"question":"Ho bao lâu rồi, ho khan hay có đờm, nhiều vào lúc nào trong ngày?","response":"Ho 5 tuần, bắt đầu sau một đợt cảm. Ho có đờm nghe rung ở ngực, nhiều về đêm và sáng sớm, thỉnh thoảng ho đến nôn trớ."},{"question":"Có sốt, thở nhanh, khò khè, thở rút lõm lồng ngực, tím môi không?","response":"Không sốt, không khó thở, không tím. Thỉnh thoảng nghe khò khè nhẹ khi ho nhiều."},{"question":"Có lần nào bé đang ăn hoặc chơi bỗng ho sặc đột ngột, nghẹn không? Có ho ra máu không?","response":"Không có sặc nghẹn đột ngột, không ho ra máu."},{"question":"Bé có ho tăng khi chạy nhảy, cười, tiếp xúc bụi, khói, lông thú không? Gia đình có ai hen, dị ứng không?","response":"Ho tăng khi trời lạnh và khi bố hút thuốc trong nhà. Anh họ bị hen. Bé không bị chàm."},{"question":"Có tiếp xúc người ho kéo dài, nghi lao không? Đã tiêm BCG chưa?","response":"Không ai trong nhà ho kéo dài. Đã tiêm BCG lúc sơ sinh, có sẹo."},{"question":"Ăn uống, ngủ, cân nặng: bé chán ăn, ăn ít, sụt cân không?","response":"Ăn kém hơn trước, không sụt cân, vẫn chơi bình thường."},{"question":"Đã dùng thuốc gì? Đã dùng kháng sinh chưa? Có dùng siro ho không?","response":"Đã uống siro ho thảo dược mua ở hiệu thuốc 10 ngày, không đỡ. Chưa dùng kháng sinh."},{"question":"Có chảy mũi sau họng, hắng giọng nhiều, nghẹt mũi, ngủ ngáy không?","response":"Hay khụt khịt mũi buổi sáng, đờm chảy xuống họng, ngủ hơi ngáy."},{"question":"Đại tiểu tiện, mồ hôi, tay chân của bé?","response":"Đại tiện nát, hay đầy bụng, tay chân hơi lạnh."}],"examination":[{"group":"V","item":"Thần sắc, thể trạng","finding":"Bé tỉnh, chơi được, sắc mặt hơi nhợt, thể trạng trung bình."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt bệu, rêu trắng dày nhớt."},{"group":"M","item":"Tiếng ho, đờm","finding":"Ho ướt, đờm rung ở ngực, không có tiếng rít thanh quản, không tiếng thở rít."},{"group":"T","item":"Mạch","finding":"Mạch hoạt."},{"group":"K","item":"Khám phổi","finding":"Rì rào phế nang thô, ran ngáy và ran ẩm nhỏ rải rác hai phế trường, không ran nổ khu trú, không rút lõm lồng ngực, nhịp thở 26 lần phút."},{"group":"K","item":"Khám tai mũi họng","finding":"Niêm mạc mũi nhợt, dịch nhầy sau họng, họng không đỏ, amiđan không to."},{"group":"K","item":"Khám tim, bụng, hạch","finding":"Tim đều, bụng mềm hơi chướng, gan lách không to, không hạch cổ to."}],"investigations":[{"name":"X-quang ngực thẳng","duration_minutes":10,"result":"Tăng đậm rốn phổi và quanh phế quản hai bên, không đông đặc, không tràn dịch, không hạch rốn phổi to."},{"name":"Công thức máu","duration_minutes":10,"result":"Bạch cầu 9,8 G/L, bạch cầu ái toan không tăng."},{"name":"CRP","duration_minutes":10,"result":"4 mg/L."},{"name":"Test lao (IGRA hoặc Mantoux) theo yếu tố dịch tễ","duration_minutes":10,"result":"Không có tiếp xúc lao, kết quả âm tính."},{"name":"CT ngực liều thấp","duration_minutes":40,"result":"Không có chỉ định ở trẻ chưa thử điều trị và X-quang không bất thường khu trú, phơi nhiễm bức xạ."},{"name":"Nội soi phế quản","duration_minutes":20,"result":"Không có chỉ định, không nghi dị vật, xâm lấn ở trẻ nhỏ."}],"choices":{"diagnosis":{"ydx":["Hen phế quản","Trào ngược dạ dày thực quản","Lao phổi","Dị vật đường thở","Ho ướt kéo dài ở trẻ em, nghi viêm phế quản vi khuẩn kéo dài sau nhiễm trùng hô hấp"],"bd":["Khái thấu","Phế ung","Hư lao","Háo suyễn","Cam tích"],"bc":["Biểu – Thực – Nhiệt","Lý – Hư – Nhiệt","Biểu – Thực – Hàn","Lý – Thực – Hàn","Lý – Thực – Nhiệt"],"the":["Đàm nhiệt uẩn phế","Phong nhiệt phạm phế","Phong hàn phạm phế","Đàm thấp","Phế âm hư"],"phap":["Tư âm nhuận phế","Thanh nhiệt hóa đàm","Sơ phong thanh nhiệt, tuyên phế","Táo thấp hóa đàm, lý khí chỉ khái","Sơ phong tán hàn, tuyên phế"],"phuong":["Ngân kiều tán","Nhị trần thang","Thanh khí hóa đàm hoàn","Sa sâm mạch môn thang","Tang cúc ẩm"],"huyet":["Túc tam lý","Tỳ du","Phế du","Thính cung","Hậu khê","Thái dương","Phong long","Đản trung","Dương lăng tuyền"]},"actions":["Chụp CT ngực liều thấp và nội soi phế quản ngay","Hỏi và khám tìm dấu hiệu nguy hiểm: thở nhanh, rút lõm lồng ngực, tím, sốt cao kéo dài, ho ra máu, nghẹn sặc đột ngột, sụt cân","Nhị trần thang gia giảm cho trẻ 4 tuổi, sắc uống mỗi ngày 1 thang chia 2 lần: Bán hạ chế 4 g, Trần bì 3 g, Phục linh 6 g, Cam thảo 2 g, Sinh khương 2 lát, Cát cánh 3 g, Tiền hồ 4 g (khoảng một phần ba liều người lớn)","Chụp X-quang ngực thẳng","Loại bỏ yếu tố kích thích: không hút thuốc trong nhà, tránh bụi, giữ ấm cổ ngực, rửa mũi nước muối sinh lý","Dùng thuốc ho có codein, thuốc giảm ho hoặc thuốc long đờm không kê đơn cho trẻ dưới 6 tuổi","Dùng Bán hạ sống, Ma hoàng hoặc Khổ hạnh nhân cho trẻ","Cân nhắc kháng sinh 2 tuần (amoxicillin kết hợp clavulanat), liều theo cân nặng do bác sĩ nhi kê, nếu ho ướt kéo dài trên 4 tuần không có nguyên nhân khác; tái khám sau 2 tuần để đánh giá","Nửa thìa cà phê mật ong trước khi ngủ (trẻ trên 1 tuổi), uống nước ấm","Xoa bóp bấm huyệt Phế du, Tỳ du, Phong long, Túc tam lý, Đản trung, không lưu kim, mỗi huyệt 1 đến 2 phút"]}}'::jsonb,
  '2f8b3b1a7c57e410e1c32a5b231a5f1ae2745f26edb0070f61327b50af49f671'
)
