  '{"schema_version":"1.0.0","case_id":"yhct-kham-103","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-103-1","resource_type":"other","source":"Chang AB, et al., Management of Children With Chronic Wet Cough and Protracted Bacterial Bronchitis: CHEST Guideline and Expert Panel Report, Chest 2017;151:884-890.","title":"Chang AB, et al., Management of Children With Chronic Wet Cough and Protracted Bacterial Bronchitis: CHEST Guideline and Expert Panel Report, Chest 2017;151:884-890.","organization":null,"year_version":null,"citation":"Chang AB, et al., Management of Children With Chronic Wet Cough and Protracted Bacterial Bronchitis: CHEST Guideline and Expert Panel Report, Chest 2017;151:884-890.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-103-2","resource_type":"other","source":"World Health Organization, Pocket Book of Hospital Care for Children, 2nd edition, 2013.","title":"World Health Organization, Pocket Book of Hospital Care for Children, 2nd edition, 2013.","organization":null,"year_version":null,"citation":"World Health Organization, Pocket Book of Hospital Care for Children, 2nd edition, 2013.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[1,2,3,4],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"neutral"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Ho ướt kéo dài ở trẻ em, nghi viêm phế quản vi khuẩn kéo dài sau nhiễm trùng hô hấp","credit":"full"},{"text":"Hen phế quản","credit":"none"},{"text":"Dị vật đường thở","credit":"none"},{"text":"Lao phổi","credit":"none"},{"text":"Trào ngược dạ dày thực quản","credit":"none"}],"bd":[{"text":"Khái thấu","credit":"full"},{"text":"Háo suyễn","credit":"none"},{"text":"Phế ung","credit":"none"},{"text":"Hư lao","credit":"none"},{"text":"Cam tích","credit":"none"}],"bc":[{"text":"Lý – Thực – Hàn","credit":"full"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Biểu – Thực – Nhiệt","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Đàm thấp","credit":"full"},{"text":"Phong hàn phạm phế","credit":"none"},{"text":"Phong nhiệt phạm phế","credit":"none"},{"text":"Phế âm hư","credit":"none"},{"text":"Đàm nhiệt uẩn phế","credit":"none"}],"phap":[{"text":"Táo thấp hóa đàm, lý khí chỉ khái","credit":"full"},{"text":"Sơ phong tán hàn, tuyên phế","credit":"none"},{"text":"Sơ phong thanh nhiệt, tuyên phế","credit":"none"},{"text":"Tư âm nhuận phế","credit":"none"},{"text":"Thanh nhiệt hóa đàm","credit":"none"}],"phuong":[{"text":"Nhị trần thang","credit":"full"},{"text":"Ngân kiều tán","credit":"none"},{"text":"Tang cúc ẩm","credit":"none"},{"text":"Sa sâm mạch môn thang","credit":"none"},{"text":"Thanh khí hóa đàm hoàn","credit":"none"}],"huyet":[{"text":"Phế du","credit":"full"},{"text":"Tỳ du","credit":"full"},{"text":"Phong long","credit":"full"},{"text":"Túc tam lý","credit":"full"},{"text":"Đản trung","credit":"full"},{"text":"Thái dương","credit":"none"},{"text":"Thính cung","credit":"none"},{"text":"Dương lăng tuyền","credit":"none"},{"text":"Hậu khê","credit":"none"}]},"action_options":[{"text":"Hỏi và khám tìm dấu hiệu nguy hiểm: thở nhanh, rút lõm lồng ngực, tím, sốt cao kéo dài, ho ra máu, nghẹn sặc đột ngột, sụt cân","time_minutes":5,"grade":"recommended","rationale":"Phát hiện nhiễm trùng nặng, dị vật, lao hoặc bệnh mạn tính cần chuyển tuyến."},{"text":"Chụp X-quang ngực thẳng","time_minutes":15,"grade":"recommended","rationale":"Ho trên 4 tuần ở trẻ cần X-quang ngực để loại trừ nguyên nhân thực thể."},{"text":"Loại bỏ yếu tố kích thích: không hút thuốc trong nhà, tránh bụi, giữ ấm cổ ngực, rửa mũi nước muối sinh lý","time_minutes":5,"grade":"recommended","rationale":"Khói thuốc làm ho kéo dài; rửa mũi giảm đờm sau họng."},{"text":"Nửa thìa cà phê mật ong trước khi ngủ (trẻ trên 1 tuổi), uống nước ấm","time_minutes":2,"grade":"recommended","rationale":"Mật ong làm dịu ho đêm ở trẻ từ 1 tuổi trở lên."},{"text":"Cân nhắc kháng sinh 2 tuần (amoxicillin kết hợp clavulanat), liều theo cân nặng do bác sĩ nhi kê, nếu ho ướt kéo dài trên 4 tuần không có nguyên nhân khác; tái khám sau 2 tuần để đánh giá","time_minutes":5,"grade":"recommended","rationale":"Khuyến cáo CHEST cho ho ướt kéo dài ở trẻ nghi viêm phế quản vi khuẩn kéo dài."},{"text":"Nhị trần thang gia giảm cho trẻ 4 tuổi, sắc uống mỗi ngày 1 thang chia 2 lần: Bán hạ chế 4 g, Trần bì 3 g, Phục linh 6 g, Cam thảo 2 g, Sinh khương 2 lát, Cát cánh 3 g, Tiền hồ 4 g (khoảng một phần ba liều người lớn)","time_minutes":10,"grade":"recommended","rationale":"Táo thấp hóa đàm; liều giảm theo tuổi, Bán hạ phải dùng loại đã chế."},{"text":"Xoa bóp bấm huyệt Phế du, Tỳ du, Phong long, Túc tam lý, Đản trung, không lưu kim, mỗi huyệt 1 đến 2 phút","time_minutes":15,"grade":"recommended","rationale":"Trẻ nhỏ dùng bấm huyệt nhẹ, không châm lưu kim."},{"text":"Chụp CT ngực liều thấp và nội soi phế quản ngay","time_minutes":60,"grade":"waste","rationale":"Chưa có chỉ định, xâm lấn và phơi nhiễm bức xạ ở trẻ nhỏ."},{"text":"Dùng thuốc ho có codein, thuốc giảm ho hoặc thuốc long đờm không kê đơn cho trẻ dưới 6 tuổi","time_minutes":2,"grade":"harmful","rationale":"Nguy cơ ức chế hô hấp, tác dụng phụ, không có lợi ích rõ ràng."},{"text":"Dùng Bán hạ sống, Ma hoàng hoặc Khổ hạnh nhân cho trẻ","time_minutes":3,"grade":"harmful","rationale":"Bán hạ sống gây độc, Ma hoàng gây tim nhanh, Khổ hạnh nhân chứa glycosid sinh cyanid."}],"teaching_explanation":"Ho trên 4 tuần ở trẻ là ho kéo dài, cần hỏi dấu hiệu nguy hiểm, nguyên nhân thực thể (dị vật, lao, hen, trào ngược, viêm xoang) và chụp X-quang ngực. Ho ướt kéo dài sau nhiễm trùng hô hấp thường là viêm phế quản vi khuẩn kéo dài; có thể cần kháng sinh 2 tuần theo chỉ định của bác sĩ nhi. Thể Đàm thấp: ho đờm nhiều, rêu trắng dày nhớt, mạch hoạt, dùng Nhị trần thang. Trẻ 4 tuổi dùng khoảng một phần ba liều người lớn, không dùng thuốc ho OTC và thuốc chứa codein."}'::jsonb,
  '54c1df9c94e911833b72ff54272c424818e8eabcb2892ad17571867e5881b298'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'yhct-kham-104',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-104","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Bé gái 3 tuổi biếng ăn, gầy, bụng to, ngủ không yên","setting":"phongkham","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":3,"sex":"nữ","patient_label":"Bé Nguyễn Khánh An"},"presentation":{"intro":"Phòng khám Y học cổ truyền. Mẹ đưa bé An, 3 tuổi, đến khám vì biếng ăn khoảng 4 tháng, người gầy, bụng to, hay quấy khóc, ngủ không yên và hay ốm vặt.","place":"Phòng khám Y học cổ truyền","clock":"10:10","night":false},"vitals":{"hr":110,"sbp":92,"dbp":56,"rr":24,"temperature_c":36.7,"spo2":99},"history":[{"question":"Bé biếng ăn từ bao giờ, mỗi bữa ăn được bao nhiêu, có ăn vặt, uống sữa nhiều không?","response":"Biếng ăn khoảng 4 tháng, mỗi bữa ăn được vài thìa cháo rồi ngậm, ngày uống khoảng 600 ml sữa, ăn vặt bánh kẹo."},{"question":"Cân nặng thay đổi thế nào, có sụt cân hoặc đứng cân không?","response":"Đứng cân 3 tháng nay, hiện 11 kg."},{"question":"Phân thế nào: số lần, lỏng hay sống phân, có máu, có ra giun không?","response":"Phân nát, lúc lỏng lúc sệt, có thức ăn chưa tiêu, không máu, chưa thấy ra giun."},{"question":"Bé có đầy bụng, ợ chua, nôn trớ, đau bụng quanh rốn, nghiến răng khi ngủ không?","response":"Bụng hay chướng, ngủ nghiến răng, quấy khóc về đêm, mồ hôi trộm vùng đầu."},{"question":"Có sốt kéo dài, ho kéo dài, tiêu chảy kéo dài, phù chân, nhiễm trùng tái đi tái lại không?","response":"Không sốt kéo dài, không phù, hay cảm ho 1 tháng 1 lần."},{"question":"Tiền sử sinh, cân nặng lúc sinh, bú mẹ, ăn dặm, tiêm chủng, tẩy giun?","response":"Sinh đủ tháng 3,0 kg, bú mẹ 8 tháng, ăn dặm lúc 6 tháng, tiêm chủng đủ, chưa tẩy giun bao giờ."},{"question":"Chế độ ăn: có bị ép ăn, vừa ăn vừa xem điện thoại, ăn rau, thịt, cá, trứng?","response":"Mẹ thường dỗ ăn bằng điện thoại, ăn ít thịt cá, thích bánh ngọt."},{"question":"Tinh thần, chơi đùa, sắc mặt, mồ hôi, tay chân?","response":"Hay quấy, ít chơi, mặt vàng nhợt, tay chân hơi mát."}],"examination":[{"group":"V","item":"Thần sắc, thể trạng","finding":"Bé gầy, sắc mặt vàng nhợt, tóc thưa, tinh thần kém linh hoạt, không phù, không teo cơ nặng."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, rêu trắng dày."},{"group":"M","item":"Hơi thở, tiếng khóc","finding":"Hơi thở hơi chua, tiếng khóc nhỏ yếu."},{"group":"T","item":"Mạch, vân tay","finding":"Mạch tế hoãn; trẻ 3 tuổi quan sát vân tay thấy nhạt."},{"group":"K","item":"Đo nhân trắc","finding":"Cân nặng 11,0 kg, chiều cao 91 cm, vòng cánh tay giữa 14,5 cm, cần so với biểu đồ WHO."},{"group":"K","item":"Khám bụng","finding":"Bụng hơi to, chướng nhẹ, mềm, không đau, gan lách không to, không khối."},{"group":"K","item":"Khám da, niêm mạc, phù","finding":"Niêm mạc nhợt nhẹ, da khô, không phù hai chân, không dấu hiệu thiếu vitamin A nặng."}],"investigations":[{"name":"Công thức máu","duration_minutes":10,"result":"Hb 10,8 g/dL, thiếu máu nhẹ, MCV hơi thấp."},{"name":"Ferritin máu","duration_minutes":10,"result":"Thấp so với ngưỡng theo tuổi."},{"name":"Xét nghiệm phân tìm trứng giun, ký sinh trùng","duration_minutes":10,"result":"Âm tính."},{"name":"Tổng phân tích nước tiểu, CRP","duration_minutes":10,"result":"Bình thường."},{"name":"CT bụng","duration_minutes":40,"result":"Không có chỉ định ở trẻ nhỏ không có dấu hiệu báo động, phơi nhiễm bức xạ."},{"name":"Nội soi dạ dày","duration_minutes":20,"result":"Không có chỉ định, xâm lấn ở trẻ nhỏ."}],"choices":{"diagnosis":{"ydx":["Nhiễm giun","Suy dinh dưỡng cấp nặng","Bệnh celiac","Lao","Biếng ăn, nhẹ cân thể vừa kèm thiếu máu thiếu sắt nhẹ do chế độ ăn và thói quen ăn uống"],"bd":["Phế ung","Tiết tả","Cam tích","Nhi hậu thiên bất túc","Hư lao"],"bc":["Biểu – Hư – Hàn","Lý – Thực – Hàn","Lý – Thực – Nhiệt","Lý – Hư – Hàn","Biểu – Thực – Nhiệt"],"the":["Thận âm hư","Can nhiệt phạm vị","Tỳ hư tích trệ","Thấp nhiệt uẩn tỳ","Tích trệ thực chứng"],"phap":["Sơ can lý khí","Thanh nhiệt lợi thấp","Tư dưỡng can thận","Tả hạ công tích mạnh","Kiện tỳ ích khí, tiêu tích"],"phuong":["Bảo hòa hoàn","Tiêu dao tán","Tứ quân tử thang gia Sơn tra, Mạch nha","Đại thừa khí thang","Lục vị địa hoàng hoàn"],"huyet":["Thính cung","Tỳ du","Thái dương","Vị du","Dương lăng tuyền","Tứ phùng","Túc tam lý","Trung quản","Hậu khê"]},"actions":["Bổ sung sắt khi ferritin thấp theo liều nhi khoa (khoảng 2 mg sắt nguyên tố trên kg mỗi ngày), theo dõi Hb sau 4 đến 8 tuần","Ép ăn, dọa dẫm hoặc dùng thuốc không rõ nguồn gốc, thuốc chứa chì, thủy ngân, hùng hoàng để chữa cam","Tứ quân tử thang gia Sơn tra, Mạch nha, sắc uống mỗi ngày 1 thang cho trẻ 3 tuổi: Đảng sâm 6 g, Bạch truật 6 g, Phục linh 6 g, Chích thảo 2 g, Sơn tra 5 g, Mạch nha 8 g (khoảng một phần ba liều người lớn)","Xoa bóp bấm huyệt hoặc châm nông không lưu kim Tỳ du, Vị du, Túc tam lý, Trung quản, Tứ phùng; có thể bóp sống lưng nhẹ","Dùng thuốc tẩy tích mạnh (Đại hoàng, Khiên ngưu, Mang tiêu) hoặc thuốc kích thích thèm ăn tùy ý kéo dài","Chụp CT bụng và nội soi dạ dày","Điều chỉnh chế độ ăn: bữa chính đúng giờ, bỏ vừa ăn vừa xem điện thoại, giảm sữa và bánh ngọt, thêm thịt cá trứng, rau, dầu mỡ","Đánh giá dinh dưỡng theo biểu đồ WHO (cân nặng theo tuổi, chiều cao theo tuổi, cân nặng theo chiều cao) và hỏi dấu hiệu suy dinh dưỡng nặng: phù, teo cơ rõ, vòng cánh tay dưới 11,5 cm","Tẩy giun albendazole 400 mg liều duy nhất cho trẻ từ 24 tháng tuổi theo hướng dẫn chương trình tẩy giun định kỳ"]}}'::jsonb,
  'ea80d94c8a90a6fa4ddb7be3cb5bac6ecfd8103c217d50062b340b1aa50468d8'
)
