  '{"schema_version":"1.0.0","case_id":"yhct-kham-104","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-104-1","resource_type":"other","source":"World Health Organization, WHO Child Growth Standards, 2006.","title":"World Health Organization, WHO Child Growth Standards, 2006.","organization":null,"year_version":null,"citation":"World Health Organization, WHO Child Growth Standards, 2006.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-104-2","resource_type":"other","source":"World Health Organization, WHO guideline on the prevention and management of wasting and nutritional oedema (acute malnutrition) in infants and children under 5 years, 2023.","title":"World Health Organization, WHO guideline on the prevention and management of wasting and nutritional oedema (acute malnutrition) in infants and children under 5 years, 2023.","organization":null,"year_version":null,"citation":"World Health Organization, WHO guideline on the prevention and management of wasting and nutritional oedema (acute malnutrition) in infants and children under 5 years, 2023.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,5],"examination_essential_indices":[0,1,3,4,5],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Biếng ăn, nhẹ cân thể vừa kèm thiếu máu thiếu sắt nhẹ do chế độ ăn và thói quen ăn uống","credit":"full"},{"text":"Suy dinh dưỡng cấp nặng","credit":"none"},{"text":"Bệnh celiac","credit":"none"},{"text":"Nhiễm giun","credit":"none"},{"text":"Lao","credit":"none"}],"bd":[{"text":"Cam tích","credit":"full"},{"text":"Tiết tả","credit":"none"},{"text":"Nhi hậu thiên bất túc","credit":"none"},{"text":"Phế ung","credit":"none"},{"text":"Hư lao","credit":"none"}],"bc":[{"text":"Lý – Hư – Hàn","credit":"full"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Hư – Hàn","credit":"none"},{"text":"Lý – Thực – Hàn","credit":"none"}],"the":[{"text":"Tỳ hư tích trệ","credit":"full"},{"text":"Tích trệ thực chứng","credit":"none"},{"text":"Can nhiệt phạm vị","credit":"none"},{"text":"Thận âm hư","credit":"none"},{"text":"Thấp nhiệt uẩn tỳ","credit":"none"}],"phap":[{"text":"Kiện tỳ ích khí, tiêu tích","credit":"full"},{"text":"Tả hạ công tích mạnh","credit":"none"},{"text":"Thanh nhiệt lợi thấp","credit":"none"},{"text":"Tư dưỡng can thận","credit":"none"},{"text":"Sơ can lý khí","credit":"none"}],"phuong":[{"text":"Tứ quân tử thang gia Sơn tra, Mạch nha","credit":"full"},{"text":"Bảo hòa hoàn","credit":"none"},{"text":"Đại thừa khí thang","credit":"none"},{"text":"Tiêu dao tán","credit":"none"},{"text":"Lục vị địa hoàng hoàn","credit":"none"}],"huyet":[{"text":"Tỳ du","credit":"full"},{"text":"Vị du","credit":"full"},{"text":"Túc tam lý","credit":"full"},{"text":"Trung quản","credit":"full"},{"text":"Tứ phùng","credit":"full"},{"text":"Thái dương","credit":"none"},{"text":"Thính cung","credit":"none"},{"text":"Hậu khê","credit":"none"},{"text":"Dương lăng tuyền","credit":"none"}]},"action_options":[{"text":"Đánh giá dinh dưỡng theo biểu đồ WHO (cân nặng theo tuổi, chiều cao theo tuổi, cân nặng theo chiều cao) và hỏi dấu hiệu suy dinh dưỡng nặng: phù, teo cơ rõ, vòng cánh tay dưới 11,5 cm","time_minutes":10,"grade":"recommended","rationale":"Phân loại mức độ để quyết định điều trị ngoại trú hay chuyển viện."},{"text":"Điều chỉnh chế độ ăn: bữa chính đúng giờ, bỏ vừa ăn vừa xem điện thoại, giảm sữa và bánh ngọt, thêm thịt cá trứng, rau, dầu mỡ","time_minutes":10,"grade":"recommended","rationale":"Nguyên nhân chủ yếu là thói quen ăn uống."},{"text":"Tẩy giun albendazole 400 mg liều duy nhất cho trẻ từ 24 tháng tuổi theo hướng dẫn chương trình tẩy giun định kỳ","time_minutes":3,"grade":"recommended","rationale":"Trẻ chưa từng tẩy giun, vùng lưu hành giun."},{"text":"Bổ sung sắt khi ferritin thấp theo liều nhi khoa (khoảng 2 mg sắt nguyên tố trên kg mỗi ngày), theo dõi Hb sau 4 đến 8 tuần","time_minutes":5,"grade":"recommended","rationale":"Hb 10,8 g/dL và ferritin thấp."},{"text":"Tứ quân tử thang gia Sơn tra, Mạch nha, sắc uống mỗi ngày 1 thang cho trẻ 3 tuổi: Đảng sâm 6 g, Bạch truật 6 g, Phục linh 6 g, Chích thảo 2 g, Sơn tra 5 g, Mạch nha 8 g (khoảng một phần ba liều người lớn)","time_minutes":10,"grade":"recommended","rationale":"Kiện tỳ ích khí, tiêu thực; liều giảm theo tuổi."},{"text":"Xoa bóp bấm huyệt hoặc châm nông không lưu kim Tỳ du, Vị du, Túc tam lý, Trung quản, Tứ phùng; có thể bóp sống lưng nhẹ","time_minutes":15,"grade":"recommended","rationale":"Kiện tỳ vị, giúp tiêu hóa; trẻ nhỏ không lưu kim."},{"text":"Chụp CT bụng và nội soi dạ dày","time_minutes":60,"grade":"waste","rationale":"Chưa có chỉ định, xâm lấn và phơi nhiễm bức xạ."},{"text":"Dùng thuốc tẩy tích mạnh (Đại hoàng, Khiên ngưu, Mang tiêu) hoặc thuốc kích thích thèm ăn tùy ý kéo dài","time_minutes":3,"grade":"harmful","rationale":"Gây mất nước, rối loạn điện giải, hao tổn chính khí ở trẻ đã yếu."},{"text":"Ép ăn, dọa dẫm hoặc dùng thuốc không rõ nguồn gốc, thuốc chứa chì, thủy ngân, hùng hoàng để chữa cam","time_minutes":3,"grade":"harmful","rationale":"Tác dụng độc hại cho trẻ nhỏ."}],"teaching_explanation":"Biếng ăn kéo dài ở trẻ nhỏ cần đánh giá bằng biểu đồ tăng trưởng WHO, loại trừ thiếu máu, thiếu vi chất, nhiễm giun và bệnh mạn tính; đa số do chế độ ăn và thói quen ăn. Cam tích thể Tỳ hư tích trệ: gầy, bụng to, phân nát có thức ăn chưa tiêu, lưỡi nhạt rêu dày, mạch tế hoãn, dùng Tứ quân tử thang gia Sơn tra, Mạch nha. Liều thuốc thang trẻ 3 tuổi khoảng một phần ba người lớn; tránh tẩy tích mạnh."}'::jsonb,
  '8095c4a775ce5867e59c7a28da58c52165669c3df18f06d616b6aebc006a4457'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'yhct-kham-105',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-105","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Bé trai 7 tuổi đái dầm hầu hết các đêm","setting":"chamcuu","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":7,"sex":"nam","patient_label":"Bé Trần Minh Khôi"},"presentation":{"intro":"Phòng châm cứu, Y học cổ truyền. Mẹ đưa bé Khôi, 7 tuổi, nặng 21 kg, đến khám vì đái dầm gần như mỗi đêm từ nhỏ, bé xấu hổ, không dám đi ngủ nhà bạn.","place":"Phòng châm cứu, Y học cổ truyền","clock":"16:00","night":false},"vitals":{"hr":92,"sbp":98,"dbp":60,"rr":20,"temperature_c":36.7,"spo2":99},"history":[{"question":"Bé đái dầm bao nhiêu đêm mỗi tuần? Đã bao giờ khô liên tục trên 6 tháng chưa?","response":"Khoảng 5 đến 6 đêm mỗi tuần, từ nhỏ chưa bao giờ khô liên tục trên 6 tháng."},{"question":"Ban ngày bé có tiểu gấp, tiểu nhiều lần, són tiểu, tiểu đau, tiểu buốt không?","response":"Ban ngày bình thường, không són, không tiểu gấp, không tiểu đau."},{"question":"Bé có khát nhiều, uống nhiều, tiểu nhiều, sụt cân không?","response":"Không khát nhiều, không sụt cân."},{"question":"Bé có táo bón, ngáy to, ngưng thở khi ngủ, ngủ rất say khó đánh thức không?","response":"Ngủ rất say, gọi khó dậy, ngáy nhẹ. Đại tiện 1 ngày 1 lần, phân mềm."},{"question":"Gia đình có ai từng đái dầm?","response":"Bố từng đái dầm đến 10 tuổi."},{"question":"Uống nước buổi tối, ăn mặn, nước ngọt, trước khi ngủ có đi tiểu không?","response":"Uống nhiều nước và sữa buổi tối, hay quên đi tiểu trước khi ngủ."},{"question":"Gia đình phản ứng thế nào khi bé đái dầm? Có mắng, phạt không? Có biến cố tâm lý gần đây không?","response":"Bố mẹ hay nhắc nhở, đôi khi mẹ mắng. Không có biến cố gần đây, bé xấu hổ."},{"question":"Sợ lạnh, tay chân lạnh, sắc mặt, ăn uống, nước tiểu trong hay vàng?","response":"Hay sợ lạnh, tay chân lạnh, nước tiểu trong nhiều, ăn ít, mệt mỏi, hay quên."}],"examination":[{"group":"V","item":"Thần sắc, thể trạng","finding":"Bé tỉnh, hơi nhợt, thể trạng trung bình, không phù."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, rêu trắng mỏng."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Giọng nói nhỏ, hơi thở bình thường."},{"group":"T","item":"Mạch","finding":"Mạch trầm nhược."},{"group":"K","item":"Khám bụng, hạ vị","finding":"Bụng mềm, hạ vị không căng, không sờ thấy khối, không khối phân."},{"group":"K","item":"Khám cột sống thắt lưng cùng, sinh dục ngoài","finding":"Không lúm da, không búi lông, không lệch cột sống, bao quy đầu và sinh dục ngoài bình thường."},{"group":"K","item":"Khám thần kinh chi dưới, đi lại","finding":"Phản xạ gân xương bình thường, sức cơ 5 trên 5, đi lại bình thường."}],"investigations":[{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Tỷ trọng 1,018, không đường, không protein, không bạch cầu, không nitrit."},{"name":"Đường huyết mao mạch","duration_minutes":10,"result":"4,9 mmol/L."},{"name":"Siêu âm hệ tiết niệu","duration_minutes":15,"result":"Thận hai bên bình thường, bàng quang thành mỏng, không tồn lưu nước tiểu sau tiểu."},{"name":"Nhật ký uống nước và đi tiểu trong 3 ngày","duration_minutes":10,"result":"Bé uống nhiều nước buổi tối, ban ngày tiểu 4 đến 5 lần."},{"name":"MRI cột sống thắt lưng cùng","duration_minutes":10,"result":"Không có chỉ định, khám thần kinh và da vùng cùng bình thường."},{"name":"Chụp bàng quang niệu đạo có cản quang, nội soi bàng quang","duration_minutes":20,"result":"Không có chỉ định, xâm lấn ở trẻ nhỏ."}],"choices":{"diagnosis":{"ydx":["Nhiễm trùng tiểu","Đái tháo đường típ 1","Bàng quang thần kinh","Ngưng thở khi ngủ","Đái dầm nguyên phát đơn triệu chứng"],"bd":["Tiểu bí","Tiêu khát","Lâm chứng","Tiểu nhiều lần","Di niệu"],"bc":["Lý – Hư – Hàn","Lý – Thực – Nhiệt","Biểu – Hư – Nhiệt","Lý – Thực – Hàn","Biểu – Thực – Hàn"],"the":["Thấp nhiệt hạ chú","Tâm thận bất giao","Can kinh uất nhiệt","Phế tỳ khí hư","Hạ nguyên hư hàn (Thận khí bất cố)"],"phap":["Bổ trung ích khí","Giao thông tâm thận","Sơ can thanh nhiệt","Thanh nhiệt lợi thấp","Ôn thận cố nhiếp, thu liễm chỉ di"],"phuong":["Bổ trung ích khí thang","Tang phiêu tiêu tán","Long đởm tả can thang","Bát chính tán","Hoàng liên a giao thang"],"huyet":["Thận du","Thái dương","Bàng quang du","Liệt khuyết","Quan nguyên","Phong trì","Trung cực","Tam âm giao","Thính cung"]},"actions":["Hỏi và khám tìm dấu hiệu thực thể: tiểu ban ngày, tiểu đau, khát nhiều, sụt cân, táo bón, ngáy nặng, bất thường cột sống, thần kinh","Giải thích cho cha mẹ và bé là bệnh không do lỗi của bé, không mắng phạt, khen thưởng khi có đêm khô","Tang phiêu tiêu tán gia giảm cho trẻ 7 tuổi, sắc uống mỗi ngày 1 thang: Tang phiêu tiêu 8 g, Long cốt 10 g sắc trước, Quy bản 8 g, Đảng sâm 8 g, Phục linh 8 g, Đương quy 6 g, Viễn chí 4 g, Thạch xương bồ 4 g (khoảng một nửa liều người lớn)","Xoa bóp bấm huyệt, cứu ấm hoặc châm nông không lưu kim Quan nguyên, Trung cực, Thận du, Bàng quang du, Tam âm giao","Điều chỉnh sinh hoạt: uống đủ nước ban ngày, giảm uống nước 1 đến 2 giờ trước ngủ, đi tiểu trước khi ngủ, tránh nước ngọt buổi tối, ghi nhật ký","Dùng desmopressin dạng xịt mũi hoặc không hạn chế uống nước buổi tối","Dùng báo động đái dầm là lựa chọn hàng đầu nếu gia đình chấp nhận, theo hướng dẫn nhi khoa","Chụp MRI cột sống và nội soi bàng quang ngay","Nếu cần, bác sĩ nhi có thể kê desmopressin 0,2 mg uống trước ngủ, hạn chế uống nước từ 1 giờ trước đến 8 giờ sau khi uống thuốc, không dùng khi bị sốt, tiêu chảy, nôn","Mắng, phạt, bắt nhịn tiểu hoặc cắt hạn chế nước cả ngày"]}}'::jsonb,
  'f8ac7777c08c6f5a7fdc761cc1c30ffda68f0055328b7095b6db3ff3e8345870'
)
