  '{"schema_version":"1.0.0","case_id":"yhct-kham-105","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-105-1","resource_type":"other","source":"Austin PF, et al., The standardization of terminology of lower urinary tract function in children and adolescents: Update report from the Standardization Committee of the International Children''s Continence Society, Neurourol Urodyn 2016;35:471-481.","title":"Austin PF, et al., The standardization of terminology of lower urinary tract function in children and adolescents: Update report from the Standardization Committee of the International Children''s Continence Society, Neurourol Urodyn 2016;35:471-481.","organization":null,"year_version":null,"citation":"Austin PF, et al., The standardization of terminology of lower urinary tract function in children and adolescents: Update report from the Standardization Committee of the International Children''s Continence Society, Neurourol Urodyn 2016;35:471-481.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-105-2","resource_type":"other","source":"National Institute for Health and Care Excellence, Bedwetting in under 19s, Clinical guideline CG111, 2010.","title":"National Institute for Health and Care Excellence, Bedwetting in under 19s, Clinical guideline CG111, 2010.","organization":null,"year_version":null,"citation":"National Institute for Health and Care Excellence, Bedwetting in under 19s, Clinical guideline CG111, 2010.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[1,3,4,5,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Đái dầm nguyên phát đơn triệu chứng","credit":"full"},{"text":"Đái tháo đường típ 1","credit":"none"},{"text":"Nhiễm trùng tiểu","credit":"none"},{"text":"Bàng quang thần kinh","credit":"none"},{"text":"Ngưng thở khi ngủ","credit":"none"}],"bd":[{"text":"Di niệu","credit":"full"},{"text":"Lâm chứng","credit":"none"},{"text":"Tiểu bí","credit":"none"},{"text":"Tiêu khát","credit":"none"},{"text":"Tiểu nhiều lần","credit":"none"}],"bc":[{"text":"Lý – Hư – Hàn","credit":"full"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Thực – Hàn","credit":"none"},{"text":"Biểu – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Hạ nguyên hư hàn (Thận khí bất cố)","credit":"full"},{"text":"Phế tỳ khí hư","credit":"none"},{"text":"Can kinh uất nhiệt","credit":"none"},{"text":"Thấp nhiệt hạ chú","credit":"none"},{"text":"Tâm thận bất giao","credit":"none"}],"phap":[{"text":"Ôn thận cố nhiếp, thu liễm chỉ di","credit":"full"},{"text":"Bổ trung ích khí","credit":"none"},{"text":"Thanh nhiệt lợi thấp","credit":"none"},{"text":"Sơ can thanh nhiệt","credit":"none"},{"text":"Giao thông tâm thận","credit":"none"}],"phuong":[{"text":"Tang phiêu tiêu tán","credit":"full"},{"text":"Bổ trung ích khí thang","credit":"none"},{"text":"Bát chính tán","credit":"none"},{"text":"Long đởm tả can thang","credit":"none"},{"text":"Hoàng liên a giao thang","credit":"none"}],"huyet":[{"text":"Quan nguyên","credit":"full"},{"text":"Trung cực","credit":"full"},{"text":"Thận du","credit":"full"},{"text":"Bàng quang du","credit":"full"},{"text":"Tam âm giao","credit":"full"},{"text":"Thái dương","credit":"none"},{"text":"Phong trì","credit":"none"},{"text":"Thính cung","credit":"none"},{"text":"Liệt khuyết","credit":"none"}]},"action_options":[{"text":"Hỏi và khám tìm dấu hiệu thực thể: tiểu ban ngày, tiểu đau, khát nhiều, sụt cân, táo bón, ngáy nặng, bất thường cột sống, thần kinh","time_minutes":5,"grade":"recommended","rationale":"Phân biệt đái dầm nguyên phát đơn triệu chứng với nguyên nhân thực thể."},{"text":"Giải thích cho cha mẹ và bé là bệnh không do lỗi của bé, không mắng phạt, khen thưởng khi có đêm khô","time_minutes":5,"grade":"recommended","rationale":"Yếu tố tâm lý và động viên rất quan trọng."},{"text":"Điều chỉnh sinh hoạt: uống đủ nước ban ngày, giảm uống nước 1 đến 2 giờ trước ngủ, đi tiểu trước khi ngủ, tránh nước ngọt buổi tối, ghi nhật ký","time_minutes":10,"grade":"recommended","rationale":"Giảm lượng nước tiểu ban đêm."},{"text":"Dùng báo động đái dầm là lựa chọn hàng đầu nếu gia đình chấp nhận, theo hướng dẫn nhi khoa","time_minutes":5,"grade":"recommended","rationale":"Hiệu quả lâu dài tốt, ít tác dụng phụ."},{"text":"Nếu cần, bác sĩ nhi có thể kê desmopressin 0,2 mg uống trước ngủ, hạn chế uống nước từ 1 giờ trước đến 8 giờ sau khi uống thuốc, không dùng khi bị sốt, tiêu chảy, nôn","time_minutes":3,"grade":"recommended","rationale":"Tránh hạ natri máu do giữ nước."},{"text":"Tang phiêu tiêu tán gia giảm cho trẻ 7 tuổi, sắc uống mỗi ngày 1 thang: Tang phiêu tiêu 8 g, Long cốt 10 g sắc trước, Quy bản 8 g, Đảng sâm 8 g, Phục linh 8 g, Đương quy 6 g, Viễn chí 4 g, Thạch xương bồ 4 g (khoảng một nửa liều người lớn)","time_minutes":10,"grade":"recommended","rationale":"Ôn thận cố nhiếp; liều giảm theo tuổi."},{"text":"Xoa bóp bấm huyệt, cứu ấm hoặc châm nông không lưu kim Quan nguyên, Trung cực, Thận du, Bàng quang du, Tam âm giao","time_minutes":15,"grade":"recommended","rationale":"Ôn thận, điều hòa bàng quang; trẻ nhỏ châm nông, không lưu kim."},{"text":"Chụp MRI cột sống và nội soi bàng quang ngay","time_minutes":60,"grade":"waste","rationale":"Không có chỉ định ở đái dầm nguyên phát đơn triệu chứng."},{"text":"Mắng, phạt, bắt nhịn tiểu hoặc cắt hạn chế nước cả ngày","time_minutes":2,"grade":"harmful","rationale":"Gây tổn thương tâm lý, làm nặng bệnh, mất nước."},{"text":"Dùng desmopressin dạng xịt mũi hoặc không hạn chế uống nước buổi tối","time_minutes":3,"grade":"harmful","rationale":"Nguy cơ hạ natri máu, co giật."}],"teaching_explanation":"Đái dầm nguyên phát đơn triệu chứng: trẻ từ 5 tuổi, đái dầm ban đêm, chưa từng khô liên tục trên 6 tháng, không triệu chứng tiểu ban ngày, khám và nước tiểu bình thường. Điều trị bằng giải thích, liệu pháp hành vi, báo động, và desmopressin khi cần với hạn chế dịch. Thể Hạ nguyên hư hàn: sợ lạnh, tiểu trong nhiều, lưỡi nhạt, mạch trầm nhược, dùng Tang phiêu tiêu tán. Liều thuốc thang trẻ 7 tuổi khoảng một nửa người lớn."}'::jsonb,
  '1996437978786a011ddbb04877b67c9f0c50e8433ed0ea1f6484efb11964acf6'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'yhct-kham-106',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-106","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nữ 34 tuổi nổi mề đay ngứa gần như mỗi ngày suốt 3 tháng","setting":"phongkham","level":"Khó","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":34,"sex":"nữ","patient_label":"Võ Thị Lan"},"presentation":{"intro":"Phòng khám Y học cổ truyền. Chị Lan là kế toán, đến khám vì nổi các mảng đỏ phù ngứa gần như mỗi ngày suốt 3 tháng, uống loratadin chỉ đỡ phần nào, nặng hơn khi gặp gió lạnh và điều hòa.","place":"Phòng khám Y học cổ truyền","clock":"15:30","night":false},"vitals":{"hr":78,"sbp":112,"dbp":70,"rr":16,"temperature_c":36.7,"spo2":99},"history":[{"question":"Mẩn ngứa xuất hiện thế nào, mỗi sẩn tồn tại bao lâu, có để lại vết thâm, đau rát không?","response":"Nổi các mảng đỏ nhạt phù, ngứa nhiều, mỗi mảng tồn tại vài giờ rồi tự biến mất, không để lại vết, không đau rát. Gần như ngày nào cũng nổi, 3 tháng nay."},{"question":"Có yếu tố khởi phát: thức ăn, thuốc (NSAID, thuốc huyết áp), nhiễm trùng, gió lạnh, nóng, mồ hôi, đè ép, căng thẳng?","response":"Nặng hơn khi gió lạnh, điều hòa, sáng sớm và khi căng thẳng. Không liên quan rõ thức ăn, không dùng thuốc giảm đau."},{"question":"Có sưng môi, mí mắt, lưỡi, khó nuốt, khàn tiếng, khó thở, tức ngực không?","response":"Không sưng môi mặt, không khó thở."},{"question":"Có sốt, đau khớp, mệt, sụt cân, đau bụng, nước tiểu thay đổi không?","response":"Không sốt, không đau khớp, không sụt cân."},{"question":"Thuốc đã dùng: kháng histamin, corticoid, thuốc nam không rõ nguồn gốc?","response":"Uống loratadin 10 mg mỗi ngày, đỡ ít. Không dùng corticoid, không dùng thuốc nam."},{"question":"Kinh nguyệt, có thai hay dự định mang thai, cho con bú không?","response":"Kinh đều, không có thai, không dự định có thai trong năm nay, không cho con bú."},{"question":"Ra mồ hôi, dễ cảm cúm, sợ gió, ăn ngủ thế nào?","response":"Hay ra mồ hôi, dễ cảm, sợ gió lạnh, ăn bình thường, ngủ kém khi ngứa."},{"question":"Tiền sử bản thân và gia đình: dị ứng, hen, viêm mũi dị ứng, bệnh tuyến giáp, bệnh tự miễn?","response":"Có viêm mũi dị ứng nhẹ. Mẹ bị bệnh tuyến giáp."}],"examination":[{"group":"V","item":"Da, dát sẩn","finding":"Vài mảng sẩn phù hồng nhạt ở thân mình và cánh tay, ranh giới rõ, không đau, không tím, không bọng nước."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, rêu trắng mỏng."},{"group":"M","item":"Giọng nói","finding":"Giọng nói bình thường, không khàn."},{"group":"T","item":"Mạch","finding":"Mạch phù hoãn nhược."},{"group":"K","item":"Dấu da vẽ nổi","finding":"Vạch nhẹ trên da xuất hiện vệt đỏ nổi sau 1 phút, ngứa."},{"group":"K","item":"Khám tim phổi, bụng, hạch, tuyến giáp","finding":"Tim phổi bình thường, bụng mềm, không hạch, tuyến giáp không to."},{"group":"K","item":"Phù mạch, đường thở","finding":"Không sưng môi, mí, lưỡi, họng thông."}],"investigations":[{"name":"Công thức máu, tốc độ máu lắng, CRP","duration_minutes":10,"result":"Bạch cầu 7,2 G/L, bạch cầu ái toan không tăng, CRP và máu lắng bình thường."},{"name":"TSH và kháng thể kháng TPO","duration_minutes":10,"result":"TSH bình thường, kháng thể kháng TPO tăng nhẹ."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Bình thường."},{"name":"Sinh thiết da","duration_minutes":10,"result":"Chỉ định khi sẩn tồn tại trên 24 giờ, đau rát, để lại vết tím gợi viêm mạch, không phù hợp ca này."},{"name":"Xét nghiệm IgE đặc hiệu hàng loạt thực phẩm và hô hấp thường quy","duration_minutes":10,"result":"Không có chỉ định thường quy ở mày đay mạn không liên quan thức ăn."}],"choices":{"diagnosis":{"ydx":["Dị ứng thức ăn cấp","Phù mạch di truyền","Mày đay mạn tự phát, mức độ vừa","Ghẻ","Viêm mạch mày đay"],"bd":["Ma chẩn","Thấp sang","Ẩn chẩn","Đan độc","Hư lao"],"bc":["Lý – Hư – Hàn","Biểu – Thực – Hàn","Biểu – Hư – Hàn","Biểu – Thực – Nhiệt","Lý – Thực – Nhiệt"],"the":["Vị tràng thấp nhiệt","Huyết hư phong táo","Phong nhiệt phạm biểu","Vệ biểu bất cố, phong hàn lưu biểu","Huyết nhiệt"],"phap":["Dưỡng huyết nhuận táo","Ích khí cố biểu, điều hòa vinh vệ, khu phong chỉ dưỡng","Lương huyết giải độc","Sơ phong thanh nhiệt","Thanh nhiệt lợi thấp"],"phuong":["Quế chi thang hợp Ngọc bình phong tán","Ngân kiều tán","Tứ vật tiêu phong ẩm","Tang cúc ẩm","Tê giác địa hoàng thang"],"huyet":["Khúc trì","Thính cung","Phong trì","Huyết hải","Túc tam lý","Hoàn khiêu","Dương lăng tuyền","Tam âm giao","Thái dương"]},"actions":["Quế chi thang hợp Ngọc bình phong tán sắc uống mỗi ngày một thang: Quế chi 8 g, Bạch thược 12 g, Chích thảo 6 g, Sinh khương 3 lát, Đại táo 4 quả, Hoàng kỳ 20 g, Bạch truật 12 g, Phòng phong 10 g","Dùng thuốc có Ma hoàng liều cao hoặc thuốc ức chế men chuyển, NSAID khi chưa đánh giá yếu tố khởi phát","Dùng corticoid toàn thân kéo dài hoặc thuốc nam, thuốc gia truyền không rõ nguồn gốc để kiểm soát mày đay","Tránh yếu tố khởi phát: gió lạnh, điều hòa quá lạnh, căng thẳng, thuốc NSAID, rượu bia","Châm cứu Khúc trì, Huyết hải, Phong trì, Túc tam lý, Tam âm giao, lưu kim 20 phút, hỏi chắc không có thai trước khi châm Tam âm giao","Kháng histamin H1 thế hệ hai dùng đều mỗi ngày (loratadin 10 mg hoặc cetirizin 10 mg); nếu chưa kiểm soát sau 2 đến 4 tuần, bác sĩ chuyên khoa có thể tăng liều đến gấp 4 theo hướng dẫn quốc tế","Xác định đây là mày đay mạn, đánh giá mức độ bằng nhật ký triệu chứng hoặc thang UAS7 và hỏi dấu hiệu viêm mạch, phù mạch","Hướng dẫn dấu hiệu cần đi cấp cứu: sưng môi, lưỡi, khó nuốt, khàn tiếng, khó thở, tức ngực","Làm sinh thiết da và IgE đặc hiệu hàng loạt thường quy"]}}'::jsonb,
  '122c959dd521a9c7e02015d8ac4152eb85a4e507b1417f671f0c1bdd49730ed0'
)
