  'yhct-kham-106',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-106","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-106-1","resource_type":"other","source":"Zuberbier T, et al., The international EAACI/GA2LEN/EuroGuiDerm/APAAACI guideline for the definition, classification, diagnosis, and management of urticaria, Allergy 2022;77:734-766.","title":"Zuberbier T, et al., The international EAACI/GA2LEN/EuroGuiDerm/APAAACI guideline for the definition, classification, diagnosis, and management of urticaria, Allergy 2022;77:734-766.","organization":null,"year_version":null,"citation":"Zuberbier T, et al., The international EAACI/GA2LEN/EuroGuiDerm/APAAACI guideline for the definition, classification, diagnosis, and management of urticaria, Allergy 2022;77:734-766.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,3,4,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"waste"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Mày đay mạn tự phát, mức độ vừa","credit":"full"},{"text":"Viêm mạch mày đay","credit":"none"},{"text":"Phù mạch di truyền","credit":"none"},{"text":"Dị ứng thức ăn cấp","credit":"none"},{"text":"Ghẻ","credit":"none"}],"bd":[{"text":"Ẩn chẩn","credit":"full"},{"text":"Ma chẩn","credit":"none"},{"text":"Đan độc","credit":"none"},{"text":"Thấp sang","credit":"none"},{"text":"Hư lao","credit":"none"}],"bc":[{"text":"Biểu – Hư – Hàn","credit":"full"},{"text":"Biểu – Thực – Nhiệt","credit":"none"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"}],"the":[{"text":"Vệ biểu bất cố, phong hàn lưu biểu","credit":"full"},{"text":"Phong nhiệt phạm biểu","credit":"none"},{"text":"Vị tràng thấp nhiệt","credit":"none"},{"text":"Huyết hư phong táo","credit":"none"},{"text":"Huyết nhiệt","credit":"none"}],"phap":[{"text":"Ích khí cố biểu, điều hòa vinh vệ, khu phong chỉ dưỡng","credit":"full"},{"text":"Sơ phong thanh nhiệt","credit":"none"},{"text":"Thanh nhiệt lợi thấp","credit":"none"},{"text":"Dưỡng huyết nhuận táo","credit":"none"},{"text":"Lương huyết giải độc","credit":"none"}],"phuong":[{"text":"Quế chi thang hợp Ngọc bình phong tán","credit":"full"},{"text":"Ngân kiều tán","credit":"none"},{"text":"Tang cúc ẩm","credit":"none"},{"text":"Tứ vật tiêu phong ẩm","credit":"none"},{"text":"Tê giác địa hoàng thang","credit":"none"}],"huyet":[{"text":"Khúc trì","credit":"full"},{"text":"Huyết hải","credit":"full"},{"text":"Phong trì","credit":"full"},{"text":"Túc tam lý","credit":"full"},{"text":"Tam âm giao","credit":"full"},{"text":"Thái dương","credit":"none"},{"text":"Thính cung","credit":"none"},{"text":"Hoàn khiêu","credit":"none"},{"text":"Dương lăng tuyền","credit":"none"}]},"action_options":[{"text":"Xác định đây là mày đay mạn, đánh giá mức độ bằng nhật ký triệu chứng hoặc thang UAS7 và hỏi dấu hiệu viêm mạch, phù mạch","time_minutes":10,"grade":"recommended","rationale":"Phân loại để chọn bước điều trị và theo dõi đáp ứng."},{"text":"Tránh yếu tố khởi phát: gió lạnh, điều hòa quá lạnh, căng thẳng, thuốc NSAID, rượu bia","time_minutes":5,"grade":"recommended","rationale":"Giảm tần suất và mức độ nổi mẩn."},{"text":"Kháng histamin H1 thế hệ hai dùng đều mỗi ngày (loratadin 10 mg hoặc cetirizin 10 mg); nếu chưa kiểm soát sau 2 đến 4 tuần, bác sĩ chuyên khoa có thể tăng liều đến gấp 4 theo hướng dẫn quốc tế","time_minutes":3,"grade":"recommended","rationale":"Liệu pháp nền theo hướng dẫn mày đay mạn; tăng liều là chỉ định ngoài nhãn do bác sĩ quyết định."},{"text":"Quế chi thang hợp Ngọc bình phong tán sắc uống mỗi ngày một thang: Quế chi 8 g, Bạch thược 12 g, Chích thảo 6 g, Sinh khương 3 lát, Đại táo 4 quả, Hoàng kỳ 20 g, Bạch truật 12 g, Phòng phong 10 g","time_minutes":10,"grade":"recommended","rationale":"Ích khí cố biểu, điều hòa vinh vệ."},{"text":"Châm cứu Khúc trì, Huyết hải, Phong trì, Túc tam lý, Tam âm giao, lưu kim 20 phút, hỏi chắc không có thai trước khi châm Tam âm giao","time_minutes":25,"grade":"recommended","rationale":"Điều hòa khí huyết, khu phong chỉ dưỡng."},{"text":"Hướng dẫn dấu hiệu cần đi cấp cứu: sưng môi, lưỡi, khó nuốt, khàn tiếng, khó thở, tức ngực","time_minutes":3,"grade":"recommended","rationale":"Phù mạch thanh quản đe dọa tính mạng."},{"text":"Làm sinh thiết da và IgE đặc hiệu hàng loạt thường quy","time_minutes":40,"grade":"waste","rationale":"Không có chỉ định ở ca này."},{"text":"Dùng corticoid toàn thân kéo dài hoặc thuốc nam, thuốc gia truyền không rõ nguồn gốc để kiểm soát mày đay","time_minutes":3,"grade":"harmful","rationale":"Phụ thuộc corticoid, tác dụng phụ, có thể bị trộn corticoid ẩn."},{"text":"Dùng thuốc có Ma hoàng liều cao hoặc thuốc ức chế men chuyển, NSAID khi chưa đánh giá yếu tố khởi phát","time_minutes":3,"grade":"harmful","rationale":"Có thể làm nặng mày đay hoặc tăng huyết áp, tim nhanh."}],"teaching_explanation":"Mày đay mạn tự phát: sẩn phù ngứa tái phát trên 6 tuần, mỗi sẩn tồn tại dưới 24 giờ, không để lại vết. Dấu hiệu gợi ý viêm mạch mày đay: sẩn tồn tại trên 24 giờ, đau rát, để lại vết thâm. Điều trị nền bằng kháng histamin H1 thế hệ hai, tăng liều theo hướng dẫn nếu chưa kiểm soát. Thể Vệ biểu bất cố kiêm phong hàn: nổi mẩn khi gặp lạnh, hay ra mồ hôi, dễ cảm, lưỡi nhạt, mạch phù hoãn nhược. Cần hướng dẫn dấu hiệu phù mạch cấp cứu."}'::jsonb,
  '71cabba7c498adbf8640bda792a84f93dbf2784cb384cce35ef809b9b8ac3601'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'yhct-kham-107',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-107","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nữ 41 tuổi mệt mỏi, hồi hộp, chóng mặt, kinh nhiều kéo dài","setting":"phongkham","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":41,"sex":"nữ","patient_label":"Đỗ Thị Hạnh"},"presentation":{"intro":"Phòng khám Y học cổ truyền. Chị Hạnh là giáo viên, đến khám vì mệt mỏi, hồi hộp, chóng mặt, hoa mắt khoảng 4 tháng, kinh nguyệt ra nhiều kéo dài, ăn ngủ kém, hay quên.","place":"Phòng khám Y học cổ truyền","clock":"08:50","night":false},"vitals":{"hr":96,"sbp":100,"dbp":62,"rr":18,"temperature_c":36.6,"spo2":98},"history":[{"question":"Mệt mỏi từ bao giờ, mức độ, có ảnh hưởng công việc, hoa mắt, chóng mặt khi đứng dậy, ngất không?","response":"Mệt khoảng 4 tháng, đi lên cầu thang phải nghỉ, hay chóng mặt hoa mắt khi đứng dậy, chưa ngất."},{"question":"Kinh nguyệt: chu kỳ, số ngày hành kinh, lượng kinh, có máu cục không?","response":"Chu kỳ 26 ngày, hành kinh 7 đến 8 ngày, dùng 8 đến 10 băng vệ sinh mỗi ngày, có máu cục, 6 tháng nay nhiều hơn."},{"question":"Có đi ngoài phân đen, ra máu, nôn máu, đau bụng, trĩ, bệnh dạ dày không?","response":"Không có, không đau dạ dày."},{"question":"Có hồi hộp, khó thở khi gắng sức, đau ngực không?","response":"Hồi hộp, thở nhanh khi leo cầu thang, không đau ngực."},{"question":"Có rụng tóc, móng giòn, thèm ăn đá, lạnh tay chân, da khô không?","response":"Rụng tóc nhiều, móng giòn, da khô, tay chân lạnh."},{"question":"Chế độ ăn: thịt đỏ, rau, trà cà phê sau bữa ăn?","response":"Ăn ít thịt đỏ, hay uống trà sau bữa ăn, ăn chay vài ngày mỗi tuần."},{"question":"Có sụt cân, sốt, ra mồ hôi đêm, khó ngủ, buồn bã, mất hứng thú không?","response":"Không sụt cân, không sốt, ngủ kém, hay quên, hơi lo lắng, không thấy buồn chán."},{"question":"Tiền sử bệnh: thiếu máu, bệnh tuyến giáp, bệnh thận, bệnh phụ khoa, gia đình thalassemia? Đang dùng thuốc gì?","response":"Chưa từng được chẩn đoán thiếu máu. Không bệnh khác, không dùng thuốc thường xuyên. Gia đình không ai bị thalassemia."},{"question":"Ăn uống, đại tiểu tiện, tinh thần theo YHCT?","response":"Ăn kém, đại tiện nát, hay ra mồ hôi, sắc mặt vàng nhợt."}],"examination":[{"group":"V","item":"Thần sắc, da niêm mạc","finding":"Mặt xanh vàng nhợt, kết mạc và môi nhạt, da khô, tóc thưa."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt bệu, rêu trắng mỏng."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Giọng nói nhỏ, thở ngắn khi nói dài."},{"group":"T","item":"Mạch","finding":"Mạch tế nhược."},{"group":"K","item":"Khám tim phổi","finding":"Nhịp tim nhanh đều 96 lần phút, âm thổi tâm thu cơ năng nhẹ, phổi trong."},{"group":"K","item":"Khám bụng, gan lách, hạ vị","finding":"Bụng mềm, gan lách không to, không đau, không khối."},{"group":"K","item":"Khám móng, đầu chi","finding":"Móng giòn lõm, tay chân mát."}],"investigations":[{"name":"Công thức máu","duration_minutes":10,"result":"Hb 8,9 g/dL, MCV 71 fL, hồng cầu nhỏ nhược sắc, tiểu cầu 410 G/L."},{"name":"Ferritin huyết thanh","duration_minutes":10,"result":"6 ng/mL."},{"name":"Siêu âm tử cung phần phụ","duration_minutes":15,"result":"Một u cơ tử cung 25 mm dưới thanh mạc, không biến dạng buồng tử cung, nội mạc 10 mm."},{"name":"TSH máu","duration_minutes":10,"result":"Bình thường."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp xoang nhanh nhẹ, không bất thường khác."},{"name":"Truyền khối hồng cầu","duration_minutes":10,"result":"Không có chỉ định ở Hb 8,9 g/dL, huyết động ổn định, thiếu máu mạn."},{"name":"Tủy đồ","duration_minutes":10,"result":"Không có chỉ định, thiếu máu rõ do thiếu sắt."}],"choices":{"diagnosis":{"ydx":["Thalassemia thể nhẹ","Thiếu máu thiếu sắt mức vừa do rong kinh, nghi u cơ tử cung","Trầm cảm","Suy giáp","Thiếu máu do bệnh mạn tính"],"bd":["Tâm quý","Hư lao","Huyễn vựng","Bất mị","Hiếp thống"],"bc":["Biểu – Hư – Nhiệt","Biểu – Thực – Hàn","Lý – Hư – Nhiệt","Lý – Hư – Hàn","Lý – Thực – Nhiệt"],"the":["Can thận âm hư","Tỳ thận dương hư","Âm hư nội nhiệt","Khí huyết lưỡng hư","Tâm tỳ lưỡng hư"],"phap":["Bổ ích khí huyết","Kiện tỳ dưỡng tâm","Tư bổ can thận","Ôn bổ tỳ thận","Tư âm thanh nhiệt"],"phuong":["Quy tỳ thang","Lục vị địa hoàng hoàn","Tứ vật thang","Thập toàn đại bổ thang","Bát trân thang"],"huyet":["Tam âm giao","Khí hải","Hoàn khiêu","Cách du","Tỳ du","Thính cung","Túc tam lý","Liệt khuyết","Thái dương"]},"actions":["Bát trân thang gia giảm sắc uống mỗi ngày một thang, dùng khi hết kinh: Đảng sâm 12 g, Bạch truật 12 g, Phục linh 12 g, Chích thảo 6 g, Đương quy 12 g, Xuyên khung 6 g, Bạch thược 12 g, Thục địa 12 g, Sinh khương 3 lát, Đại táo 3 quả","Chỉ dùng thuốc bổ mà không tìm nguyên nhân mất máu, không bổ sung sắt","Làm công thức máu, ferritin, siêu âm tử cung phần phụ để tìm nguyên nhân mất máu","Dùng thuốc hoạt huyết mạnh (Đào nhân, Hồng hoa, Xuyên khung liều cao) trong lúc kinh ra nhiều","Sắt uống khoảng 60 mg sắt nguyên tố một lần mỗi ngày hoặc cách ngày, uống xa bữa ăn, xa trà và canxi; tái khám công thức máu sau 4 tuần, tiếp tục thêm 3 tháng sau khi Hb bình thường","Hỏi tìm dấu hiệu nặng: ngất, đau ngực, khó thở lúc nghỉ, xuất huyết tiêu hóa, rong kinh ồ ạt","Giới thiệu khám phụ khoa để đánh giá rong kinh và u cơ tử cung","Truyền khối hồng cầu và làm tủy đồ","Châm hoặc cứu Túc tam lý, Tam âm giao, Khí hải, Tỳ du, Cách du, lưu kim 20 phút"]}}'::jsonb,
  '9134e79f5e09cb35f3d27cc132c630066e87e10b94f39833c711c3d4f5d51bad'
)
