  '{"schema_version":"1.0.0","case_id":"yhct-kham-107","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ida-camaschella-2015-26935e2f4e8d","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/25946282/","title":"Camaschella C, Iron-deficiency anemia, N Engl J Med 2015;372:1832-1843.","organization":null,"year_version":null,"citation":"Camaschella C, Iron-deficiency anemia, N Engl J Med 2015;372:1832-1843.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-yhct-kham-107-2","resource_type":"other","source":"World Health Organization, Haemoglobin concentrations for the diagnosis of anaemia and assessment of severity, 2011.","title":"World Health Organization, Haemoglobin concentrations for the diagnosis of anaemia and assessment of severity, 2011.","organization":null,"year_version":null,"citation":"World Health Organization, Haemoglobin concentrations for the diagnosis of anaemia and assessment of severity, 2011.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,3,4,5],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Thiếu máu thiếu sắt mức vừa do rong kinh, nghi u cơ tử cung","credit":"full"},{"text":"Suy giáp","credit":"none"},{"text":"Thalassemia thể nhẹ","credit":"none"},{"text":"Thiếu máu do bệnh mạn tính","credit":"none"},{"text":"Trầm cảm","credit":"none"}],"bd":[{"text":"Hư lao","credit":"full"},{"text":"Huyễn vựng","credit":"none"},{"text":"Bất mị","credit":"none"},{"text":"Tâm quý","credit":"none"},{"text":"Hiếp thống","credit":"none"}],"bc":[{"text":"Lý – Hư – Hàn","credit":"full"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Biểu – Hư – Nhiệt","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Khí huyết lưỡng hư","credit":"full"},{"text":"Tâm tỳ lưỡng hư","credit":"none"},{"text":"Can thận âm hư","credit":"none"},{"text":"Tỳ thận dương hư","credit":"none"},{"text":"Âm hư nội nhiệt","credit":"none"}],"phap":[{"text":"Bổ ích khí huyết","credit":"full"},{"text":"Kiện tỳ dưỡng tâm","credit":"none"},{"text":"Tư bổ can thận","credit":"none"},{"text":"Ôn bổ tỳ thận","credit":"none"},{"text":"Tư âm thanh nhiệt","credit":"none"}],"phuong":[{"text":"Bát trân thang","credit":"full"},{"text":"Thập toàn đại bổ thang","credit":"partial"},{"text":"Quy tỳ thang","credit":"none"},{"text":"Lục vị địa hoàng hoàn","credit":"none"},{"text":"Tứ vật thang","credit":"none"}],"huyet":[{"text":"Túc tam lý","credit":"full"},{"text":"Tam âm giao","credit":"full"},{"text":"Khí hải","credit":"full"},{"text":"Tỳ du","credit":"full"},{"text":"Cách du","credit":"full"},{"text":"Thái dương","credit":"none"},{"text":"Thính cung","credit":"none"},{"text":"Liệt khuyết","credit":"none"},{"text":"Hoàn khiêu","credit":"none"}]},"action_options":[{"text":"Hỏi tìm dấu hiệu nặng: ngất, đau ngực, khó thở lúc nghỉ, xuất huyết tiêu hóa, rong kinh ồ ạt","time_minutes":5,"grade":"recommended","rationale":"Quyết định chuyển viện cấp cứu hay điều trị ngoại trú."},{"text":"Làm công thức máu, ferritin, siêu âm tử cung phần phụ để tìm nguyên nhân mất máu","time_minutes":30,"grade":"recommended","rationale":"Xác nhận thiếu máu thiếu sắt và nguyên nhân do rong kinh."},{"text":"Sắt uống khoảng 60 mg sắt nguyên tố một lần mỗi ngày hoặc cách ngày, uống xa bữa ăn, xa trà và canxi; tái khám công thức máu sau 4 tuần, tiếp tục thêm 3 tháng sau khi Hb bình thường","time_minutes":5,"grade":"recommended","rationale":"Bù sắt là điều trị nền, cần đủ thời gian để bù kho dự trữ."},{"text":"Giới thiệu khám phụ khoa để đánh giá rong kinh và u cơ tử cung","time_minutes":5,"grade":"recommended","rationale":"Điều trị nguyên nhân mất máu."},{"text":"Bát trân thang gia giảm sắc uống mỗi ngày một thang, dùng khi hết kinh: Đảng sâm 12 g, Bạch truật 12 g, Phục linh 12 g, Chích thảo 6 g, Đương quy 12 g, Xuyên khung 6 g, Bạch thược 12 g, Thục địa 12 g, Sinh khương 3 lát, Đại táo 3 quả","time_minutes":10,"grade":"recommended","rationale":"Bổ khí huyết; trong kỳ kinh nhiều giảm hoặc bỏ Xuyên khung, thêm A giao, Ngải diệp theo chỉ định."},{"text":"Châm hoặc cứu Túc tam lý, Tam âm giao, Khí hải, Tỳ du, Cách du, lưu kim 20 phút","time_minutes":25,"grade":"recommended","rationale":"Bổ khí huyết, kiện tỳ."},{"text":"Truyền khối hồng cầu và làm tủy đồ","time_minutes":120,"grade":"waste","rationale":"Không có chỉ định ở Hb 8,9 g/dL huyết động ổn định."},{"text":"Chỉ dùng thuốc bổ mà không tìm nguyên nhân mất máu, không bổ sung sắt","time_minutes":3,"grade":"harmful","rationale":"Bỏ sót rong kinh, u cơ tử cung, làm thiếu máu nặng thêm."},{"text":"Dùng thuốc hoạt huyết mạnh (Đào nhân, Hồng hoa, Xuyên khung liều cao) trong lúc kinh ra nhiều","time_minutes":3,"grade":"harmful","rationale":"Làm tăng mất máu, nặng thêm thiếu máu."}],"teaching_explanation":"Mệt, hồi hộp, chóng mặt ở phụ nữ rong kinh cần làm công thức máu và ferritin; Hb 8,9 g/dL, MCV thấp, ferritin thấp là thiếu máu thiếu sắt, phải tìm nguyên nhân mất máu (rong kinh, u cơ tử cung, xuất huyết tiêu hóa). Điều trị bằng sắt uống đủ thời gian và xử trí nguyên nhân. Thể Khí huyết lưỡng hư: mệt, hồi hộp, chóng mặt, sắc mặt nhợt, lưỡi nhạt, mạch tế nhược, dùng Bát trân thang; thận trọng thuốc hoạt huyết khi kinh ra nhiều. Chuyển tuyến khi Hb dưới 7 g/dL hoặc có triệu chứng nặng."}'::jsonb,
